// a bystander's glance. The verb is the same, the social weight is not.
func (s *TurnService) applyTransform(ctx context.Context, tc *turnContext, evt *event.GameEvent, v *verdict, deed string) {
	hazard := entity.IsHazardEffect(v.effect)
	if s.mutator != nil {
		note := entity.EffectNote(v.effect)
		if _, err := s.mutator.ApplyEffect(ctx, v.targetEnt.ID, v.effect, note, tc.tick); err != nil {
			s.logger.Warn("transform mutation failed", zap.String("entity", v.targetEnt.Name), zap.Error(err))
		}
	}

	// A neutral, harmless change earns a glance and a memory, nothing heavier.
	if !v.hostile && !hazard {
		for _, w := range tc.coLocated() {
			s.formMemory(ctx, tc, evt, w, fmt.Sprintf("%s на моих глазах: «%s»", tc.player.Identity.Name, deed))
		}
		return
	}

	playerName := tc.player.Identity.Name
	// The owner of the ruined thing, if standing right here, is the personally
	// wronged party — handled apart from the onlookers, as applyHostility handles
	// an assault's victim. An absent owner's grievance on later discovery is a
	// future mechanic, as it is on the take-path.
	var ownerID *domain.ActorID
	if id := s.ownerOf(ctx, v.targetEnt); id != nil {
		if owner := tc.actorByID(*id); owner != nil && owner.GetCurrentLocation() == tc.player.GetCurrentLocation() {
			ownerID = id
		}
	}

	for _, w := range tc.coLocated() {
		if ownerID != nil && w.ID == *ownerID {
			continue // wronged personally below, not a mere onlooker
		}
		guard := isGuard(w)
		if s.behavior != nil {
			if guard {
				// The law hardens at a crime, it does not cower — resolve, not dread.
				s.applyImpulse(ctx, tc, w, map[actor.EmotionType]float32{actor.EmotionAnger: 0.65})
			} else {
				s.applyImpulse(ctx, tc, w, map[actor.EmotionType]float32{actor.EmotionFear: 0.6, actor.EmotionAnxiety: 0.5})
			}
		}
		// A hazard (arson) leaves a bystander LASTING fear of the player, exactly as a
		// blow does — otherwise the city forgets the arsonist the moment the flames die;
		// the catalogue carries that fear for a non-guard onlooker, zero for a guard (who
		// answers with resolve, not cowering) and zero for a harmless transform (a smashed
		// mug frightens no one into lasting fear). A guard's lasting mark is a lawman's
		// grievance, set apart on the same live relationship the delta then persists.
		if guard {
			actor.MarkCrimeWitnessed(w, tc.player.ID) // the law remembers — confronts on sight
		}
		s.applyRelDelta(ctx, tc, w, relationshipConsequence(roleHazardOnlooker, hazard, guard), "погром")
		mem := fmt.Sprintf("%s у всех на глазах решается на «%s» — и доводит дело до конца", playerName, deed)
		if guard {
			mem = fmt.Sprintf("На моих глазах преступление: %s — «%s»", playerName, deed)
		}
		s.formMemory(ctx, tc, evt, w, mem)
	}

	// The owner takes the full relationship damage and a lasting wariness of the
	// one who ruined their property — anger first (it is their loss), and the
	// world remembers it as personal, not as something they merely watched. A
	// GUARD owner is still the law: they harden into a confronting grievance
	// (anger, no cowering fear), not the dread a townsperson carries — otherwise
	// destroying a guard's own thing would make the watch trail off in fear,
	// against the «law hardens, it does not cower» invariant.
	if ownerID != nil {
		owner := tc.actorByID(*ownerID)
		guard := isGuard(owner)
		if s.behavior != nil {
			impulse := map[actor.EmotionType]float32{actor.EmotionAnger: 0.6, actor.EmotionFear: 0.4}
			if guard {
				impulse = map[actor.EmotionType]float32{actor.EmotionAnger: 0.65}
			}
			s.applyImpulse(ctx, tc, owner, impulse)
		}
		if guard {
			actor.MarkCrimeWitnessed(owner, tc.player.ID) // their own property ruined → a lawman's grievance, confront on sight
		}
		// The owner takes the full disposition damage and a lasting wariness — their
		// property wronged weighs like an assault (and a hazard endangers them bodily
		// too, so the catalogue floors their fear at the fleeing-onlooker's). A guard
		// owner is still the law: the catalogue zeroes their dread, the grievance above
		// stands instead.
		s.applyRelDelta(ctx, tc, owner, relationshipConsequence(rolePropertyOwner, hazard, guard), "порча имущества")
		s.formMemory(ctx, tc, evt, owner, fmt.Sprintf("%s уничтожает на моих глазах моё: %s", playerName, v.targetEnt.Name))
	}
}

// applyImpulse drives an NPC's emotions with floor semantics and persists the
// change; an EmotionChanged event keeps the log honest.
func (s *TurnService) applyImpulse(ctx context.Context, tc *turnContext, npc *actor.Actor, floors map[actor.EmotionType]float32) {
	if !s.behavior.ApplyEmotionImpulse(npc, floors) {
		return
	}
	if err := s.actors.Update(ctx, npc); err != nil {
		s.logger.Warn("persist emotion impulse failed", zap.String("npc", npc.Identity.Name), zap.Error(err))
	}
	dominant, intensity := npc.State.Emotional.CurrentTone.GetDominantEmotion()
	evt := event.NewGameEvent(
		event.EventTypeEmotionChanged,
		npc.ID, npc.State.GetCurrentLocation(), tc.worldID, tc.tick,
		event.StateChangeEventData{
			ActorID:   npc.ID,
			StateType: event.StateChangeEmotion,
			OldValue:  event.StringValue(""),
			NewValue:  event.StringValue(string(dominant)),
			Reason:    fmt.Sprintf("реакция на действие игрока (%.2f)", intensity),
		},
	)
	if err := s.events.Append(ctx, evt); err != nil {
		s.logger.Warn("append emotion change failed", zap.Error(err))
	}
}

// formMemory writes one actor's memory of the deed, coloured by how they feel
// right now (the impulse just landed). Best-effort: a failed memory must not
// fail the turn.
func (s *TurnService) formMemory(ctx context.Context, tc *turnContext, evt *event.GameEvent, owner *actor.Actor, perspective string) {
	if s.memory == nil {
		return
	}
	if _, err := s.memory.CreateFromEvent(ctx, evt, owner.ID, perspective, memory.EmotionalToneFromActor(owner)); err != nil {
		s.logger.Warn("memory formation failed", zap.String("npc", owner.Identity.Name), zap.Error(err))
	}
}

package llm

import (
	"context"
	"fmt"
	"strings"

	"github.com/dnd-llm/dnd-llm/internal/domain/entity"
	infrallm "github.com/dnd-llm/dnd-llm/internal/infrastructure/llm"
)

// The effect classifier is the consequence-sensor: given the player's DEED, it
// picks — under a grammar — which transformation from the closed catalogue the
// ACTION produces. ONE focused job: classify the player's verb, not the thing.
// (Asking it to also pick the affected thing made it choose the effect that
// fits the thing's nature — flour → «смять» — instead of the player's verb;
// the thing is grounded deterministically elsewhere, by name.) This is the
// deterministic-core boundary done right: the LLM maps open-ended language to a
// closed category, the core applies that key's fixed mechanics, and the choice
// is journaled so replay never calls the model again. The verb names the effect
// («поджечь» → поджечь); a consequence-verb resolves by meaning («ударить
// кружку об пол» → разбить) — exactly where the model is strong.

// effectNone is the sentinel: the deed changes no thing (touch, look, talk).
const effectNone = "никакой"

type effectSelectSchema struct {
	Effect string `json:"effect"` // dynamic enum: catalogue keys + effectNone
}

// EffectSelector classifies a deed into a catalogue effect.
type EffectSelector struct {
	llm infrallm.SchemaCompleter
}

// NewEffectSelector builds a classifier. A nil completer makes Classify return
// "" — the deed changes nothing.
func NewEffectSelector(llm infrallm.SchemaCompleter) *EffectSelector {
	return &EffectSelector{llm: llm}
}

// Classify returns the catalogue effect the deed produces, or "" for «никакой».
// Grammar-bound to the catalogue; the verdict engine owns the mechanics and
// grounds WHICH thing is affected itself.
func (s *EffectSelector) Classify(ctx context.Context, deed string) (string, error) {
	if s == nil || s.llm == nil || strings.TrimSpace(deed) == "" {
		return "", nil
	}
	enum := append(entity.EffectKeys(), effectNone)
	schema, _, err := infrallm.Decode[effectSelectSchema](ctx, s.llm, infrallm.Request{
		SystemPrompt: effectClassifySystem,
		UserPrompt:   fmt.Sprintf("Действие игрока: %s\n\nКакой эффект из перечня производит это действие? Если действие ничего не меняет в вещах (потрогать, осмотреть, поговорить) — «%s». Верни JSON.", deed, effectNone),
		Temperature:  0.2, // classification wants to be decisive, not creative
		MaxTokens:    40,
		Language:     "ru",
		Options:      &infrallm.RequestOptions{DynamicEnums: map[string][]string{"effect": enum}},
	})
	if err != nil {
		return "", err
	}
	if strings.TrimSpace(schema.Effect) == effectNone {
		return "", nil
	}
	return schema.Effect, nil
}

const effectClassifySystem = `Ты — сенсор последствий в игровом движке. Тебе дают ДЕЙСТВИЕ игрока над вещью. Выбери из перечня ОДИН эффект, который это действие производит.

Главное правило: выбирай по тому, что игрок ДЕЛАЕТ (по глаголу действия), а не по природе предмета. «Поджечь» — это поджечь, что бы ни поджигали. Если действие ничего не меняет в вещах — «никакой».`

