package turn

import (
	"context"
	"fmt"
	"time"

	"github.com/dnd-llm/dnd-llm/internal/application/conversation"
	appgoal "github.com/dnd-llm/dnd-llm/internal/application/goal"
	"github.com/dnd-llm/dnd-llm/internal/application/llm"
	"github.com/dnd-llm/dnd-llm/internal/application/memory"
	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/actor"
	"github.com/dnd-llm/dnd-llm/internal/domain/check"
	"github.com/dnd-llm/dnd-llm/internal/domain/entity"
	"github.com/dnd-llm/dnd-llm/internal/domain/event"
	"github.com/dnd-llm/dnd-llm/internal/domain/front"
	"github.com/dnd-llm/dnd-llm/internal/infrastructure/repository"
	"go.uber.org/zap"
)

// TickConfig tunes the per-tick orchestration.
type TickConfig struct {
	// StoryConcurrency caps how many StoryNPC LLM calls (decisions + dialogue
	// lines) fire concurrently in one tick. vLLM-rust batches them server-side;
	// the cap just protects against connection floods.
	StoryConcurrency int
	// DecisionTimeout bounds a single LLM decision/dialogue call so an
	// over-budget call degrades to a fallback instead of stalling the tick.
	DecisionTimeout time.Duration
	// MemoryMaintenanceEveryTicks runs memory upkeep (decay + compression) once
	// every N ticks. Defaults to 1 (every tick).
	MemoryMaintenanceEveryTicks int
}

func (c TickConfig) withDefaults() TickConfig {
	if c.StoryConcurrency <= 0 {
		// Measured on Gemma E4B Q4_K_M / vllm-rust v1.21 (8 GB, eager GGUF):
		// aggregate throughput scales ~4.3× up to a batch of 12 (25 → 108 tok/s)
		// and saturates there; 12 concurrent decisions complete in ~9s — inside
		// a 10s tick — while 16 spill over. The server queues anything beyond
		// its --max-requests, so this cap only needs to match the sweet spot.
		c.StoryConcurrency = 12
	}
	if c.DecisionTimeout <= 0 {
		// Headroom for constrained decoding on a local 4B; a real-time engine
		// keeps within tick budget via small MaxTokens, this is the safety net.
		c.DecisionTimeout = 20 * time.Second
	}
	if c.MemoryMaintenanceEveryTicks < 1 {
		c.MemoryMaintenanceEveryTicks = 1
	}
	return c
}

// TickProcessorDeps contains dependencies for the TickProcessor.
type TickProcessorDeps struct {
	ActorRepo        actor.ActorRepository
	EventStore       event.EventStore
	DecisionSvc      *llm.DecisionService
	BehaviorSystem   *actor.BehaviorSystem     // optional; a default one is created if nil
	MemoryService    *memory.MemoryService     // optional; perception forms memories when set
	ConvOrchestrator *ConversationOrchestrator // optional; NPC↔NPC dialogue when set
	LocationRegistry *LocationRegistry         // optional; capacity-aware placement when set
	GoalTracker      *appgoal.GoalTracker      // optional; goal-directed StoryNPC behaviour when set
	Hazards          HazardScanner             // optional; environmental-threat evacuation when set
	Igniter          EntityIgniter             // optional; fire spreads to flammable neighbours when set
	Kindler          PropKindler               // optional; fire reaches a place's LATENT prop fund when set
	Doom             GoalOutcomeApplier        // optional; a completed goal's authored outcome lands as a real change when set
	Logger           *zap.Logger               // optional; NewNop when nil
	Config           TickConfig
}

// GoalOutcomeApplier lands a completed goal's authored OUTCOME as a real world change —
// the same port (and adapter, knowledge.DoomApplier) a front doom uses, so a goal payoff
// and a front doom are one mechanism. nil → a goal completion only rotates the NPC's aim.
type GoalOutcomeApplier interface {
	Apply(ctx context.Context, worldID domain.WorldID, c front.Consequence, tick domain.Tick) error
}

// HazardScanner lists the things present at a location, so the tick can find a
// STANDING environmental threat (a fire) and make everyone there flee; and lists
// the locations that hold a fire, so a blaze spreads even in an emptied room.
type HazardScanner interface {
	ListPresentAt(ctx context.Context, worldID domain.WorldID, locationID domain.LocationID, holders []domain.ActorID) ([]*entity.Entity, error)
	HazardLocations(ctx context.Context, worldID domain.WorldID) ([]domain.LocationID, error)
}

// EntityIgniter drives a thing through fire: Ignite sets a flammable neighbour
// alight from a spreading blaze (the same hazard mechanics a player's arson
// commits); BurnOut ends the fire once it has consumed the thing, leaving a
// charred ruin that no longer threatens or burns. Both are event-sourced for
// replay so the whole lifecycle (ignite → spread → char) is reproducible.
type EntityIgniter interface {
	Ignite(ctx context.Context, id domain.EntityID, tick domain.Tick) error
	BurnOut(ctx context.Context, id domain.EntityID, tick domain.Tick) error
}

// PropKindler lets a standing fire reach the LATENT prop fund of a place — the
// authored furniture that has not yet crystallized into an entity. When the
// present-entity tier of the spread finds no materialized kindling, this
// crystallizes the next flammable prop of the place and ignites it (the same
// crystallize-on-reach a player's action uses), returning the thing's name or ""
// when the place has no more latent fuel. Without it a fire is blind to a
// tavern's authored candle until a player happens to touch it.
type PropKindler interface {
	KindleNext(ctx context.Context, worldID domain.WorldID, loc domain.LocationID, tick domain.Tick) (string, error)
}

// TickProcessor handles the processing of a single game tick.
// It coordinates actor actions, world events, and state updates.
type TickProcessor struct {
	actorRepo        actor.ActorRepository
	eventStore       event.EventStore
	decisionSvc      *llm.DecisionService
	behaviorSystem   *actor.BehaviorSystem
	memoryService    *memory.MemoryService
	convOrchestrator *ConversationOrchestrator
	locationRegistry *LocationRegistry
	goalTracker      *appgoal.GoalTracker
	hazards          HazardScanner
	igniter          EntityIgniter
	kindler          PropKindler
	doom             GoalOutcomeApplier
	actionLoop       *actionLoopTracker
	logger           *zap.Logger
	cfg              TickConfig

	// checkRoll resolves an uncertain action into a graded outcome. Production
	// leaves it nil and the deterministic check.Resolve is used; tests inject a
	// forced tier to exercise a stage's branches without depending on the dice.
	checkRoll func(seed int64, pool int, pos check.Position) check.Outcome
}

// roll resolves an uncertain action through the check primitive, honouring an
// injected roller when one is set (tests force a tier; production rolls the dice).
func (p *TickProcessor) roll(seed int64, pool int, pos check.Position) check.Outcome {
	if p.checkRoll != nil {
		return p.checkRoll(seed, pool, pos)
	}
	return check.Resolve(seed, pool, pos)
}

// NewTickProcessor creates a new TickProcessor with the given dependencies.
func NewTickProcessor(deps TickProcessorDeps) *TickProcessor {
	bs := deps.BehaviorSystem
	if bs == nil {
		bs = actor.NewBehaviorSystem()
	}
	logger := deps.Logger
	if logger == nil {
		logger = zap.NewNop()
	}
	return &TickProcessor{
		actorRepo:        deps.ActorRepo,
		eventStore:       deps.EventStore,
		decisionSvc:      deps.DecisionSvc,
		behaviorSystem:   bs,
		memoryService:    deps.MemoryService,
		convOrchestrator: deps.ConvOrchestrator,
		locationRegistry: deps.LocationRegistry,
		goalTracker:      deps.GoalTracker,
		hazards:          deps.Hazards,
		igniter:          deps.Igniter,
		kindler:          deps.Kindler,
		doom:             deps.Doom,
		actionLoop:       newActionLoopTracker(),
		logger:           logger,
		cfg:              deps.Config.withDefaults(),
	}
}

// ProcessActors processes all actors in the world for this tick.
//
// Orchestration order (see ai-docs plan, Steps 3-7):
//  1. Perception: events from the previous tick update NPC emotions and memory.
//  2. Conversations: detect/start NPC↔NPC conversations among co-located StoryNPCs.
//  3. Concurrent LLM batch: StoryNPC decisions + dialogue lines fire together so
//     the server's continuous batching folds them into one forward pass.
//  4. Routine NPCs: schedule + BehaviorSystem, no LLM (the cheap tier).
//  5. Reap conversations (end + relationship effects) and persist changed actors.
//
// Returns all events generated during the tick.
func (p *TickProcessor) ProcessActors(
	ctx context.Context,
	worldID domain.WorldID,
	gameTime domain.GameTime,
	actors []*actor.Actor,
) ([]*event.GameEvent, error) {
	// Tag the context with the world so repository writes attribute correctly.
	ctx = repository.WithWorldID(ctx, worldID)

	var events []*event.GameEvent
	dirty := make(map[domain.ActorID]bool)
	byID := make(map[domain.ActorID]*actor.Actor, len(actors))

	var storyNPCs, routineNPCs []*actor.Actor
	for _, a := range actors {
		if a.IsDead() {
			continue
		}
		byID[a.ID] = a
		switch a.Type {
		case actor.ActorTypeStoryNPC:
			storyNPCs = append(storyNPCs, a)
		case actor.ActorTypeRoutineNPC:
			routineNPCs = append(routineNPCs, a)
		}
	}

	// 1. Perception → emotions + memory (sequential, mutates before any reads).
	percEvents, percDirty := p.processPerception(ctx, worldID, gameTime, byID)
	events = append(events, percEvents...)
	mergeDirty(dirty, percDirty)

	// 1b. Emotional maintenance: every living NPC's feelings decay toward calm and
	// their escalation level is recomputed, so emotions live and fade between
	// events instead of freezing. Runs after perception so escalation reflects
	// this tick's freshly-perceived emotions.
	for id, npc := range byID {
		if p.behaviorSystem.MaintainEmotions(npc, gameTime) {
			dirty[id] = true
		}
	}

	// 1b'. REFLEXES — the instinct layer of behaviour selection: deterministic,
	// preemptive responses that override deliberation. An NPC does not "decide"
	// from a menu to flee a fire or quit a collapsed shell — the body leaves before
	// the mind weighs options, mid-conversation or not, story NPC or routine
	// townsperson alike. Reflexes run BEFORE conversation and the decision batch and
	// CLAIM the NPCs they move, so the deliberative layers skip them (one body, one
	// action per tick). The reflex here is displacement from an untenable place
	// (hazard or ruin); others belong here.
	reflexEvents, reflexDirty, reflexClaimed := p.processInstincts(ctx, gameTime, worldID, byID)
	events = append(events, reflexEvents...)
	mergeDirty(dirty, reflexDirty)

	// 1c. Memory upkeep: every N ticks each living NPC forgets what has decayed
	// past recall and snowball-compresses what has aged, so memory stays bounded
	// over long runs while flashbulb trauma persists. Runs after perception so
	// this tick's fresh memories are already in the store.
	if p.memoryService != nil && p.cfg.MemoryMaintenanceEveryTicks > 0 &&
		gameTime.Tick%domain.Tick(p.cfg.MemoryMaintenanceEveryTicks) == 0 {
		for id, npc := range byID {
			if err := p.memoryService.Maintain(ctx, id, gameTime.Tick); err != nil {
				fmt.Printf("Error maintaining memory for %s: %v\n", id, err)
			}
			// Memories drift over time, shaped by the NPC's psychology: anxious or
			// less clever minds and traumatic memories distort more.
			neuroticism, intelligence := psychProfile(npc)
			if err := p.memoryService.DistortMemories(ctx, id, neuroticism, intelligence, gameTime.Tick); err != nil {
				fmt.Printf("Error distorting memory for %s: %v\n", id, err)
			}
			// Consolidation is heavier (resolves events) and only acts on aged
			// routine memories, so run it sparingly — about once a game hour.
			if gameTime.Tick%domain.TicksPerHour == 0 {
				if err := p.memoryService.Consolidate(ctx, id, gameTime.Tick); err != nil {
					fmt.Printf("Error consolidating memory for %s: %v\n", id, err)
				}
			}
		}
	}

	// Refresh which places are unusable (a structure destroyed this or an earlier
	// tick) and push it to the registry, so the capacity-aware placement below —
	// and every later tick — steers NPCs away from a ruined venue instead of
	// scheduling them into a burned-out husk. Runs after the reflexes that may have
	// just consumed a building, before any placement reads it.
	if p.locationRegistry != nil {
		p.locationRegistry.SetUninhabitable(worldID, p.uninhabitableLocations(ctx, worldID))
	}

	// Current crowd at each location, used by capacity-aware placement below.
	// A per-tick snapshot: as NPCs transition in one by one across ticks, late
	// arrivals to a full venue get redirected, so the city spreads out.
	occupancy := occupancyByLocation(byID)

	// StoryNPCs follow their schedule for baseline placement (so they gather at
	// taverns/squares and can meet), while their discretionary actions still come
	// from the LLM below. Without this they'd never relocate and never co-locate.
	for _, npc := range storyNPCs {
		if npc.Schedule == nil {
			continue
		}
		evt, changed, err := p.applySchedule(ctx, worldID, npc, gameTime, occupancy)
		if err != nil {
			continue
		}
		if evt != nil {
			events = append(events, evt)
		}
		if changed {
			dirty[npc.ID] = true
		}
	}

	// 2. Detect/start background conversations. Two distinct claims, kept in two
	//    maps on purpose:
	//      - playerBusy: NPCs talking to the PLAYER this turn. They must never
	//        also background-chatter — one mouth, one conversation (the live bug
	//        had an NPC haggling with the player and chatting to a neighbour in
	//        the same turn).
	//      - busy: playerBusy PLUS the pairs Detect starts this tick, so those
	//        NPCs don't also run a separate story decision below.
	//    DialogueTasks must see only playerBusy: marking a freshly-paired NPC
	//    busy in the shared map made DialogueTasks treat its OWN conversation's
	//    participants as claimed and kill the talk before its first line — which
	//    is why no background conversation was ever heard.
	playerBusy := make(map[domain.ActorID]bool)
	busy := make(map[domain.ActorID]bool)
	// An NPC a reflex already moved this tick has spent its action: it neither
	// deliberates nor is pulled into background chatter (its conversation, if
	// any, wrapped up as it bolted).
	for id := range reflexClaimed {
		busy[id] = true
		playerBusy[id] = true
	}
	var playerLoc domain.LocationID
	var player *actor.Actor
	for _, a := range actors {
		if a.Type == actor.ActorTypePlayer {
			player, playerLoc = a, a.GetCurrentLocation()
			break
		}
	}
	if player != nil && p.eventStore != nil {
		if conv := conversation.FoldActive(ctx, p.eventStore, worldID, player.ID, gameTime.Tick); conv != nil {
