	// cadence — the "environmental trigger" the cadence anticipates, kept
	// deterministic (the reaction stays a menu choice; only the timing is forced).
	// Drive evaluation: an NPC's internal state spawns goals no author wrote. A lasting
	// fear of someone becomes a standing avoidance drive (derived from the relationship
	// each tick), so the town shuns a dreaded player of its own accord — run BEFORE the
	// decision, so activeGoal surfaces the fresh drive in the prompt and the action menu.
	present := make(map[domain.ActorID]bool, len(byID))
	for id := range byID {
		present[id] = true
	}
	for _, npc := range storyNPCs {
		p.evaluateDrives(npc, present, gameTime)
	}

	violentLocs := recentViolenceLocations(ctx, p.eventStore, worldID, gameTime.Tick)
	var tasks []llmTask
	for _, npc := range storyNPCs {
		forced := violentLocs[npc.State.GetCurrentLocation()]
		if busy[npc.ID] || (!forced && !p.storyCadence(npc, gameTime.Tick)) {
			continue
		}
		npc := npc
		tasks = append(tasks, func(c context.Context) *event.GameEvent {
			evt, err := p.ProcessNPCAction(c, npc, gameTime, actors, worldID)
			if err != nil {
				return nil
			}
			return evt
		})
	}
	if p.convOrchestrator != nil {
		// Background conversations speak aloud only where the player stands;
		// everywhere else they advance silently (no LLM, no DialogueLine).
		// playerBusy (NOT busy): only an NPC the player is talking to drops its
		// back

