}

// endangeredLocations returns the occupied locations that hold a standing hazard
// — a present thing marked with an entity.StateHazard, whether pinned to the
// place OR carried in by someone there (a burning cargo in a holder's arms
// endangers the room too). One ListPresentAt per distinct occupied location,
// with that location's actors as holders so carried hazards are seen.
func (p *TickProcessor) endangeredLocations(ctx context.Context, worldID domain.WorldID, byID map[domain.ActorID]*actor.Actor) map[domain.LocationID]bool {
	endangered := make(map[domain.LocationID]bool)
	for loc, holders := range actorsByLocation(byID) {
		if loc.IsZero() {
			continue
		}
		present, err := p.hazards.ListPresentAt(ctx, worldID, loc, holders)
		if err != nil {
			continue
		}
		for _, e := range present {
			if e.StateText(entity.StateHazard) != "" {
				endangered[loc] = true
				break
			}
		}
	}
	return endangered
}

// uninhabitableLocations returns the places no longer usable because their
// LOAD-BEARING structure has been destroyed (a burned-out timber frame). The
// generalisation of "fire empties a room": a hazard closes a place WHILE it burns
// (endangeredLocations → evacuate); a ruined shell closes it FOR GOOD, even with no
// standing hazard — so NPC routing must not send anyone back. Scans every location
// the registry knows (not just occupied ones — a ruined venue stands empty), reading
// place-pinned structures via ListPresentAt. Deterministic, derived from entity
// state, so it rebuilds identically on restart/replay.
func (p *TickProcessor) uninhabitableLocations(ctx context.Context, worldID domain.WorldID) map[domain.LocationID]bool {
	out := make(map[domain.LocationID]bool)
	if p.hazards == nil || p.locationRegistry == nil {
		return out
	}
	for loc := range p.locationRegistry.capacities(ctx, worldID) {
		if loc.IsZero() {
			continue
		}
		present, err := p.hazards.ListPresentAt(ctx, worldID, loc, nil)
		if err != nil {
			continue
		}
		for _, e := range present {
			if e.IsLoadBearing() && e.IsRuined() {
				out[loc] = true
				break
			}
		}
	}
	return out
}

// fireHeatByLocation returns the total blaze HEAT in each occupied location — the
// summed FireHeat of everything burning there, the intensity an actor standing in
// it is exposed to. Locations with no fire are absent (0). Carried fire is included
// (holders passed to ListPresentAt), so a burning thing in someone's arms heats the
// room as a place-pinned one does — the same surface evacuation and consumption
// watch.
func (p *TickProcessor) fireHeatByLocation(ctx context.Context, gameTime domain.GameTime, worldID domain.WorldID, byID map[domain.ActorID]*actor.Actor) map[domain.LocationID]int {
	out := make(map[domain.LocationID]int)
	for loc, holders := range actorsByLocation(byID) {
		if loc.IsZero() {
			continue
		}
		present, err := p.hazards.ListPresentAt(ctx, worldID, loc, holders)
		if err != nil {
			continue
		}
		for _, e := range present {
			out[loc] += e.FireHeat(gameTime.Tick)
		}
	}
	return out
}

// harmFromHazards burns every actor who REMAINS where a fire stands — the price of
// not fleeing. It runs AFTER evacuateFromHazards, so NPCs who fled are already gone
// from the endangered rooms; what stays is the player (who flees only on their own
// turn) and any NPC the fire trapped (could not relocate — a fire kills who it
// traps, DF under the hood). Damage scales with the location's total blaze heat and
// goes through the actor's combat model (TakeDamage → unconscious → death saves),
// journaled as a fire DamageTaken so it perceives, surfaces and replays like any
// other harm.
func (p *TickProcessor) harmFromHazards(ctx context.Context, gameTime domain.GameTime, worldID domain.WorldID, byID map[domain.ActorID]*actor.Actor) ([]*event.GameEvent, map[domain.ActorID]bool) {
	dirty := make(map[domain.ActorID]bool)
	var events []*event.GameEvent
	if p.hazards == nil {
		return events, dirty
	}
	heat := p.fireHeatByLocation(ctx, gameTime, worldID, byID)
	if len(heat) == 0 {
		return events, dirty
	}
	for id, a := range byID {
		if a.State == nil || a.State.Physical == nil || a.IsDead() {
			continue
		}
		if ev := burnActor(a, entity.FireDamagePerTick(heat[a.State.GetCurrentLocation()]), worldID, gameTime); ev != nil {
			dirty[id] = true
			events = append(events, ev)
		}
	}
	return events, dirty
}

// burnActor applies a dose of fire harm to an actor through the combat model and
// returns the journaled DamageTaken fact — the ONE place a burn is recorded, shared
// by the harm reflex (the price of standing in a blaze) and the rescue scorch (the
// price of braving one). nil when the actor has no combat body or the dose is empty,
// so callers can fold the result without re-checking.
func burnActor(a *actor.Actor, dmg int, worldID domain.WorldID, gameTime domain.GameTime) *event.GameEvent {
	if a.State == nil || a.State.Physical == nil || dmg <= 0 {
		return nil
	}
	a.State.Physical.TakeDamage(dmg, "fire", false)
	return event.NewGameEvent(
		event.EventTypeDamageTaken,
		a.ID, a.State.GetCurrentLocation(), worldID, gameTime.Tick,
		event.DamageEventData{
			VictimID:    a.ID,
			Damage:      dmg,
			DamageType:  "fire",
			RemainingHP: a.State.Physical.Health.Current,
			Killed:      a.IsDead(),
			Source:      "environment",
		},
	)
}

// NewActionContext creates a new ActionContext for the given actor and tick.
func NewActionContext(
	a *actor.Actor,
	tick domain.Tick,
	gameTime domain.GameTime,
) *ActionContext {
	return &ActionContext{
		Actor:        a,
		CurrentTick:  tick,
		GameTime:     gameTime,
		Location:     a.State.GetCurrentLocation(),
		NearbyActors: nil,
		RecentEvents: nil,
		Timestamp:    time.Now(),
	}
}

package turn

import (
	"context"
	"math/rand"
	"strings"

	appmemory "github.com/dnd-llm/dnd-llm/internal/application/memory"
	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/actor"
	"github.com/dnd-llm/dnd-llm/internal/domain/event"
	goaldom "github.com/dnd-llm/dnd-llm/internal/domain/goal"
	"github.com/dnd-llm/dnd-llm/internal/domain/memory"
)

// maxRumorListeners caps how many co-located NPCs pick up a shared rumor.
const maxRumorListeners = 3

// applyDecisionEffects closes the loop between a StoryNPC's chosen action and
// the world: social choices open a conversation, movement choices relocate the
// NPC. Most actions are intrinsically self-contained (observe, work, …) and
// have no external effect. Runs sequentially after the concurrent decision
// batch, so mutating shared actor state here is safe.
//
// detail is the NPC's own reasoning for the action, reused as flavour text for
// the resulting observation/rumor.
//
// Returns follow-on events and whether the actor's state changed.
func (p *TickProcessor) applyDecisionEffects(
	ctx context.Context,
	npc *actor.Actor,
	actionType string,
	detail string,
	gameTime domain.GameTime,
	worldID domain.WorldID,
	byID map[domain.ActorID]*actor.Actor,
	busy map[domain.ActorID]bool,
) ([]*event.GameEvent, bool) {
	switch actionType {
	case "strike_up_conversation", "confront", "approach_person", "offer_aid":
		// Engaging a specific person THIS soul is drawn to (or moved to comfort) manifests as
		// opening a conversation — the existing vehicle for one NPC reaching another. The
		// appraisal already chose WHO grips them; the orchestrator pairs them up.
		if p.convOrchestrator == nil {
			return nil, false
		}
		return p.convOrchestrator.ForceStart(ctx, worldID, gameTime, npc, byID, busy), false

	case "share_rumor":
		return p.spreadRumor(ctx, npc, gameTime, worldID, byID, busy), false

	case "investigate":
		return p.investigate(ctx, npc, detail, gameTime, worldID), false

	case goalActionID:
		// The decision phase only narrated the outcome (read-only preview); the
		// durable state change — progress + GoalProgressed/GoalAchieved events —
		// is applied here, in the sequential phase.
		return p.advanceGoal(ctx, npc, gameTime, worldID), false

	case "move_elsewhere", "wander":
		return p.relocate(ctx, npc, gameTime, worldID, byID, false)

	case "storm_off", "withdraw":
		// Leave-class actions: the point is to GET OUT of here. Unlike a casual
		// move, "nowhere purposeful to go" must not collapse into staying put —
		// the emitted action already narrates the NPC leaving.
		return p.relocate(ctx, npc, gameTime, worldID, byID, true)

	case "recoil_watch", "watch_warily":
		// Holding ground, tense, eyes fixed on the one who unsettles them — a congruent
		// non-flight response (recoil_watch from witnessed violence, watch_warily from a
		// wary subjective reading). No world change: bolting is the flight reflex's job.
		return nil, false
	}
	return nil, false
}

// investigate produces an observation at the NPC's location and, when memory is
// available, forms a memory of it — so investigation actually leaves a trace the
// NPC can recall and act on later.
func (p *TickProcessor) investigate(
	ctx context.Context,
	npc *actor.Actor,
	detail string,
	gameTime domain.GameTime,
	worldID domain.WorldID,
) []*event.GameEvent {
	loc := npc.State.GetCurrentLocation()
	if detail == "" {
		detail = "осматривается по сторонам в поисках чего-то необычного"
	}
	obs := event.NewGameEvent(
		event.EventTypeObservation,
		npc.ID, loc, worldID, gameTime.Tick,
		event.ObservationEventData{ActorID: npc.ID, LocationID: loc, Description: detail},
	)
	if p.memoryService != nil {
		desc := describeForMemory(obs, npc.ID, func(domain.ActorID) string { return "кто-то" })
		_, _ = p.memoryService.CreateFromEvent(ctx, obs, npc.ID, desc, memory.EmotionalToneFromActor(npc))
	}
	return []*event.GameEvent{obs}
}

// spreadRumor propagates a rumor from the speaker to co-located NPCs: each
// listener gets a RumorHeard event and (when memory is available) remembers it,
// so information actually diffuses through the town. It also sparks a
// conversation so the rumor is shared aloud.
//
// The rumor's content is something the speaker REMEMBERS — never the
// decision's reasoning, which is the model's meta-voice («моя цель…») and was
// leaking to the player verbatim as a whisper.
func (p *TickProcessor) spreadRumor(
	ctx context.Context,
	npc *actor.Actor,
	gameTime domain.GameTime,
	worldID domain.WorldID,
	byID map[domain.ActorID]*actor.Actor,
	busy map[domain.ActorID]bool,
) []*event.GameEvent {
	loc := npc.State.GetCurrentLocation()
	rumor := "свежая городская сплетня — подробности тонут в шёпоте"
	if p.memoryService != nil {
		if mems, err := p.memoryService.Recall(ctx, npc.ID, appmemory.RecallQuery{
			MinImportance: 0.3,
			Limit:         1,
			CurrentTick:   gameTime.Tick,
			PreferRecent:  true,
		}); err == nil && len(mems) > 0 && strings.TrimSpace(mems[0].Content) != "" {
			rumor = mems[0].Content
		}
	}

	nameOf := func(id domain.ActorID) string {
		if a, ok := byID[id]; ok {
			return a.GetName()
		}
		return "кто-то"
	}

	var events []*event.GameEvent
	listeners := 0
	for id, other := range byID {
		if id == npc.ID || other.IsDead() {
			continue
		}
		if other.State.GetCurrentLocation() != loc {
			continue
		}
		rh := event.NewGameEvent(
			event.EventTypeRumorHeard,
			other.ID, loc, worldID, gameTime.Tick,
			event.RumorHeardEventData{HearerID: other.ID, SourceID: npc.ID, LocationID: loc, Rumor: rumor},
		)
		events = append(events, rh)
		if p.memoryService != nil {
			// Render with provenance ("Heard from <speaker>: …") so the rumor's
			// source travels with the memory and the chain stays traceable.
			desc := describeForMemory(rh, other.ID, nameOf)
			_, _ = p.memoryService.CreateFromEvent(ctx, rh, other.ID, desc, memory.EmotionalToneFromActor(other))
		}
		if listeners++; listeners >= maxRumorListeners {
			break
		}
	}

	// The rumor is shared aloud — spark a conversation too.
	if p.convOrchestrator != nil {
		events = append(events, p.convOrchestrator.ForceStart(ctx, worldID, gameTime, npc, byID, busy)...)
	}
	return events
}

// relocate moves the NPC toward a place they actually have reason to be (see
// purposefulDestination), keeping their current activity state (only the location
// changes), and emits a movement event. Crucially it does NOT scatter them to a
// random empty venue: with no spatial graph in the world, that read as teleporting
// across town every few ticks.
//
// mustLeave marks leave-class actions (storm_off, withdraw), where departing
// matters more than the destination: with nothing purposeful pulling the NPC
// anywhere, they disperse toward an emptier venue instead of staying — the
// already-narrated "storms off" must not leave them rooted to the spot.
//
// The destination is resolved through the same capacity rules as every other
// movement path (full venue → same-type alternative → stay): physics applies
// to LLM-driven moves no less than to scheduled ones.
func (p *TickProcessor) relocate(
	ctx context.Context,
	npc *actor.Actor,
	gameTime domain.GameTime,
	worldID domain.WorldID,
	byID map[domain.ActorID]*actor.Actor,
	mustLeave bool,
) ([]*event.GameEvent, bool) {
	from := npc.State.GetCurrentLocation()
	to := p.purposefulDestination(npc, gameTime, byID)
	if mustLeave && (to == "" || to == from) {
		to = p.pickDispersalTarget(ctx, worldID, from, byID)
	}
	if to == "" || to == from {
		return nil, false // nowhere meaningful to go → stay rather than teleport
	}
	if resolved, ok := p.resolvePlacement(ctx, worldID, npc.State.StateType, to, occupancyByLocation(byID)); ok {
		to = resolved
	} else {
		return nil, false // destination (and every alternative) is full
	}
	if to == from {
		return nil, false // capacity redirected the move back to where they stand
	}
	if !setContextLocation(npc.State.StateContext, to) {
		return nil, false // current state has no relocatable location
	}

	fromLoc := from
	evt := event.NewGameEvent(
		event.EventTypeActorMoved,
		npc.ID, to, worldID, gameTime.Tick,
		event.MovementEventData{
			ActorID:        npc.ID,
			FromLocationID: &fromLoc,
			ToLocationID:   to,
			Method:         "walking",
		},
	)
	return []*event.GameEvent{evt}, true
}

// rng returns a source of randomness, reusing the conversation orchestrator's
// when available so a seeded run stays reproducible.
func (p *TickProcessor) rng() *rand.Rand {
	if p.convOrchestrator != nil {
		return p.convOrchestrator.rng
	}
	return rand.New(rand.NewSource(1))
}

// purposefulDestination picks where an NPC actually has reason to go when they
// choose to move: toward their goal's place, else where their schedule puts them,
// else — only if they are sitting alone — toward where other people are, for
// company. Returns "" when there is no meaningful destination, so the caller keeps
// the NPC where they are instead of scattering them to a random venue.
func (p *TickProcessor) purposefulDestination(
	npc *actor.Actor,
	gameTime domain.GameTime,
	byID map[domain.ActorID]*actor.Actor,
) domain.LocationID {
	from := npc.State.GetCurrentLocation()

	// 1. A goal that points somewhere concrete pulls the NPC there.
	if g := p.activeGoal(npc); g != nil {
		// A place-goal → that place.
		if g.Target.LocationID != nil && *g.Target.LocationID != from {
			return *g.Target.LocationID
		}
		// A PERSON-goal → where that person is (follow, seek out, protect). Avoidance is
		// the exception: it points AT the feared one but moves AWAY (the flight reflex and
		// must-leave dispersal handle that), so it never routes the NPC toward them.
		if g.Target.ActorID != nil && g.Type != goaldom.GoalTypeAvoidActor {
			if target := byID[*g.Target.ActorID]; target != nil && target.State != nil {
				if to := target.State.GetCurrentLocation(); !to.IsZero() && to != from {
					return to
				}
			}
		}
	}
	// 2. Where the NPC is scheduled to be right now.
	if npc.Schedule != nil {
		if sc := npc.Schedule.GetCurrentActivity(gameTime); !sc.Location.IsZero() && sc.Location != from {
			return sc.Location
		}
	}
	// 3. Alone here? Head toward company (a place others occupy). Otherwise stay.
	if aloneAt(from, npc.ID, byID) {
		return pickWanderTarget(from, byID, p.rng())
	}
	return ""
}

// aloneAt reports whether the actor is the only one at the given location.
func aloneAt(loc domain.LocationID, self domain.ActorID, byID map[domain.ActorID]*actor.Actor) bool {
	for id, a := range byID {
		if id == self {
			continue
		}
		if a.State.GetCurrentLocation() == loc {
			return false
		}
	}
	return true
}

// pickWanderTarget chooses a distinct location to wander to among the places
// other actors currently occupy (so NPCs converge on lively spots).
func pickWanderTarget(from domain.LocationID, byID map[domain.ActorID]*actor.Actor, rng *rand.Rand) domain.LocationID {
	seen := make(map[domain.LocationID]bool)
	var candidates []domain.LocationID
	for _, a := range byID {
		loc := a.State.GetCurrentLocation()
		if loc == "" || loc == from || seen[loc] {
			continue
		}
		seen[loc] = true
		candidates = append(candidates, loc)
	}
	if len(candidates) == 0 {
		return ""
	}
	return candidates[rng.Intn(len(candidates))]
}

// setContextLocation updates the location on the actor's current state context
// in place, for the context types that carry one. Returns false if the context
// has no location (e.g. a conversation context).
func setContextLocation(ctx actor.StateContext, loc domain.LocationID) bool {
	switch c := ctx.(type) {
	case *actor.IdleContext:
		c.Location = loc
	case *actor.SleepingContext:
		c.Location = loc
	case *actor.EatingContext:
		c.Location = loc
	case *actor.WorkingContext:
		c.Location = loc
	case *actor.ShoppingContext:
		c.Location = loc
	case *actor.EntertainmentContext:
		c.Location = loc
	case *actor.RestingContext:
		c.Location = loc
	default:
		return false
	}
	return true
}

package player

import (
	"context"
	"fmt"
	"unicode"

	"github.com/dnd-llm/dnd-llm/internal/application/knowledge"
	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/actor"
	"github.com/dnd-llm/dnd-llm/internal/domain/entity"
	"github.com/dnd-llm/dnd-llm/internal/domain/event"
	"github.com/dnd-llm/dnd-llm/internal/domain/memory"
	"github.com/dnd-llm/dnd-llm/internal/rutext"
	"go.uber.org/zap"
)

// The verdict engine: facts before prose. The parser-sensor reads the deed's
// target, instrument and social charge off the player's own words; this file
// grounds them in the scene and computes the consequences DETERMINISTICALLY —
// events, emotions, relationships, memories, entity mutations — all committed
// before the narrator says a word. The narrator then renders the committed
// facts and physically cannot declaw them (the old order, prose first and
// facts read off the prose, is how an arson became «касаешься стула»).

// verdictKind classifies what the deed actually amounts to.
type verdictKind int

const (
	// verdictPlain: neutral or ungrounded — prose only, no world changes.
	verdictPlain verdictKind = iota
	// verdictAssault: hostile act on a person.
	verdictAssault
	// verdictKindness: friendly act on a person.
	verdictKindness
	// verdictTransform: a deed that changes a present thing — the sensor
	// selected a catalogue effect (burn, shatter, soak, paint…) and its means
	// are at hand. Hostile or neutral; the charge drives the witnesses' reaction.
	verdictTransform
	// verdictImpotent: hostile act on an entity without the means — an honest
	// refusal, not a softened scene.
	verdictImpotent
	// verdictRevelation: a neutral deed that fulfils a rumor's latent hook — the
	// player performed the rumored ritual at the right place, so the promised
	// payoff lands instead of "nothing happens".
	verdictRevelation
)

// verdict is the deterministic outcome of one free-form deed.
type verdict struct {
	kind      verdictKind
	targetNPC *actor.Actor
	targetEnt *entity.Entity
	effect    string   // a catalogue effect key, or "" — see domain/entity/effect.go
	hostile   bool     // the deed's charge was hostile (drives witness reaction + disposition)
	facts     []string // closed-template sentences for the renderer
	// lawConfront is the watch's deterministic challenge when a crime happens
	// before a guard — appended verbatim after the prose so the narrator cannot
	// drop it (the law's reaction is a committed consequence, not a flourish).
	lawConfront string
	// Revelation payload: the fulfilled hook's promised consequence and the id
	// of the rumor that planted it (the fulfillment marker keys off it).
	hookPayoff  string
	hookRumorID string
}

// presentThings lists the entities physically in the scene: here, plus what the
// player and co-located NPCs carry.
func (s *TurnService) presentThings(ctx context.Context, tc *turnContext) []*entity.Entity {
	if s.knowledge == nil {
		return nil
	}
	holders := []domain.ActorID{tc.player.ID}
	for _, a := range tc.coLocated() {
		holders = append(holders, a.ID)
	}
	present, err := s.knowledge.ListPresent(ctx, knowledge.Scope{
		WorldID:  tc.worldID,
		ActorID:  tc.player.ID,
		Location: tc.player.GetCurrentLocation(),
	}, holders)
	if err != nil {
		return nil
	}
	return present
}

// entityPresent reports whether an entity id is among the scene's physical contents.
func entityPresent(present []*entity.Entity, id domain.EntityID) bool {
	for _, e := range present {
		if e.ID == id {
			return true
		}
	}
	return false
}

// fireMeansAtHand returns a PORTABLE fire source the player can WIELD to carry a
// flame to the target — a torch, a candle, a lit brand. A fixed installation (a
// hearth, a forge: KindFeature) is a fire SOURCE but not a means: you cannot scoop
// its flame up in bare hands. So a portable fire item already present is preferred;
// failing that, the place's latent fire prop (the tavern's wall torch) is
// crystallized on reach, exactly as the target thing is. nil means there is fire
// about but nothing to carry it — an honest impotence, not "fire from nowhere".
func (s *TurnService) fireMeansAtHand(ctx context.Context, tc *turnContext, present []*entity.Entity) *entity.Entity {
	if m := portableFire(present); m != nil {
		return m
	}
	return s.crystallizeFireProp(ctx, tc)
}

// portableFire returns the first present fire source a player could take in hand — a
// fire-category thing that is CARRIABLE (a torch, a candle). A hearth (feature) is
// fixed; a flame (substance) slips through fingers: neither can be wielded.
func portableFire(present []*entity.Entity) *entity.Entity {
	for _, e := range present {
		if e.Category == entity.CategoryFire && e.Kind.Carriable() {
			return e
		}
	}
	return nil
}

// crystallizeFireProp births the location's latent portable fire prop (a torch, a
// candle) so the player can take it in hand — the means twin of crystallizeAt,
// keyed by CATEGORY (fire) rather than the player's words, since the player named
// the TARGET, not the brand they reach for. nil when the fund holds no portable
// flame (only a fixed hearth, or nothing).
func (s *TurnService) crystallizeFireProp(ctx context.Context, tc *turnContext) *entity.Entity {
	if s.crystallizer == nil {
		return nil
	}
	here := tc.player.GetCurrentLocation()
	loc := tc.locations[here]
	if loc == nil {
		return nil
	}
	var props []knowledge.Prop
	if s.furnisher != nil {
		props = s.furnisher.EnsureFund(ctx, tc.worldPremise, tc.worldEra, loc)
	} else {
		props = knowledge.PropsFromState(loc.State)
	}
	for i := range props {
		if entity.Category(props[i].Category) != entity.CategoryFire {
			continue
		}
		return s.crystallizer.CrystallizeProp(ctx, knowledge.CrystallizeInput{
			WorldID:     tc.worldID,
			Location:    here,
			Mention:     props[i].Name,
			Props:       props,
			SourceActor: tc.player.ID,
			Tick:        tc.tick,
		}, &props[i])
	}
	return nil
}

// computeVerdict decides what a free-form deed actually does. A deed aimed at a
// PERSON is assault or kindness by its charge. Otherwise the deed may change a
// THING: the sensor grounds WHICH present thing and HOW from closed enums of
// what truly exists — no parser role-splitting, no hallucination. Anything
// ungrounded degrades toward plain — the safe failure.
func (s *TurnService) computeVerdict(ctx context.Context, tc *turnContext, action extractedDeed) *verdict {
	v := &verdict{kind: verdictPlain}

	if action.Target != "" {
		v.targetNPC = tc.groundedCoLocatedActor(action.Target)
	}

	switch {
	case v.targetNPC != nil:
		s.fillPersonVerdict(tc, v.targetNPC, action.Charge, v)
	default:
		s.computeThingEffect(ctx, tc, action, v)
	}

	// A neutral deed that would otherwise do nothing may fulfil a rumor's latent
	// hook: the player performed the rumored ritual at the right place and time.
	// Checked only when the deed grounds to nothing — an assault is still an
	// assault, a kindness still a kindness; the hook rescues "nothing happens".
	if v.kind == verdictPlain {
		if ph := s.matchHook(ctx, tc, action); ph != nil {
			v.kind = verdictRevelation
			v.facts = []string{ph.hook.Payoff}
			v.hookPayoff = ph.hook.Payoff
			v.hookRumorID = ph.rumorID
		}
	}

	return v
}

// fillPersonVerdict sets a verdict aimed at a PERSON by the deed's charge: a
// hostile deed is an assault (with the watch's challenge if a guard saw it), a
// friendly one a kindness, anything else plain. Shared by the explicit-Target
// path and the deed-text fallback (when the parser left the person in the deed
// rather than the Target slot — «обнять Купца Изольта» came back with an empty
// Target and the man's name folded into the deed).
func (s *TurnService) fillPersonVerdict(tc *turnContext, person *actor.Actor, charge string, v *verdict) {
	v.targetNPC = person
	switch charge {
	case chargeHostile:
		v.kind = verdictAssault
		// Witnesses are everyone co-located except the target itself.
		v.facts = assaultFacts(person.Identity.Name, len(tc.coLocated())-1)
		// A crime before the watch draws the law's challenge — the victim,
		// even if a guard, leads nothing; they are the one struck.
		v.lawConfront = lawConfrontationFact(guardsAmong(witnessesExcept(tc.coLocated(), person.ID)))
	case chargeFriendly:
		v.kind = verdictKindness
		v.facts = []string{fmt.Sprintf("Тёплый жест доходит до цели: %s принимает его.", person.Identity.Name)}
	default:
		v.facts = plainFacts()
	}
}

// computeThingEffect fills the verdict for a non-person deed. Two separate
// concerns, each its right tool: WHAT effect is CLASSIFIED by the sensor (the
// player's verb → a catalogue key, independent of the thing so its nature can't
// bias the choice); WHICH thing is grounded DETERMINISTICALLY (the player named
// it). The effect is resolved first: a deed that changes nothing (touch, look)
// needs no thing at all, and an effect with no means at hand is «нечем»
// regardless of the thing.
func (s *TurnService) computeThingEffect(ctx context.Context, tc *turnContext, action extractedDeed, v *verdict) {
	effect := ""
	if s.selector != nil {
		if e, err := s.selector.Classify(ctx, action.Deed); err != nil {
			s.logger.Warn("effect classification failed; the deed changes nothing", zap.Error(err))
		} else {
			effect = e
		}
	}
	if effect == "" {
		// No thing changes — but the deed may be aimed at a person the parser
		// put in the Who slot («обнять Изольта»): a kindness, not nothing.
		s.fizzleOrPerson(ctx, tc, action, v)
		return
	}

	present := s.presentThings(ctx, tc)

	// WHICH thing it affects is the one the deed names. A present entity first;
	// otherwise a latent prop of the place, materialized on demand — a thing
	// becomes real the moment ANY deed reaches for it, exactly as the take-path
	// crystallizes on pickup. Prop materialization is deed-agnostic, so «разбить
	// кружку» reaches the tavern's mug just as «взять кружку» does.
	// The thing the deed names, as the turn's grounding resolved it — kept only if it
	// is physically HERE (a deed reaches what is present, not a thing merely known of
	// elsewhere). Otherwise a latent prop of the place, materialized on demand.
	thing := tc.groundedThing(action.Deed)
	if thing != nil && !entityPresent(present, thing.ID) {
		thing = nil
	}
	if thing == nil {
		thing = s.crystallizeAt(ctx, tc, action.Deed)
	}
	if thing == nil {
		// No thing here — perhaps a person is (checked AFTER the thing so a
		// thing-deed never turns into an assault on a possessive owner). Else the
		// thing the deed names simply isn't here: honest «нет такого», NOT «нечем»
		// (the means may well be at hand — it's the табурет that's missing, not
		// the torch), so the renderer doesn't invent a means problem.
		if p := s.deedPerson(ctx, tc, action); p != nil {
			s.fillPersonVerdict(tc, p, action.Charge, v)
			return
		}
		if action.Charge == chargeHostile {
			v.kind = verdictImpotent
			v.facts = absentThingFacts(action.Deed)
		} else {
			v.facts = plainFacts()
		}
		return
	}

	// Some effects only bite a thing in a particular state, the preconditions
	// living in the catalogue (the single source of an effect's mechanics):
	//   - extinguish needs an active fire — you cannot put out what is not alight,
	//     so it never overwrites a settled condition (a charred ruin stays charred);
	//   - burning needs a thing whose MATERIAL catches (the same CatchesFire the
	//     spread uses) — so arson and spread share ONE gate: a wooden hut burns, a
	//     river or clay mug does not, and ash never reignites.
	// A failed precondition is impotent, not a transformation.
	if entity.EffectNeedsHazard(effect) && thing.StateText(entity.StateHazard) == "" {
		v.kind = verdictImpotent
		v.facts = noBlazeFacts(action.Deed)
		return
	}
	if entity.EffectNeedsFlammable(effect) && !thing.CatchesFire() {
		v.kind = verdictImpotent
		v.facts = unflammableFacts(action.Deed)
		return
	}

	// A fire deed needs a flame the player can WIELD — resolved NOW, after the
	// target and its material are confirmed, so a brand is never crystallized for a
	// deed that fizzles. No portable flame (only a fixed hearth, or nothing) → an
	// honest «нечем», not fire conjured from bare hands.
	var means *entity.Entity
	if effectRequires(effect) == entity.MeansFire {
		if means = s.fireMeansAtHand(ctx, tc, present); means == nil {
			v.kind = verdictImpotent
			v.facts = impotentFacts(action.Deed)
			return
		}
	}

	v.kind = verdictTransform
	v.targetEnt = thing
	v.effect = effect
	v.hostile = action.Charge == chargeHostile
	v.facts = transformFacts(thing.Name, effect, len(tc.coLocated()), action.Charge)
	// Name the flame the player took in hand, so the narrator says «снимаешь факел
	// со стены и подносишь к табурету…» instead of conjuring fire from nowhere.
	if means != nil {
		v.facts = append([]string{fmt.Sprintf("Берёшь в руку источник огня — %s.", means.Name)}, v.facts...)
	}
	// Destroying or endangering before the watch is a crime they see — the law
	// confronts. (A neutral change — washing, painting — is no one's business.)
	// Unlike an assault (which excludes the struck victim), a property crime does
	// NOT exclude a guard owner: their thing was ruined, not their person, so they
	// are fit to enforce — and excluding them would let the law ignore a crime
	// when the only guard present is the owner.
	if v.hostile || entity.IsHazardEffect(effect) {
		v.lawConfront = lawConfrontationFact(guardsAmong(tc.coLocated()))
	}
}

// fizzleOrPerson routes a deed that touched no thing. The parser sometimes
// leaves the person a deed is aimed at in the deed text instead of the Target
// slot («обнять Купца Изольта» → empty Target); if the deed names a co-located
// person, it is a deed aimed at THEM (kindness/assault by charge). Otherwise it
// changed nothing. Checked only AFTER thing-grounding, so a deed naming a thing
// («разбить книгу Мирры») stays a thing-deed and never becomes an assault.
func (s *TurnService) fizzleOrPerson(ctx context.Context, tc *turnContext, action extractedDeed, v *verdict) {
	if p := s.deedPerson(ctx, tc, action); p != nil {
		s.fillPersonVerdict(tc, p, action.Charge, v)
		return
	}
	s.fizzle(action, v)
}

// deedPerson grounds the person a deed is aimed at: the Who (addressee) slot most
// often, but the parser sometimes folds them into the deed text — read both from the
// turn's grounding, restricted to who is HERE (a deed acts on the present).
func (s *TurnService) deedPerson(_ context.Context, tc *turnContext, action extractedDeed) *actor.Actor {
	if p := tc.groundedCoLocatedActor(action.Who); p != nil {
		return p
	}
	return tc.groundedCoLocatedActor(action.Deed)
}

// fizzle records a deed that changed nothing (no thing to act on at all): an
// honest «нечем» for hostile intent, plain prose otherwise.
func (s *TurnService) fizzle(action extractedDeed, v *verdict) {
	if action.Charge == chargeHostile {
		v.kind = verdictImpotent
		v.facts = impotentFacts(action.Deed)
	} else {
		v.facts = plainFacts()
	}
}

// absentThingFacts is the honest refusal when a deed's MEANS are at hand but the
// thing it names is not HERE — distinct from «нечем» (no means), so the renderer
// doesn't invent a means problem for a player who is plainly holding the torch.
func absentThingFacts(deed string) []string {
	return []string{fmt.Sprintf("Здесь нет того, на что направлено действие: «%s».", deed)}
}

// extractedDeed is the sensor reading the verdict engine consumes — built
// from a parsed action by the callers (doFreeform composes it from the
// parser-sensor fields; doAttack and the failed theft build it directly).
type extractedDeed struct {
	Deed       string // инфинитивная фраза
	Target     string
	Who        string // addressee slot — where the parser often puts the person
	Instrument string
	Charge     string // closed: chargeHostile | chargeFriendly | "" (neutral)
}

// The parser-sensor's closed charge vocabulary.
const (
	chargeHostile  = "враждебно"
	chargeFriendly = "дружелюбно"
)

// Lasting relationship-fear instilled by a hostile act. A victim past the
// IsFearful threshold (50) is met warily long after the blow; ~2 attacks cross
// it. Witnesses learn more slowly.
const (
	fearOnAttackVictim  = 35
	fearOnAttackWitness = 12
	// fearOnHazardWitness is the LASTING fear left by watching the player set the
	// place ablaze and having to flee it — a hazard endangers everyone present,
	// so an onlooker is a victim of the danger, not a mere bystander to a blow.
	// One arson crosses the wary threshold (>40); it compounds toward cowering.
	fearOnHazardWitness = 45
	// fearOnPropertyOwner is the LASTING fear left in someone whose own thing the
	// player ruined before their eyes — destroying what is theirs is a hostile
	// act against THEM, weighed like an assault on their person (the victim's 35),
	// not like the ambient half-hit an onlooker takes.
	fearOnPropertyOwner = 35
	// giftFearRelief is how much a gift thaws an NPC's lasting fear of the
	// 

