	Actors       actor.ActorRepository
	Worlds       world.WorldRepository
	Events       event.EventStore
	Sim          *simulation.Controller
	Locs         locationLister
	Morph        *morph.Service
	Memory       *appmemory.MemoryService
	Behavior     *actor.BehaviorSystem
