)

// ErrNotJoined means the player has no actor in this world yet.
var ErrNotJoined = errors.New("player has not joined this world")

// Turn progress stages streamed to the client while the LLM works.
const (
	StageIntent = "intent" // понимаю, что игрок имеет в виду
	StageActing = "acting" // исполняю действия игрока
	StageWorld  = "world"  // мир делает свой ход
)

// tickBudget bounds the world's own tick, independent of the turn deadline:
// a worst-case tick (every NPC re-deciding after a reseed) is a batched LLM
// volley that must finish and COMMIT even when the player's replies already
// ate most of the turn. The client may stop waiting; the world must not tear.
const tickBudget = 150 * time.Second

// locationLister is the slice of the persistence layer the service needs to
// name and enumerate locations.
type locationLister interface {
	ListLocationStatesByWorld(ctx context.Context, worldID domain.WorldID) ([]*persistence.LocationState, error)
}

// NPCLine is one NPC reply addressed to the player. The player-facing badge
// is the GESTURE (body language — generated with the words, so it cannot
// contradict them); the emotion label stays internal: it drives relationship
// drift, and shown next to the text it kept reading as a mismatch
// («(радость): ничего не знаю»).
type NPCLine struct {
	ActorID domain.ActorID
	Name    string
	Text    string
	Gesture string
	Emotion string
}

// TurnEventView is a world event of the tick, rendered for the player's feed.
type TurnEventView struct {
	ActorName string
	Text      string
	Type      string
}

// TurnResult is everything one player turn produced.
type TurnResult struct {
	// Narrative describes what the player's own actions led to.
	Narrative string
	// Question, when set, is a clarification request: the input could not be
	// (fully) executed and the world did NOT tick for the unclear part.
	Question string
	// Replies are NPC lines spoken directly to the player this turn.
	Replies []NPCLine
	// Events are the tick's world events visible from the player's location.
	Events []TurnEventView
	// Tick is the world tick the turn's events were committed on. One
	// semantics for every outcome — full turn, failed tick, partial turn: the
	// tick the turn played out in (0 only when nothing executed at all).
	Tick int
	// Shop is the merchant's window a browse rendered this turn (engine
	// prices); nil otherwise. The UI shows it as a panel; acting on it stays
	// textual.
	Shop *ShopView
	// Emotion is the player's explicit emotional state this turn (L5). Set whenever the
	// player named a non-calm feeling — pure state («прихожу в ярость») or alongside a
	// deed («в ярости бью стражника»). It is resolved as a contested self-regulation and
	// applied to the actor (see self_regulation.go); surfaced here for the client too.
	// Empty / StateCalm = none.
	Emotion string
}

// TurnService turns one chat message into world changes: parse → ground
// mentions → validate → execute as events → one world tick → a readable
// result. One turn at a time: the mutex keeps player turns from interleaving
// with each other.
type TurnService struct {
	parser       *extraction.IntentParser
	resolver     *extraction.MentionResolver
	dialogue     *appllm.DialogueService
	narrator     *appllm.NarrationService
	selector     *appllm.EffectSelector
	knowledge    *knowledge.Service
	scribe       *knowledge.Scribe
	mutator      *knowledge.Mutator
	crystallizer *knowledge.Crystallizer
	furnisher    *knowledge.Furnisher
	cues         *appllm.CueClassifier // judges a deed against a rumor hook's cue / an NPC's goal aim
	weaver       *appweaver.Service
	goals        *appgoal.GoalTracker // the player can advance a co-located NPC's goal by helping
	doom         appweaver.Doom       // lands a goal's outcome the player drove to completion
	actors       actor.ActorRepository
	worlds       world.WorldRepository
	events       event.EventStore
	sim          *simulation.Controller
	locs         locationLister
	morph        *morph.Service
	// The verdict engine's consequence channels: synchronous emotions and
	// memories for the deed's target and witnesses (facts before prose).
	memory   *appmemory.MemoryService
	behavior *actor.BehaviorSystem
	logger   *zap.Logger

	// checkRoll resolves an uncertain deed (self-regulation, …) into a graded
	// outcome. Injectable so tests force a tier; defaults to the deterministic dice.
	checkRoll func(seed int64, pool int, pos check.Position) check.Outcome

	// mu serializes player turns: one turn at a time. Conversation state is
	// deliberately NOT process state — the active conversation is folded from
	// the event log per turn (see conversation.go), so it survives restarts
	// and can never disagree with what the log says happened.
	mu sync.Mutex
}

// TurnServiceDeps bundles the service's dependencies.
type TurnServiceDeps struct {
	Parser       *extraction.IntentParser
	Resolver     *extraction.MentionResolver
	Dialogue     *appllm.DialogueService
	Narrator     *appllm.NarrationService
	Selector     *appllm.EffectSelector
	Knowledge    *knowledge.Service
	Scribe       *knowledge.Scribe
