}

// turnContext is everything one turn reads repeatedly: the player, the world
// clock, the location directory and the live roster, loaded once up front.
type turnContext struct {
	player       *actor.Actor
	worldID      domain.WorldID
	worldPremise string // the world's authored description (canon for prompts)
	worldEra     string // the world's time-and-setting canon (keeps generation in period)
	input        string // the player's raw message this turn — their expressed intent, the
	//                     authoritative signal of what they are doing (an observe leaves no
	//                     event trace, but it is right here); read by the weaver scene.
	tick      domain.Tick
	gameTime  domain.GameTime
	locations map[domain.LocationID]*persistence.LocationState
	roster    []*actor.Actor // all living actors except the player

	// arrivedAt marks a location the player moved to earlier THIS turn, so a
	// follow-up observe («выхожу на площадь и осматриваюсь») doesn't repeat
	// the arrival description verbatim.
	arrivedAt domain.LocationID

	// conv caches the turn's folded conversation; convLoaded distinguishes
	// "not folded yet" from "folded: no active talk".
	conv       *Conversation
	convLoaded bool

	// mentions is the turn's grounded MentionSet (С2): every entity the player
	// referred to, resolved to its world id. The deterministic hooks read it by
	// membership; it is journaled for replay. Filled in ProcessInput after the parse.
	mentions *extraction.MentionSet

	// expField caches the turn's experiential field — the player's reference scope
	// (here-now ∪ visited ∪ remembered ∪ known) assembled once for grounding;
	// fieldLoaded distinguishes "not assembled yet" from "assembled: empty".
	expField   *experientialField
	fieldLoaded bool
}

func (tc *turnContext) locationName(id domain.LocationID) string {
	if loc, ok := tc.locations[id]; ok {
		return loc.Name
	}
	return string(id)
}

func (tc *turnContext) locationDescription(id domain.LocationID) string {
	if loc, ok := tc.locations[id]; ok {
		if d, _ := loc.State["description"].(string); d != "" {
			return d
		}
	}
	return ""
}

// actorByID finds a roster NPC by id, nil when unknown.
func (tc *turnContext) actorByID(id domain.ActorID) *actor.Actor {
	for _, a := range tc.roster {
		if a.ID == id {
			return a
		}
	}
	return nil
}

// coLocated returns the living NPCs standing where the player stands.
func (tc *turnContext) coLocated() []*actor.Actor {
	here := tc.player.GetCurrentLocation()
	var out []*actor.Actor
	for _, a := range tc.roster {
		if a.GetCurrentLocation() == here {
			out = append(out, a)
		}
	}
	return out
}

// ProcessInput plays one full player turn. progress (optional) is invoked with
// a Stage* constant as the turn moves through its phases.
func (s *TurnService) ProcessInput(
	ctx context.Context,
	userID, text string,
	progress func(stage string),
) (*TurnResult, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	if progress == nil {
		progress = func(string) {}
	}

	worldID := s.sim.WorldID()
	ctx = repository.WithWorldID(ctx, worldID)

	tc, err := s.loadTurnContext(ctx, worldID, userID)
	if err != nil {
		return nil, err
	}
	tc.input = text

	// The player speaking IS the claim to drive the world: if the simulation
	// runs autonomously (e.g. after an operator resume), take the controls back.
	if s.sim.Mode() != simulation.ModePlayerDriven {
		if err := s.sim.SetMode(simulation.ModePlayerDriven); err != nil {
			return nil, fmt.Errorf("switch to player-driven mode: %w", err)
		}
	}

	// A felled player cannot act. If they are merely DOWN (unconscious), the world
	// resolves their fate while they only watch: a willing soul may brave the danger
	// to drag them clear — or, if they have terrified the town, the hazard finishes
	// them. If they are DEAD, the story is over for this character. Either way, no
	// parse: the player's words cannot move a body that will not answer.
	if tc.player.IsDead() {
		return &TurnResult{Narrative: "Ты мёртв. Для этого героя история окончена — чтобы начать заново, пересоздай мир."}, nil
	}
	if playerUnconscious(tc.player) {
		return s.resolveIncapacitated(ctx, worldID, userID, tc), nil
	}

	// Stage 0: parse the message into atomic actions. Gibberish is not a
	// server error — it is a question back to the player.
	progress(StageIntent)
	parsed, _, err := s.parser.Parse(ctx, text, s.parseContext(ctx, tc))
	if errors.Is(err, extraction.ErrNoActions) {
		return &TurnResult{Question: "Не понял, что ты хочешь сделать — опиши действие иначе."}, nil
	}
	if err != nil {
		return nil, fmt.Errorf("parse input: %w", err)
	}
	// A state-only turn: L5 found a feeling with no deed («прихожу в ярость») and routed it
	// out of the deed pipeline (Actions empty, Emotion set). The feeling IS the turn —
	// resolve it as a CONTESTED self-regulation (the world opposes it; a roll decides how
	// much lands), then let the world tick so the new state lives and NPCs perceive it.
	// NOT gibberish — that path is ErrNoActions above.
	if len(parsed.Actions) == 0 {
		return s.stateOnlyTurn(ctx, tc, parsed.Emotion)
	}

	// A deliberate wait is its own lane: it SKIPS time (a full hour), past the round packer's
	// per-turn tick ceiling, so the city turns to a new hour and moves on its schedules — the
	// metronome the player reaches by letting time pass, not by acting.
	if isPureWait(parsed.Actions) {
		return s.waitTurn(ctx, tc)
	}

	for i, a := range parsed.Actions {
		s.logger.Debug("player action parsed",
			zap.Int("n", i),
			zap.String("action", a.Action),
			zap.String("who", a.Who),
			zap.String("where", a.Where),
			zap.String("topic", a.Topic),
			zap.String("utterance", a.Utterance),
			zap.String("modality", a.Modality),
			zap.String("trigger", a.Trigger),
			zap.String("influence", a.InfluenceMode),
			zap.String("stake", a.InfluenceStake))
	}

	// С2: one grounding pass — resolve every entity the player referred to into a
	// MentionSet (present ∪ knowledge scope), so the deterministic hooks fire by
	// membership and the references are journaled for replay.
	tc.mentions = s.groundTurn(ctx, tc, parsed.Actions)
	s.recordMentions(ctx, tc)

	// The player may have voiced a FEELING alongside the deed («в ярости бью стражника»).
	// Resolve it as a contested self-regulation BEFORE the deeds run, so the tick's NPC
	// perception — and the deeds' own checks (Stage 3) — see the player's true emotional
	// state, journaled ahead of the first tick.
	if parsed.Emotion != "" && parsed.Emotion != extraction.StateCalm {
		s.resolveSelfRegulation(ctx, tc, parsed.Emotion)
	}

	// Stage 1: pack the parsed actions into ROUNDS by their estimated duration —
	// the unit at which the world stops to react. Quick deeds bundle into one
	// round (one world reaction); a long deed's round spans several game-ticks.
	// The world's clock advances by what the actions actually took (bounded by
	// the tick ceiling), so each round perceives the previous round's reaction —
	// the fix for "do two things in sequence" without skipping time.
	rounds := packRounds(parsed.Actions, roundQuantumSeconds, tc.gameTime.SecondsPerTick, maxTicksPerTurn)

	result := &TurnResult{}
	if parsed.Emotion != extraction.StateCalm {
		result.Emotion = parsed.Emotion
	}
	var pieces []string
	executedAny := false      // did ANY round commit + tick? (gates Tick/weaver)
	var firstTick domain.Tick // the tick the turn opened on (result.Tick)
	var lastTick domain.Tick  // the last full tick that ran (weaver scene)
	haveTick := false

	for ri := 0; ri < len(rounds); ri++ {
		r := rounds[ri]

		// Execute this round's actions against the CURRENT (freshly-reloaded) tc.
		// A clarification stops the turn: this round still reacts to what it DID
		// commit, then the unclear action and everything after wait for an answer.
		progress(StageActing)
		acted := false
		clarified := false
		for _, action := range r.actions {
			outcome, err := s.executeAction(ctx, tc, action)
			if err != nil {
				return nil, err
			}
			if outcome.question != "" {
				result.Question = outcome.question
				clarified = true
				break
			}
			acted = true
			if outcome.narrative != "" {
				pieces = append(pieces, outcome.narrative)
			}
			if outcome.reply != nil {
				result.Replies = append(result.Replies, *outcome.reply)
			}
			if outcome.shop != nil {
				result.Shop = outcome.shop
			}
		}
		// The round's first action needed clarification: nothing committed here.
		// Earlier rounds stand (already ticked). Stop and ask.
		if !acted {
			break
		}

		// The weaver's prepared move lands ONCE per turn, before the first round's
		// tick — the world perceives it exactly like the player's own events. Its
		// prose joins the narrative as one more piece.
		if !executedAny {
			firstTick = tc.tick
			if s.weaver != nil {
				if wt := s.weaver.Commit(ctx, s.weaverScene(ctx, tc, tc.tick)); wt != "" {
					pieces = append(pieces, wt)
				}
			}
		}
		executedAny = true

		// The world reacts to this round: r.ticks game-ticks (the last a full
		// deliberation tick, the rest cheap reflex ticks). The tick gets its own
		// budget, detached from the turn deadline: a tick that dies mid-flight must
		// still commit — the client may stop waiting, the world must not tear.
		progress(StageWorld)
		tickCtx, cancelTick := context.WithTimeout(context.WithoutCancel(ctx), tickBudget)
		tickRes, err := s.sim.StepRoundAsPlayerTurn(tickCt

[…truncated middle of file: 11065 bytes / ~296 lines dropped to fit prompt budget…]

t := s.narrateDownDrama(ctx, tc, downEvents); drama != "" {
		pieces = append(pieces, drama)
		result.Events = s.visibleEvents(tc, rest)
	} else {
		result.Events = s.visibleEvents(tc, downEvents)
	}
	result.Narrative = strings.Join(pieces, "\n\n")
	return result
}

// narrateDownDrama pulls the down-and-out FACTS out of a tick's events (a rescuer
// braving danger, first aid, a death) and renders them through the LLM narrator —
// facts before prose, like any committed deed. The core authored the closed-
// template facts; the narrator colours them. Returns the prose and the remaining
// events to surface as structured turn-events. Empty prose when no down-drama
// happened; a narration failure falls back to the facts plainly (never lost).
func (s *TurnService) narrateDownDrama(ctx context.Context, tc *turnContext, events []*event.GameEvent) (string, []*event.GameEvent) {
	// Resolve actor names so the rescuer who ACTS in each fact can be named
	// explicitly to the narrator — the clear entity link that stops the 4B from
	// blurring «Перевозчик Кузь вытаскивает тебя» into «кто-то».
	names := make(map[domain.ActorID]string, len(tc.roster)+1)
	for _, a := range tc.roster {
		if a.Identity != nil {
			names[a.ID] = a.Identity.Name
		}
	}
	if tc.player.Identity != nil {
		names[tc.player.ID] = tc.player.Identity.Name
	}

	var facts, participants []string
	seen := make(map[domain.ActorID]bool)
	rest := make([]*event.GameEvent, 0, len(events))
	for _, e := range events {
		if d, ok := e.Data.(event.RandomEventEventData); ok && d.Category == "rescue" {
			if f := strings.TrimSpace(d.Description); f != "" {
				facts = append(facts, f)
			}
			if n, ok := names[e.ActorID]; ok && e.ActorID != tc.player.ID && !seen[e.ActorID] {
				participants = append(participants, n)
				seen[e.ActorID] = true
			}
			continue
		}
		rest = append(rest, e)
	}
	if len(facts) == 0 {
		return "", events
	}
	if s.narrator == nil {
		return strings.Join(facts, " "), rest
	}
	in := s.narrateFactsInput(ctx, tc, "лишиться чувств в беде и ждать, чем всё кончится", facts, "", false)
	in.Participants = participants
	prose, err := s.narrator.NarratePlayerAction(ctx, in)
	if err != nil || strings.TrimSpace(prose) == "" {
		s.logger.Warn("down-drama narration failed; surfacing facts plainly", zap.Error(err))
		return strings.Join(facts, " "), rest
	}
	return prose, rest
}

func (s *TurnService) visibleEvents(tc *turnContext, events []*event.GameEvent) []TurnEventView {
	here := tc.player.GetCurrentLocation()
	names := make(map[domain.ActorID]string, len(tc.roster)+1)
	for _, a := range tc.roster {
		names[a.ID] = a.Identity.Name
	}
	names[tc.player.ID] = tc.player.Identity.Name
	nameOf := func(id domain.ActorID) string {
		if n, ok := names[id]; ok {
			return n
		}
		return "кто-то"
	}

	var out []TurnEventView
	// The player's own fire harm is coalesced into ONE line per call, not one per
	// tick: a long wait in a blaze fires a damage event every tick, but the player
	// reads "пламя обжигает тебя" once, escalated if the heat felled them.
	playerBurned, playerDowned := false, false
	for _, e := range events {
		var text string
		switch data := e.Data.(type) {
		case event.DamageEventData:
			// Only the player's OWN burns surface here, second person; an NPC's harm
			// reaches the player through perception, not this feed.
			if data.DamageType != "fire" || data.VictimID != tc.player.ID || e.LocationID != here {
				continue
			}
			playerBurned = true
			if data.Killed || data.RemainingHP <= 0 {
				playerDowned = true
			}
			continue
		case event.DialogueEventData:
			if e.LocationID != here {
				continue
			}
			text = fmt.Sprintf("«%s»", strings.TrimSpace(data.Text))
			// A line addressed to another NPC names its listener — otherwise a
			// background conversation reads as someone talking to themselves.
			// Nominative apposition keeps it morphology-safe.
			if len(data.ListenerIDs) > 0 && data.ListenerIDs[0] != tc.player.ID {
				text += fmt.Sprintf(" (собеседник: %s)", nameOf(data.ListenerIDs[0]))
			}
		case event.RumorHeardEventData:
			if data.HearerID != tc.player.ID {
				continue
			}
			text = fmt.Sprintf("шепчет: «%s»", strings.TrimSpace(data.Rumor))
			out = append(out, TurnEventView{ActorName: nameOf(data.SourceID), Text: text, Type: string(e.Type)})
			continue
		case event.ObservationEventData:
			if e.LocationID != here || data.ActorID == tc.player.ID {
				continue
			}
			text = strings.TrimSpace(data.Description)
		case event.RandomEventEventData:
			// Ambient happenings: location-bound ones only where the player
			// stands; town-wide shifts are felt everywhere. Verbatim prose
			// without an actor line — the world itself speaks. (The down-and-out
			// drama, category "rescue", is pulled out upstream by narrateDownDrama
			// and rendered through the narrator, so it never reaches here.)
			if data.LocationID != "" && domain.LocationID(data.LocationID) != here {
				continue
			}
			out = append(out, TurnEventView{ActorName: "", Text: strings.TrimSpace(data.Description), Type: string(e.Type)})
			continue
		case event.MovementEventData:
			from := domain.LocationID("")
			if data.FromLocationID != nil {
				from = *data.FromLocationID
			}
			switch {
			case data.ToLocationID == here:
				text = "приходит"
			case from == here:
				dest := tc.locationName(data.ToLocationID)
				if into := s.morph.Forms(dest).Into(); into != "" {
					text = "уходит " + into // «уходит в караульню»
				} else {
					text = fmt.Sprintf("уходит — %s", dest)
				}
			default:
				continue
			}
		default:
			continue
		}
		if text == "" {
			continue
		}
		out = append(out, TurnEventView{ActorName: nameOf(e.ActorID), Text: text, Type: string(e.Type)})
	}
	if playerBurned {
		text := "Пламя обжигает тебя."
		if playerDowned {
			text = "Пламя обжигает тебя — жар валит тебя наземь в дыму."
		}
		out = append(out, TurnEventView{ActorName: "", Text: text, Type: string(event.EventTypeDamageTaken)})
	}
	return out
}

package turn

import (
	"context"
	"testing"

	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/actor"
	"github.com/dnd-llm/dnd-llm/internal/domain/check"
	"github.com/dnd-llm/dnd-llm/internal/domain/entity"
)

// forceTier injects a fixed check outcome, so a rescue-stage test exercises a
// branch (a clean haul, a botch driven back) without depending on the dice — the
// dice themselves are tested in domain/check. The position passes through so a
// consequence that scales with it (a scorch) stays realistic.
func forceTier(t check.Tier) func(int64, int, check.Position) check.Outcome {
	return func(_ int64, _ int, pos check.Position) check.Outcome {
		return check.Outcome{Tier: t, Position: pos}
	}
}

// downedAt is a felled (unconscious, 0 HP) actor at loc — taken down the real way,
// so its DeathTracker is in the unconscious state the resolver reads.
func downedAt(loc domain.LocationID, maxHP int) *actor.Actor {
	a := mortalAt(loc, maxHP)
	// Down them in two small blows: a single hit of maxHP from full trips the
	// engine's massive-damage instant death (it measures excess off the already-
	// zeroed HP). Fire deals small per-tick doses, so this edge never bites in play.
	a.State.Physical.TakeDamage(maxHP-1, "test", false) // → 1 HP
	a.State.Physical.TakeDamage(1, "test", false)       // → 0 HP, unconscious
	return a
}

func named(a *actor.Actor, name string) *actor.Actor {
	a.Identity = actor.NewActorIdentity(name, actor.RaceHuman, actor.ClassFighter, 1)
	return a
}

// fearOf makes `a` dread `ofID` at the given level (a relationship the willingness
// check reads).
func fearOf(a *actor.Actor, ofID domain.ActorID, amount int) {
	rel := actor.NewActorRelationship(ofID)
	rel.Fear = amount
	a.State.Social.SetRelationship(ofID, rel)
}

func blaze(loc domain.LocationID) *fakeHazards {
	return &fakeHazards{byLoc: map[domain.LocationID][]*entity.Entity{
		loc: {burningThing2("Сруб «Лунного Брода»", entity.KindFeature, 0)},
	}}
}

// APPROACH (step 1): a willing soul elsewhere rushes INTO the fire toward the
// downed — they do NOT teleport the rescue; this tick only closes the distance.
func TestResolveDowned_ApproachStep(t *testing.T) {
	burning := domain.NewLocationID()
	safe := domain.NewLocationID()

	player := downedAt(burning, 10)
	player.Type = actor.ActorTypePlayer
	rescuer := named(mortalAt(safe, 10), "Купец Изольт")
	rescuer.Type = actor.ActorTypeStoryNPC
	byID := map[domain.ActorID]*actor.Actor{player.ID: player, rescuer.ID: rescuer}

	p := &TickProcessor{hazards: blaze(burning), checkRoll: forceTier(check.Clean)}
	_, dirty := p.resolveDowned(context.Background(), domain.NewGameTimeAt(5), domain.WorldID("w"), byID)

	if rescuer.State.GetCurrentLocation() != burning {
		t.Error("the approacher must rush INTO the danger toward the downed")
	}
	if player.State.GetCurrentLocation() != burning {
		t.Error("the player is not carried yet on the approach step")
	}
	if !player.State.Physical.IsUnconscious() {
		t.Error("the player stays senseless until tended (approach is not a teleported rescue)")
	}
	if !dirty[rescuer.ID] {
		t.Error("the moved approacher must be dirtied")
	}
}

// CARRY OUT (step 2): a willing soul ALREADY beside the downed hauls both to safety
// — the player still senseless (the tend comes next, in safety).
func TestResolveDowned_CarryStep(t *testing.T) {
	burning := domain.NewLocationID()
	refuge := domain.NewLocationID()

	player := downedAt(burning, 10)
	player.Type = actor.ActorTypePlayer
	carrier := named(mortalAt(burning, 10), "Капитан Дарой") // already beside the player
	carrier.Type = actor.ActorTypeStoryNPC
	bystander := mortalAt(refuge, 10) // marks `refuge` as a place to carry toward
	bystander.Type = actor.ActorTypeStoryNPC
	byID := map[domain.ActorID]*actor.Actor{player.ID: player, carrier.ID: carrier, bystander.ID: bystander}

	p := &TickProcessor{hazards: blaze(burning), checkRoll: forceTier(check.Clean)}
	_, dirty := p.resolveDowned(context.Background(), domain.NewGameTimeAt(5), domain.WorldID("w"), byID)

	if carrier.State.GetCurrentLocation() == burning {
		t.Error("the carrier must haul out of the fire")
	}
	if player.State.GetCurrentLocation() == burning {
		t.Error("the player must be carried out of the fire")
	}
	if !player.State.Physical.IsUnconscious() {
		t.Error("the carry does not revive — only the tend does")
	}
	if !dirty[player.ID] || !dirty[carrier.ID] {
		t.Error("both must be dirtied for persistence")
	}
}

// CARRY botch: strength and heat win — the carrier cannot lift the body clear, so
// BOTH remain in the fire this tick (the harm reflex, after, will bite them). The
// next tick tries again; a body left too long is lost to the blaze.
func TestResolveDowned_CarryBotchLeavesBothInFire(t *testing.T) {
	burning := domain.NewLocationID()
	refuge := domain.NewLocationID()

	player := downedAt(burning, 10)
	player.Type = actor.ActorTypePlayer
	carrier := named(mortalAt(burning, 10), "Капитан Дарой")
	carrier.Type = actor.ActorTypeStoryNPC
	bystander := mortalAt(refuge, 10) // a clear place exists to carry toward
	bystander.Type = actor.ActorTypeStoryNPC
	byID := map[domain.ActorID]*actor.Actor{player.ID: player, carrier.ID: carrier, bystander.ID: bystander}

	p := &TickProcessor{hazards: blaze(burning), checkRoll: forceTier(check.Botch)}
	events, dirty := p.resolveDowned(context.Background(), domain.NewGameTimeAt(5), domain.WorldID("w"), byID)

	if carrier.State.GetCurrentLocation() != burning || player.State.GetCurrentLocation() != burning {
		t.Error("a botched carry moves no one — both stay in the fire")
	}
	if dirty[carrier.ID] || dirty[player.ID] {
		t.Error("a botched carry moved no one, so nothing is dirtied by it")
	}
	if len(events) == 0 {
		t.Error("a botched carry still reports the struggle as a fact for the narrator")
	}
}

// CARRY at a cost (Mixed): the carrier hauls the body clear but takes the blaze's
// bite doing it — they reach safety AND lose HP. A costly success is still real risk.
func TestResolveDowned_CarryMixedScorchesCarrier(t *testing.T) {
	burning := domain.NewLocationID()
	refuge := domain.NewLocationID()

	player := downedAt(burning, 10)
	player.Type = actor.ActorTypePlayer
	carrier := named(mortalAt(burning, 10), "Капитан Дарой")
	carrier.Type = actor.ActorTypeStoryNPC
	bystander := mortalAt(refuge, 10)
	bystander.Type = actor.ActorTypeStoryNPC
	byID := map[domain.ActorID]*actor.Actor{player.ID: player, carrier.ID: carrier, bystander.ID: bystander}

	p := &TickProcessor{hazards: blaze(burning), checkRoll: forceTier(check.Mixed)}
	p.resolveDowned(context.Background(), domain.NewGameTimeAt(5), domain.WorldID("w"), byID)

	if carrier.State.GetCurrentLocation() == burning || player.State.GetCurrentLocation() == burning {
		t.Error("a costly success still gets both out of the fire")
	}
	if carrier.State.Physical.Health.Current >= 10 {
		t.Error("a Mixed haul must scorch the carrier — they pay for the rescue in blood")
	}
}

// APPROACH botch: a wall of heat throws the would-be rescuer back at the threshold —
// they do NOT reach the downed this tick (and so are not yet burned). Try next tick.
func TestResolveDowned_ApproachBotchDrivenBack(t *testing.T) {
	burning := domain.NewLocationID()
	safe := domain.NewLocationID()

	player := downedAt(burning, 10)
	player.Type = actor.ActorTypePlayer
	rescuer := named(mortalAt(safe, 10), "Купец Изольт")
	rescuer.Type = actor.ActorTypeStoryNPC
	byID := map[domain.ActorID]*actor.Actor{player.ID: player, rescuer.ID: rescuer}

	p := &TickProcessor{hazards: blaze(burning), checkRoll: forceTier(check.Botch)}
	events, dirty := p.resolveDowned(context.Background(), domain.NewGameTimeAt(5), domain.WorldID("w"), byID)

	if rescuer.State.GetCurrentLocation() != safe {
		t.Error("a driven-back approacher must NOT enter the fire this tick")
	}
	if dirty[rescuer.ID] {
		t.Error("an approacher who did not move must not be dirtied")
	}
	if len(events) == 0 {
		t.Error("the driven-back attempt is still reported as a fact for the narrator")
	}
}

// TEND (step 3): a willing soul beside a downed in SAFETY brings them round — the
// final step, and the rescue variant for a down with no hazard, only blood loss.
func TestResolveDowned_TendStep(t *testing.T) {
	safe := domain.NewLocationID()

	player := downedAt(safe, 10)
	player.Type = actor.ActorTypePlayer
	ally := named(mortalAt(safe, 10), "Сестра Велиша")
	ally.Type = actor.ActorTypeStoryNPC
	byID := map[domain.ActorID]*actor.Actor{player.ID: player, ally.ID: ally}

	// No hazards — the down is blood loss, an ally tends in place.
	p := &TickProcessor{hazards: &fakeHazards{byLoc: map[domain.LocationID][]*entity.Entity{}}}
	_, dirty := p.resolveDowned(context.Background(), domain.NewGameTimeAt(5), domain.WorldID("w"), byID)

	if player.State.Physical.IsUnconscious() {
		t.Error("an ally's first aid must bring a safely-downed player round")
	}
	if player.State.GetCurrentLocation() != safe {
		t.Error("first aid tends in place — the player is not moved")
	}
	if !dirty[player.ID] {
		t.Error("the tended player must be dirtied")
	}
}

// If everyone able fears the player too much, no one braves the fire — the town has
// turned from them, and the blaze is left to take its course (no approach, no carry).
func TestResolveDowned_TerrifiedTownAbandonsPlayer(t *testing.T) {
	burning := domain.NewLocationID()
	safe := domain.NewLocationID()

	player := downedAt(burning, 10)
	player.Type = actor.ActorTypePlayer
	coward := mortalAt(safe, 10)
	coward.Type = actor.ActorTypeStoryNPC
	fearOf(coward, player.ID, 80) // dreads the player → will not help
	byID := map[domain.ActorID]*actor.Actor{player.ID: player, coward.ID: coward}

	p := &TickProcessor{hazards: blaze(burning)}
	p.resolveDowned(context.Background(), domain.NewGameTimeAt(5), domain.WorldID("w"), byID)

	if coward.State.GetCurrentLocation() != safe {
		t.Error("a soul who dreads the player must not stir to help")
	}
	if player.State.GetCurrentLocation() != burning || !player.State.Physical.IsUnconscious() {
		t.Error("abandoned, the player is left where they fell for the fire to finish")
	}
}

// A willing carrier who has reached a fallen comrade is NOT swept out by the
// evacuation reflex — they stay to do the hauling.
func TestEvacuate_DoesNotFleeACommittedCarrier(t *testing.T) {
	burning := domain.NewLocationID()

	player := downedAt(burning, 10)
	player.Type = actor.ActorTypePlayer
	carrier := mortalAt(burning, 10) // unafraid → willing, standing over the downed
	carrier.Type = actor.ActorTypeStoryNPC
	byID := map[domain.ActorID]*actor.Actor{player.ID: player, carrier.ID: carrier}

	p := &TickProcessor{
		behaviorSystem: actor.NewBehaviorSystem(),
		hazards:        blaze(burning),
	}
	_, _, claimed := p.displaceFromUntenable(context.Background(), domain.NewGameTimeAt(5), domain.WorldID("w"), byID)

	if claimed[carrier.ID] {
		t.Error("the committed carrier must not be fled by evacuation — they stay to haul the downed out")
	}
}

package turn

import (
	"context"
	"fmt"

	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/actor"
	"github.com/dnd-llm/dnd-llm/internal/domain/check"
	"github.com/dnd-llm/dnd-llm/internal/domain/entity"
	"github.com/dnd-llm/dnd-llm/internal/domain/event"
	"github.com/dnd-llm/dnd-llm/internal/domain/skill"
)

// When an actor falls unconscious the world does not freeze around them — it
// decides their fate. A downed PLAYER cannot act (they only watch), so the tick
// resolves the drama deterministically. A rescue is NOT one atomic deed: it is a
// SEQUENCE of the rescuer's own actions, one per tick, each subject to the world
// reacting in between —
//
//	APPROACH : a willing soul elsewhere rushes INTO the danger toward the downed
//	           (and the blaze burns them there this tick, like anyone — real risk,
//	           not a token "dose");
//	CARRY OUT: once at the downed, they haul both to safety;
//	TEND     : in safety, they bring the downed round.
//
// The stage is derived from POSITIONS each tick (no stored intent): so a rescuer
// felled mid-approach simply leaves another to try, and a downed who dies before
// the carry is reached is lost. The catch — and the long shadow of the player's
// deeds — is WHO will come: an NPC who DREADS the player will not risk their life.
// Terrorise the town and no one runs into the fire for you.
//
// Each step where the world fights back is a graded CHECK (domain/check): the pool
// is the rescuer's capability against the task and the blaze (strength against
// deadweight, constitution against heat); the position is the fire's fury. So an
// approach can be DRIVEN BACK by a wall of flame, a carry can be a clean haul or a
// scorching one that costs the carrier, and a botch leaves both in the fire for the
// harm reflex to bite — the spectrum DF would give, not a binary in-or-out.

const (
	// rescuerFearCap: an NPC who fears the downed this much or more will not brave a
	// hazard to save them. Reputation decides whether the town comes for you.
	rescuerFearCap = 50

	// reviveHP is the sliver of health a tended or stabilised actor comes round
	// with — enough to stand and act again, never a free full heal.
	reviveHP = 1

	// carryBaseDice / braveBaseDice are the dice an UNHINDERED, average rescuer
	// brings to hauling a deadweight body / pushing through heat (before strength
	// or constitution adds, and before the blaze takes away). Two: a fair shot at
	// a clean room, a coin-flip at a kindling one, a likely botch in an inferno.
	carryBaseDice = 2
	braveBaseDice = 2
)

// resolveDowned advances the fate of every unconscious actor by ONE step this tick:
// a stage of the rescue where a hazard threatens, death saves where it is safe and
// no one tends them. Reflex — deterministic, no LLM. The events it returns are the
// FACTS of the drama (the narrator renders them; they are never surfaced raw).
func (p *TickProcessor) resolveDowned(ctx context.Context, gameTime domain.GameTime, worldID domain.WorldID, byID map[domain.ActorID]*actor.Actor) ([]*event.GameEvent, map[domain.ActorID]bool) {
	dirty := make(map[domain.ActorID]bool)
	var events []*event.GameEvent

	var endangered map[domain.LocationID]bool // lazy — most ticks no one is down
	var heat map[domain.LocationID]int        // lazy — only needed when a down is in danger
	for id, a := range byID {
		if a.State == nil || a.State.Physical == nil || !a.State.Physical.IsUnconscious() {
			continue
		}
		if endangered == nil {
			endangered = p.endangeredLocations(ctx, worldID, byID)
		}
		loc := a.State.GetCurrentLocation()

		if !endangered[loc] {
			// SAFE. A willing soul present TENDS them (first aid brings them round);
			// otherwise their own body decides through death saves.
			if ally := willingHelperAt(loc, a, byID); ally != nil {
				a.State.Physical.Heal(reviveHP)
				dirty[id], dirty[ally.ID] = true, true
				events = append(events, downFact(ally.ID, loc, worldID, gameTime,
					fmt.Sprintf("%s приводит тебя в чувство.", actorName(ally))))
			} else if ev, ok := rollDownedSave(a, gameTime, worldID); ok {
				events = append(events, ev)
				dirty[id] = true
			}
			continue
		}

		// IN DANGER. If a willing soul is already beside them, this tick they CARRY
		// the downed out (still senseless — the tend comes next, in safety). Else the
		// nearest willing soul elsewhere APPROACHES — rushing into the blaze. Both are
		// graded checks against the fire's fury, so the world can fight the rescue.
		if heat == nil {
			heat = p.fireHeatByLocation(ctx, gameTime, worldID, byID)
		}
		pos := firePosition(heat[loc])

		var evs []*event.GameEvent
		var moved []domain.ActorID
		if carrier := willingHelperAt(loc, a, byID); carrier != nil {
			evs, moved = p.resolveCarry(ctx, carrier, a, loc, pos, gameTime, worldID, byID)
		} else if approacher := willingApproacher(a, byID, endangered); approacher != nil {
			evs, moved = p.resolveApproach(approacher, a, loc, pos, gameTime, worldID)
		}
		// else: no one will come — the harm reflex (after this) finishes an
		// abandoned body. The town has turned from the player.
		events = append(events, evs...)
		for _, mid := range moved {
			dirty[mid] = true
		}
	}
	return events, dirty
}

// resolveCarry advances the CARRY stage: a soul beside the downed tries to haul
// both to safety. The attempt is a check — strength against the body's deadweight
// and the blaze's bite — under a position set by the fire's fury. On any success
// they reach safety (a Mixed haul scorches the carrier on the way out); a Botch
// leaves both in the fire this tick, where the harm reflex bites and the next tick
// tries again. Returns the FACT events and the actors whose position changed.
func (p *TickProcessor) resolveCarry(ctx context.Context, carrier, downed *actor.Actor, loc domain.LocationID, pos check.Position, gameTime domain.GameTime, worldID domain.WorldID, byID map[domain.ActorID]*actor.Actor) ([]*event.GameEvent, []domain.ActorID) {
	safe := p.pickSafeLocation(ctx, worldID, loc, byID)
	if safe == "" {
		return nil, nil // nowhere clear to take them yet — hold and try next tick
	}

	seed := check.Seed(gameTime.Tick, "carry", string(carrier.ID), string(downed.ID))
	pool := check.PoolFromContest(carryBaseDice+carrier.AbilityModifier(skill.AbilityStrength), int(pos))
	out := p.roll(seed, pool, pos)

	if !out.Tier.Accomplished() {
		// Botch: the weight and the heat win — neither moves. Both stay in the fire;
		// the harm reflex (after) burns them, and the next tick tries again.
		return []*event.GameEvent{downFact(carrier.ID, loc, worldID, gameTime,
			fmt.Sprintf("%s рвётся вытащить тебя, но жар и тяжесть тела отбрасывают назад — вы оба остаётесь в огне.", actorName(carrier)))}, nil
	}

	var events []*event.GameEvent
	text := fmt.Sprintf("%s выхватывает тебя из огня и тащит прочь в безопасность.", actorName(carrier))
	if out.Tier == check.Mixed {
		// Success at a cost: the carrier takes the blaze's bite hauling the body out,
		// the worse the fiercer the position (int(pos)) — one toll, one source.
		if ev := burnActor(carrier, int(pos)+1, worldID, gameTime); ev != nil {
			events = append(events, ev)
		}
		text = fmt.Sprintf("%s из последних сил выволакивает тебя наружу, сам обугливаясь в пламени.", actorName(carrier))
	}
	setContextLocation(carrier.State.StateContext, safe)
	setContextLocation(downed.State.StateContext, safe)
	events = append(events, downFact(carrier.ID, safe, worldID, gameTime, text))
	return events, []domain.ActorID{carrier.ID, downed.ID}
}

// resolveApproach advances the APPROACH stage: a willing soul elsewhere rushes IN
// toward the downed. The attempt is a check — constitution against the wall of heat.
// On success they reach the downed (a Mixed push sears them on the way), entering
// the fire so the harm reflex burns them this tick like anyone standing in it; a
// Botch is driven back at the threshold — they do not reach it, and try next tick.
func (p *TickProcessor) resolveApproach(approacher, downed *actor.Actor, loc domain.LocationID, pos check.Position, gameTime domain.GameTime, worldID domain.WorldID) ([]*event.GameEvent, []domain.ActorID) {
	seed := check.Seed(gameTime.Tick, "approach", string(approacher.ID), string(downed.ID))
	pool := check.PoolFromContest(braveBaseDice+approacher.AbilityModifier(skill.AbilityConstitution), int(pos))
	out := p.roll(seed, pool, pos)

	if !out.Tier.Accomplished() {
		// Botch: a wall of heat throws them back — they do not reach the downed this
		// tick (and so are not burned). The next tick tries again.
		return []*event.GameEvent{downFact(approacher.ID, approacher.State.GetCurrentLocation(), worldID, gameTime,
			fmt.Sprintf("%s рвётся к тебе, но стена огня отшвыривает назад.", actorName(approacher)))}, nil
	}

	setContextLocation(approacher.State.StateContext, loc) // into the danger
	var events []*event.GameEvent
	text := fmt.Sprintf("%s бросается к тебе сквозь огонь.", actorName(approacher))
	if out.Tier == check.Mixed {
		// Success at a cost: seared forcing the last few feet (on top of the harm
		// reflex that now burns them for standing in it), scaled by the position.
		if ev := burnActor(approacher, int(pos)+1, worldID, gameTime); ev != nil {
			events = append(events, ev)
		}
		text = fmt.Sprintf("%s прорывается к тебе сквозь пламя, опаляя себя.", actorName(approacher))
	}
	events = append(events, downFact(approacher.ID, loc, worldID, gameTime, text))
	return events, []domain.ActorID{approacher.ID}
}

// firePosition reads how exposed a rescuer is in a location into a check Position,
// off the SAME heat→harm conversion the harm reflex uses (fireDamagePerTick) — not
// a parallel re-quantisation of raw heat. A room whose blaze cannot actually bite
// (a lone smouldering item, 0 HP/tick) is Controlled; one that stings (~1 HP/tick,
// a kindling building) is Risky; a fire that kills a townsperson in a few ticks
// (≥3 HP/tick, a full blaze) is Desperate. The danger's TOLL — dice off the pool, a
// costly success's bite — is the position's ordinal (int(pos)), one source again.
func firePosition(heat int) check.Position {
	switch dmg := entity.FireDamagePerTick(heat); {
	case dmg >= 3:
		return check.Desperate
	case dmg >= 1:
		return check.Risky
	default:
		return check.Controlled
	}
}


// rollDownedSave settles an unconscious actor in SAFETY with a death save: stabilise
// (and come round on a sliver of HP) or slip away. Returns the committed FACT and
// whether anything changed.
func rollDownedSave(a *actor.Actor, gameTime domain.GameTime, worldID domain.WorldID) (*event.GameEvent, bool) {
	// A d20 ritual (nat-20/nat-1/strikes), but seeded from the tick and the actor so
	// the save replays identically rather than re-rolling on global rand.
	roll := check.D20(check.Seed(gameTime.Tick, "deathsave", string(a.ID)))
	if _, err := a.State.Physical.RollDeathSaveWithD20(0, roll); err != nil {
		return nil, false
	}
	loc := a.State.GetCurrentLocation()
	switch {
	case a.IsDead():
		return downFact(domain.ActorID(worldID), loc, worldID, gameTime, "Помощь не подоспела; дыхание прерывается, и темнота смыкается окончательно."), true
	case !a.State.Physical.IsUnconscious(): // stabilised or a natural 20 — came round
		if a.State.Physical.Health.Current == 0 {
			a.State.Physical.Heal(reviveHP)
		}
		return downFact(domain.ActorID(worldID), loc, worldID, gameTime, "Дыхание выравнивается само — ты приходишь в себя."), true
	default:
		return nil, true // still fighting; the next tick rolls again
	}
}

// willingToBrave reports whether `rescuer` would risk themselves for the downed:
// alive, conscious, not too terrified to move, and NOT dreading the downed
// (rescuerFearCap). Reputation gates the whole drama here.
func willingToBrave(rescuer, downed *actor.Actor) bool {
	if rescuer.State == nil || rescuer.State.Physical == nil {
		return false
	}
	if rescuer.IsDead() || rescuer.State.Physical.IsUnconscious() {
		return false
	}
	if rescuer.State.Emotional != nil && rescuer.State.Emotional.EscalationLevel == actor.EscalationTerrified {
		return false
	}
	if rescuer.State.Social != nil {
		if rel := rescuer.State.Social.GetRelationship(downed.ID); rel != nil && rel.Fear >= rescuerFearCap {
			return false
		}
	}
	return true
}

// affectionFor is how dearly `rescuer` holds the downed (0 if no relationship) —
// the tie-breaker for who steps up first.
func affectionFor(rescuer, downed *actor.Actor) int {
	if rescuer.State != nil && rescuer.State.Social != nil {
		if rel := rescuer.State.Social.GetRelationship(downed.ID); rel != nil {
			return rel.Affection
		}
	}
	return 0
}

// willingHelperAt is the willing soul ALREADY beside the downed (same location) who
// holds them dearest — the carrier this tick, or the one who tends in safety. nil
// when no one able-and-willing is here.
func willingHelperAt(loc domain.LocationID, downed *actor.Actor, byID map[domain.ActorID]*actor.Actor) *actor.Actor {
	var best *actor.Actor
	bestAffection := -1 << 30
	for id, a := range byID {
		if id == downed.ID || a.State == nil || a.State.GetCurrentLocation() != loc {
			continue
		}
		if !willingToBrave(a, downed) {
			continue
		}
		if aff := affectionFor(a, downed); aff > bestAffection {
			best, bestAffection = a, aff
		}
	}
	return best
}

// willingApproacher is the willing soul elsewhere (NOT already in a danger) who
// holds the downed dearest — the one who rushes IN. nil when the town will not come.
func willingApproacher(downed *actor.Actor, byID map[domain.ActorID]*actor.Actor, endangered map[domain.LocationID]bool) *actor.Actor {
	var best *actor.Actor
	bestAffection := -1 << 30
	for id, a := range byID {
		if id == downed.ID || a.State == nil || endangered[a.State.GetCurrentLocation()] {
			continue
		}
		if !willingToBrave(a, downed) {
			continue
		}
		if aff := affectionFor(a, downed); aff > bestAffection {
			best, bestAffection = a, aff
		}
	}
	return best
}

// isCommittedCarrier reports whether this NPC is standing beside a fallen soul they
// are willing to carry out — so the evacuation reflex must NOT flee them (they stay
// to do the hauling). The mirror of willingHelperAt, asked from the helper's side.
func isCommittedCarrier(npc *actor.Actor, byID map[domain.ActorID]*actor.Actor) bool {
	if npc.State == nil {
		return false
	}
	loc := npc.State.GetCurrentLocation()
	for id, a := range byID {
		if id == npc.ID || a.State == nil || a.State.Physical == nil {
			continue
		}
		if !a.State.Physical.IsUnconscious() || a.State.GetCurrentLocation() != loc {
			continue
		}
		if willingToBrave(npc, a) {
			return true
		}
	}
	return false
}

// pickSafeLocation finds somewhere clear of any standing hazard to haul a downed
// actor to — a location with room that is not the burning one they stand in.
func (p *TickProcessor) pickSafeLocation(ctx context.Context, worldID domain.WorldID, from domain.LocationID, byID map[domain.ActorID]*actor.Actor) domain.LocationID {
	to := p.pickDispersalTarget(ctx, worldID, from, byID)
	if to == from {
		return ""
	}
	return to
}

// downFact builds a down-resolution FACT event: a closed-template fact (what
// happened) the player-layer narrator renders into prose — never surfaced raw.
// actorID names WHO acted (the rescuer), so the narrator can be anchored on the
// name; for an actorless beat (a lone death save) pass the world id.
func downFact(actorID domain.ActorID, loc domain.LocationID, worldID domain.WorldID, gameTime domain.GameTime, text string) *event.GameEvent {
	return event.NewGameEvent(
		event.EventTypeRandomEventTriggered,
		actorID, loc, worldID, gameTime.Tick,
		event.RandomEventEventData{LocationID: loc.String(), Description: text, Category: "rescue"},
	)
}

// actorName is an actor's display name, safe when identity is unset (a fallback the
// player never normally sees — every seeded or joined actor is named).
func actorName(a *actor.Actor) string {
	if a.Identity != nil && a.Identity.Name != "" {
		return a.Identity.Name
	}
	return "кто-то"
}

// Package check is the single source of truth for resolving an UNCERTAIN action
// into a graded outcome. It is the deterministic core's answer to D&D's blunt
// pass/fail roll: instead of a binary, a check yields a TIER along a closed
// spectrum (botch → mixed → clean → triumph), and the situation's danger is a
// separate POSITION dial that tells the caller how SEVERE a setback's consequence
// is. This is the Blades-in-the-Dark / PbtA shape — "success at a cost", "failure
// as an event" — but the judging that those systems leave to a human GM is here a
// pure function of world state: the caller derives the dice pool from capability
// and the position from standing danger, the core rolls, and the LLM narrates the
// resulting fact. Nothing here knows about fire, rescue, stealth or any one
// situation — it resolves the CLASS of uncertain actions.
//
// The dice are a pool of d6, read by the single best die — so capability is the
// SIZE of the pool (more competence → more dice → a better expected tier), and the
// curve rewards skill over luck (the simulation virtue: a frail baker rarely
// out-hauls a warrior). The roll is seeded from the tick and the participants
// (Seed), so the same situation always rolls the same dice — reproducible from the
// event log, never re-rolled on replay.
package check

import (
	"math/rand"

	"github.com/dnd-llm/dnd-llm/internal/domain"
)

// Tier is the graded outcome of an uncertain action — the closed spectrum that
// replaces pass/fail. Ordered worst → best, so callers may compare with </>=.
type Tier int

const (
	// Botch: the action FAILED, and the failure carries a consequence (you are
	// driven back, you drop what you held, the situation worsens).
	Botch Tier = iota
	// Mixed: the action SUCCEEDED, but at a cost — you do the thing and something
	// goes wrong with it (you take harm, you are slowed, you draw notice).
	Mixed
	// Clean: full success, no strings.
	Clean
	// Triumph: success with a boon — you do it and gain something besides.
	Triumph
)

// Accomplished reports whether the action GOT DONE (Mixed counts — it succeeds, it
// merely costs). Use this to branch "did it happen"; switch on the Tier itself when
// the cost or the boon matters.
func (t Tier) Accomplished() bool { return t >= Mixed }

func (t Tier) String() string {
	switch t {
	case Botch:
		return "botch"
	case Mixed:
		return "mixed"
	case Clean:
		return "clean"
	case Triumph:
		return "triumph"
	default:
		return "unknown"
	}
}

// Position is how EXPOSED the actor is — the dial that sets how severe a setback's
// consequence is, derived by the caller from the world's standing danger (a calm
// room is Controlled; a roaring blaze is Desperate). It does NOT change the dice;
// it travels with the Outcome so the caller's consequence catalog can scale the
// fallout (a Botch in safety is a stumble; a Botch in an inferno can be the end).
//
// The constants are ordered by exposure, and the ORDINAL is the danger magnitude
// (Controlled=0 … Desperate=2): callers may use int(pos) as the size of the toll
// the danger exacts — dice off a pool, the bite of a costly success — rather than
// inventing a parallel ladder of magic numbers.
type Position int

const (
	Controlled Position = iota // safe footing — a slip costs little
	Risky                      // real danger — a slip hurts
	Desperate                  // mortal stakes — a slip can be fatal
)

func (p Position) String() string {
	switch p {
	case Controlled:
		return "controlled"
	case Risky:
		return "risky"
	case Desperate:
		return "desperate"
	default:
		return "unknown"
	}
}

// MaxPool caps the dice pool: even total mastery leaves a sliver of risk (with five
// dice the chance of an all-low botch is ~3%), so no action is ever a certainty.
const MaxPool = 5

// Outcome is the resolved check: the tier, the position it was rolled under (for
// the caller's consequence catalog), and the raw dice (for transparency, debug and
// journaling).
type Outcome struct {
	Tier     Tier
	Position Position
	Dice     []int
	Best     int
}

// PoolFromContest builds the dice pool for an action that pits CAPABILITY against
// DIFFICULTY: every point of edge is a die, every point of difficulty takes one
// away. Both are small non-negative ratings the caller composes from world facts
// (a strength bucket, a hazard's bite). Clamped to [0, MaxPool] — a zero pool is
// the desperate-and-incapable case Resolve handles by rolling two and taking the
// WORST.
func PoolFromContest(capability, difficulty int) int {
	return min(max(capability-difficulty, 0), MaxPool)
}

// Resolve rolls `pool` d6 and reads the single best die as the tier (one 6 → Clean,
// two or more 6s → Triumph, a 4-5 → Mixed, all ≤3 → Botch). A pool of zero — the
// actor is outmatched by the task — rolls TWO dice and takes the WORST, so the
// incapable can scrape a lucky success but never a triumph. Deterministic in the
// seed: same seed → same dice, so the event log replays a check without re-rolling.
func Resolve(seed int64, pool int, pos Position) Outcome {
	if pool > MaxPool {
		pool = MaxPool
	}
	r := rand.New(rand.NewSource(seed))

	n, takeLowest := pool, false
	if n < 1 {
		n, takeLowest = 2, true
	}

	dice := make([]int, n)
	best, sixes := 0, 0
	for i := 0; i < n; i++ {
		d := r.Intn(6) + 1
		dice[i] = d
		if d == 6 {
			sixes++
		}
		switch {
		case i == 0:
			best = d
		case takeLowest && d < best:
			best = d
		case !takeLowest && d > best:
			best = d
		}
	}

	return Outcome{Tier: tierFromBest(best, sixes, takeLowest), Position: pos, Dice: dice, Best: best}
}

// tierFromBest maps the deciding die to a tier. A two-six triumph is only reachable
// when keeping the highest (a pool of one or more) — the desperate take-lowest case
// tops out at a clean scrape.
func tierFromBest(best, sixes int, takeLowest bool) Tier {
	switch {
	case best == 6 && sixes >= 2 && !takeLowest:
		return Triumph
	case best == 6:
		return Clean
	case best >= 4:
		return Mixed
	default:
		return Botch
	}
}

// D20 rolls a single deterministic d20 (1..20) from a seed — for mechanics that are
// genuinely a d20 ritual (a death save's nat-20/nat-1/strikes), not the pool model,
// but still must replay identically. The seed comes from Seed, so the same tick and
// parties always roll the same die.
func D20(seed int64) int {
	return rand.New(rand.NewSource(seed)).Intn(20) + 1
}

// Seed derives the deterministic dice seed for a check from the tick and the
// participating identities (a kind tag, the actor, the target…). The same tick and
// the same parts always yield the same seed, so a check is reproducible from facts
// already in the log. Mirrors the contest seed used across the codebase: FNV-1a
// over the parts, XORed with the tick.
func Seed(tick domain.Tick, parts ...string) int64 {
	const (
		offset uint64 = 1469598103934665603
		prime  uint64 = 1099511628211
	)
	h := offset
	for _, p := range parts {
		for i := 0; i < len(p); i++ {
			h ^= uint64(p[i])
			h *= prime
		}
		h ^= 0x2c // a separator so "ab"+"c" and "a"+"bc" do not collide
		h *= prime
	}
	return int64(uint64(tick)) ^ int64(h)
}

