package weaver

import (
	"context"
	"fmt"
	"sync"

	appgoal "github.com/dnd-llm/dnd-llm/internal/application/goal"
	appllm "github.com/dnd-llm/dnd-llm/internal/application/llm"
	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/actor"
	"github.com/dnd-llm/dnd-llm/internal/domain/event"
	"github.com/dnd-llm/dnd-llm/internal/domain/front"
	goaldom "github.com/dnd-llm/dnd-llm/internal/domain/goal"
	weaverdom "github.com/dnd-llm/dnd-llm/internal/domain/weaver"
	infrallm "github.com/dnd-llm/dnd-llm/internal/infrastructure/llm"
	"go.uber.org/zap"
)

// EntityDraft is what the weaver asks the entity layer to create for an
// arrival: a stub with a story, never bare text.
type EntityDraft struct {
	Kind      string
	Name      string
	Gist      string
	Backstory string
}

// EntityPort is the weaver's hand into the "everything is an entity" layer.
type EntityPort interface {
	CreateStub(ctx context.Context, worldID domain.WorldID, draft EntityDraft, tick domain.Tick) (domain.EntityID, error)
}

// TruthPort tells the weaver whether a discovered truth is now COMMON knowledge —
// the read side of reveal_knowledge. A front whose premise a public truth undercuts
// (a scapegoat the real cause clears) defuses instead of dooming once IsWorldKnown
// reports the truth has spread. Nil → no front is knowledge-defusable (they run as
// before).
type TruthPort interface {
	IsWorldKnown(ctx context.Context, id domain.EntityID) (bool, error)
}

// LocationPort is the weaver's hand into world structure: it grows a new
// sublocation of the player's city. The built place is incarnation runtime —
// the reseed wipe regrows the world from the fixture, so the builder marks it
// for collection. Primitives keep the implementing package free of a weaver
// import. Nil → the build kind stays off the menu.
type LocationPort interface {
	BuildSublocation(ctx context.Context, worldID domain.WorldID, parentCity domain.LocationID, name, desc, locType string) (domain.LocationID, error)
}

// Scene is the player's situation at commit time, supplied by the turn
// pipeline (the weaver validates its prepared plan against it — the player
// may have walked away since preparation).
type Scene struct {
	WorldID      domain.WorldID
	WorldPremise string // the world's one-line premise (the river that flows at night)
	WorldEra     string // the world's time-and-setting canon (keeps interventions in period)
	Tick         domain.Tick
	PlayerID     domain.ActorID
	PlayerDeed   string // the player's expressed intent this turn (their raw message), the
	//                     authoritative signal of what they are DOING — an investigation that
	//                     leaves no event trace (an observe) is still here. Empty off the
	//                     player path (an autonomous tick). The front defuse classifies it.
	Location     domain.LocationID
	LocationName string
	LocationDesc string
	CityID       domain.LocationID // the parent city, for a build_location's parent
	CoLocated    []*actor.Actor
	Roster       []*actor.Actor // all living NPCs (npc_impulse picks from here)
	LoreFacts    []LoreFact     // lore entities of the scene, for subject grounding
	Places       []ScenePlace   // the world's known locations, for a rumor hook's place enum
	// Mentions are the entity ids the player's turn grounded — every person, place and
	// thing they referred to, already resolved. A front lead engages DETERMINISTICALLY
	// when its authored subject is among them (membership), before the fuzzy cue.
	Mentions []string
}

// mentioned reports whether the player grounded a reference to the given entity id
// this turn — the deterministic engagement signal.
func (s Scene) mentioned(id string) bool {
	if id == "" {
		return false
	}
	for _, m := range s.Mentions {
		if m == id {
			return true
		}
	}
	return false
}

// LoreFact is one entity the intervention may build on.
type LoreFact struct {
	ID   string
	Name string
	Gist string
}

// ScenePlace is one known location a rumor hook may bind its deed to — the
// payoff place may differ from where the rumor is told (a dock ritual heard in
// the tavern).
type ScenePlace struct {
	ID   domain.LocationID
	Name string
}

// Service runs the weaver's loop: AfterTurn prepares a plan in the background
// (the world stands still between turns — the GPU is free), Commit validates
// and lands it at the start of the next turn, before the world tick, so NPCs
// perceive it the same way they perceive the player's deeds.
type Service struct {
	events    event.EventStore
	actors    actor.ActorRepository
	goals     *appgoal.GoalTracker
	llm       infrallm.SchemaCompleter // authors ALL content; required (no Go-prose fallback)
	entities  EntityPort               // nil → the arrival kind stays off the menu
	locations LocationPort             // nil → the build-location kind stays off the menu
	truth     TruthPort                // nil → no front is knowledge-defusable
	cfg       weaverdom.Config
	enabled   bool
	logger    *zap.Logger

	// frontDefs are the AUTHORED story fronts (from the seed), hydrated each start
	// like goals; the weaver raises a dormant one into a live front and drives it.
	// doom applies a fired front's consequence as a REAL world change — without it
	// the weaver does not open fronts (no narration-only dooms).
	frontDefs map[string]*front.Def
	doom      Doom
	// cues judges whether a player's free-form deed engages a front's lead cue — the
	// fuzzy half of the defuse, shared with the rumor-hook payoff (one classifier, no
	// drift). nil → only the structured driver-dialogue signal defuses.
	cues *appllm.CueClassifier

	mu      sync.Mutex
	pending *weaverdom.Plan
	// preparing guards against overlapping Prepare goroutines.
	preparing bool
}

// Deps bundles the service's dependencies.
type Deps struct {
	Events    event.EventStore
	Actors    actor.ActorRepository
	Goals     *appgoal.GoalTracker
	LLM       infrallm.SchemaCompleter
	Entities  EntityPort
	Locations LocationPort
	Truth     TruthPort             // reports whether a discovered truth is now common knowledge (front defuse)
	Doom      Doom                  // applies a fired front's consequence as a real world change
	Cues      *appllm.CueClassifier // judges whether a deed engages a lead cue (defuse)
	Cfg       weaverdom.Config
	Enabled   bool
	Logger    *zap.Logger
}

// NewService builds the weaver service.
func NewService(deps Deps) *Service {
	logger := deps.Logger
	if logger == nil {
		logger = zap.NewNop()
	}
	cfg := deps.Cfg
	if cfg.WindowTicks <= 0 {
		cfg = weaverdom.DefaultConfig()
	}
	return &Service{
		events:    deps.Events,
		actors:    deps.Actors,
		goals:     deps.Goals,
		llm:       deps.LLM,
		entities:  deps.Entities,
		locations: deps.Locations,
		truth:     deps.Truth,
		doom:      deps.Doom,
		cues:      deps.Cues,
		frontDefs: map[string]*front.Def{},
		cfg:       cfg,
		enabled:   deps.Enabled,
		logger:    logger,
	}
}

// Enabled reports whether the weaver acts (it always observes).
func (s *Service) Enabled() bool { return s != nil && s.enabled }

// Reset drops the pending plan (used on world reseed).
func (s *Service) Reset() {
	if s == nil {
		return
	}
	s.mu.Lock()
	s.pending = nil
	s.mu.Unlock()
}

// AfterTurn schedules background preparation for the NEXT turn. Fire and
// forget: the turn's result is already on its way to the player.
func (s *Service) AfterTurn(baseCtx context.Context, scene Scene) {
	if !s.Enabled() {
		return
	}
	s.mu.Lock()
	if s.preparing {
		s.mu.Unlock()
		return
	}
	s.preparing = true
	s.mu.Unlock()

	go func() {
		defer func() {
			s.mu.Lock()
			s.preparing = false
			s.mu.Unlock()
		}()
		plan, err := s.prepare(baseCtx, scene)
		if err != nil {
			s.logger.Warn("weaver preparation failed", zap.Error(err))
			return
		}
		s.mu.Lock()
		s.pending = plan
		s.mu.Unlock()
		if plan != nil {
			s.logger.Info("weaver prepared an intervention",
				zap.String("kind", string(plan.Kind)),
				zap.String("issue", string(plan.Issue)),
				zap.String("target_emotion", plan.TargetEmotion),
			)
		}
	}()
}

// prepare reads the journey, decides whether to intervene and drafts the
// content. Returns nil when the story is healthy — the common case.
func (s *Service) prepare(ctx context.Context, scene Scene) (*weaverdom.Plan, error) {
	sig, err := ExtractSignals(ctx, s.events, scene.WorldID, scene.PlayerID, scene.Location, scene.Tick, s.cfg)
	if err != nil {
		return nil, err
	}
	// The world's size is the player's situation, not the event log — supply it
	// from the scene so confinement can read "the map is exhausted". Only when a
	// builder is wired (else there is no answer to give).
	if s.locations != nil {
		sig.Behavior.TotalLocations = len(scene.Places)
	}
	sig.Fronts = s.foldFronts(ctx, scene.WorldID)
	profile := weaverdom.CalculateProfile(sig.Samples)
	issues := weaverdom.DetectIssues(profile, sig.Behavior, sig.Arc, s.cfg)
	top := weaverdom.TopIssue(issues)

	// A live front IS the story this turn — it advances and surfaces at Commit, so
	// the weaver raises no competing intervention while one presses forward.
	if sig.activeFront() != nil {
		return nil, nil
	}
	if top == nil {
		return nil, nil
	}

	// A pacing issue with a matching DORMANT authored front → raise it (selected
	// deterministically; its content was authored in the seed), rather than generate
	// an ambient nudge. The front then drives itself toward a real doom.
	if def := s.selectFront(top.Type, sig, scene); def != nil {
		return &weaverdom.Plan{
			Issue:    top.Type,
			Phase:    s.phaseAfter(sig.Arc, top.Type),
			Kind:     weaverdom.KindOpenFront,
			FrontKey: def.Key,
		}, nil
	}

	plan := &weaverdom.Plan{
		Issue:         top.Type,
		TargetEmotion: weaverdom.ContrastEmotion(profile, top.Type),
		Phase:         s.phaseAfter(sig.Arc, top.Type),
	}
	s.chooseKind(plan, top.Severity, scene)
	if err := s.FillContent(ctx, plan, scene); err != nil {
		return nil, err
	}
	return plan, nil
}

// phaseAfter decides where the arc moves: answering a missing climax or a
// stuck phase advances it (when ripe); everything else keeps the phase.
func (s *Service) phaseAfter(arc weaverdom.ArcState, issue weaverdom.IssueType) weaverdom.Phase {
	switch issue {
	case weaverdom.IssueMissingClimax, weaverdom.IssuePhaseStuck:
		if arc.Ripe() {
			return weaverdom.NextPhase(arc.Phase)
		}
	}
	return arc.Phase
}

// stagnationEngageSeverity is the stagnation severity at which the weaver stops
// knocking softly (a rumour, a scene) and brings the story TO the stuck player — an
// NPC seeks them out, opening a thread. Stagnation severity climbs with the passive
// streak (0.5 + 0.1·(streak−min)), so this fires once a player has been adrift for
// several turns and ambient nudges have plainly failed to move them.
const stagnationEngageSeverity = 0.8

// chooseKind picks the intervention kind: organic first (existing NPCs and
// lore before new content), constrained by what the scene affords. Severity is the
// chosen issue's, so a persistent problem can escalate its remedy.
func (s *Service) chooseKind(plan *weaverdom.Plan, severity float64, scene Scene) {
	hasCompany := len(scene.CoLocated) > 0

	switch plan.Issue {
	case weaverdom.IssueStagnation:
		// A brief lull: the world knocks softly — a rumour if there is company, else
		// a happening nearby. But a DEEP, persistent stagnation is a plea for agency
		// that ambient nudges won't answer: escalate to active engagement — an NPC
		// who seeks the stuck player out and opens a thread to act on, the same
		// remedy a missing climax gets, gated on how long the player has been adrift.
		switch {
		case severity >= stagnationEngageSeverity:
			plan.Kind = weaverdom.KindNPCImpulse
		case hasCompany:
			plan.Kind = weaverdom.KindRumorDrop
		default:
			plan.Kind = weaverdom.KindSceneEvent
		}
	case weaverdom.IssueHighFatigue:
		// Relief: a gentle shift of the world's mood.
		plan.Kind = weaverdom.KindWorldShift
	case weaverdom.IssueMissingClimax:
		// A peak needs an ACTIVE push: an NPC seeks the player out — a direct
		// call-to-action, not an ambient happening. This holds whether or not
		// the player has company: pickImpulseTarget sends someone who is NOT
		// already here, so a present crowd doesn't suppress it. Only when no
		// free story NPC exists to send does FillContent degrade to a scene
		// event. (The old `hasCompany -> SceneEvent` gate left the climax
		// ambient in the common case — the player was rarely drawn into the
		// story directly; see finding #21.)
		plan.Kind = weaverdom.KindNPCImpulse
	case weaverdom.IssueConfinement:
		// The map is exhausted: grow the world. A structural intervention — it
		// neither needs company nor opens a thread.
		plan.Kind = weaverdom.KindBuildLocation
	default: // low variety, phase stuck
		if hasCompany {
			plan.Kind = weaverdom.KindRumorDrop
		} else {
			plan.Kind = weaverdom.KindSceneEvent
		}
	}

	plan.LocationID = scene.Location
	if hasCompany && (plan.Kind == weaverdom.KindRumorDrop) {
		plan.TargetActor = scene.CoLocated[0].ID
	}
	if plan.Kind == weaverdom.KindNPCImpulse {
		plan.TargetActor = "" // chosen at fill time from the wider roster
	}
}

// Commit validates the prepared plan against the live scene and lands it:
// events into the log (the world tick right after makes NPCs perceive them),
// finished prose back to the turn for the player's feed. Returns "" when
// there is nothing to weave.
func (s *Service) Commit(ctx context.Context, scene Scene) string {
	if !s.Enabled() {
		return ""
	}
	// The world presses any live front forward FIRST (its portent or doom this turn),
	// then the prepared intervention lands. Folding before execute means a front just
	// raised this turn is not double-advanced.
	frontWeave := s.advanceActiveFront(ctx, scene)

	s.mu.Lock()
	plan := s.pending
	s.pending = nil
	s.mu.Unlock()
	if plan == nil {
		return frontWeave
	}
	if !s.revalidate(plan, scene) {
		s.logger.Info("weaver plan dropped: scene changed", zap.String("kind", string(plan.Kind)))
		return frontWeave
	}
	text, err := s.execute(ctx, plan, scene)
	if err != nil {
		s.logger.Warn("weaver intervention failed", zap.Error(err))
		return frontWeave
	}
	return joinWeave(frontWeave, text)
}

// joinWeave combines a front beat and an intervention's prose into the turn's feed,
// dropping empties.
func joinWeave(a, b string) string {
	switch {
	case a == "":
		return b
	case b == "":
		return a
	default:
		return a + "\n\n" + b
	}
}

// revalidate checks the plan still fits: location-bound kinds retarget to the
// player's current place; NPC-bound kinds drop when the NPC is gone.
func (s *Service) revalidate(plan *weaverdom.Plan, scene Scene) bool {
	switch plan.Kind {
	case weaverdom.KindSceneEvent, weaverdom.KindWorldShift, weaverdom.KindArrival:
		plan.LocationID = scene.Location
		return true
	case weaverdom.KindBuildLocation:
		// Structural: a new place fits the world regardless of where the player
		// now stands, as long as the build actually produced a name.
		return plan.BuildName != ""
	case weaverdom.KindRumorDrop:
		for _, a := range scene.CoLocated {
			if a.ID == plan.TargetActor {
				return true
			}
		}
		// The intended teller left; any present NPC can carry a rumor.
		if len(scene.CoLocated) > 0 {
			plan.TargetActor = scene.CoLocated[0].ID
			return true
		}
		return false
	case weaverdom.KindNPCImpulse:
		return plan.TargetActor != ""
	case weaverdom.KindOpenFront:
		// Valid as long as the authored front still exists and has not been raised
		// since preparation (the content is the def's, resolved by key).
		s.mu.Lock()
		_, known := s.frontDefs[plan.FrontKey]
		s.mu.Unlock()
		return plan.FrontKey != "" && known
	default:
		return false
	}
}

// Status is the operator's view for /sim/weaver.
type Status struct {
	Enabled  bool               `json:"enabled"`
	Profile  weaverdom.Profile  `json:"profile"`
	Behavior weaverdom.Behavior `json:"behavior"`
	Arc      weaverdom.ArcState `json:"arc"`
	Issues   []weaverdom.Issue  `json:"issues"`
	Pending  *weaverdom.Plan    `json:"pending,omitempty"`
	History  []HistoryEntry     `json:"history"`
}

// HistoryEntry is one past intervention.
type HistoryEntry struct {
	Tick    int    `json:"tick"`
	Kind    string `json:"kind"`
	Issue   string `json:"issue"`
	Phase   string `json:"phase"`
	Summary string `json:"summary"`
}

// CurrentStatus computes the live weaver view.
func (s *Service) CurrentStatus(ctx context.Context, scene Scene) (*Status, error) {
	sig, err := ExtractSignals(ctx, s.events, scene.WorldID, scene.PlayerID, scene.Location, scene.Tick, s.cfg)
	if err != nil {
		return nil, err
	}
	profile := weaverdom.CalculateProfile(sig.Samples)

	st := &Status{
		Enabled:  s.Enabled(),
		Profile:  profile,
		Behavior: sig.Behavior,
		Arc:      sig.Arc,
		Issues:   weaverdom.DetectIssues(profile, sig.Behavior, sig.Arc, s.cfg),
		History:  s.history(ctx, scene.WorldID),
	}
	s.mu.Lock()
	st.Pending = s.pending
	s.mu.Unlock()
	return st, nil
}

// history lists the recent intervention markers.
func (s *Service) history(ctx context.Context, worldID domain.WorldID) []HistoryEntry {
	crit := event.StreamCriteria{}.ForWorld(worldID).WithEventTypes(event.EventTypeWeaverIntervened)
	events, err := s.events.GetEventStream(ctx, crit)
	if err != nil {
		return nil
	}
	out := make([]HistoryEntry, 0, len(events))
	for _, evt := range events {
		data, ok := evt.Data.(event.WeaverIntervenedEventData)
		if !ok {
			continue
		}
		out = append(out, HistoryEntry{
			Tick: int(evt.Tick), Kind: data.Kind, Issue: data.IssueType,
			Phase: data.Phase, Summary: data.Summary,
		})
	}
	if len(out) > 10 {
		out = out[len(out)-10:]
	}
	return out
}

// grantGoal installs an npc_impulse goal in the live tracker and journals it
// (the fold on start re-grants it after a restart).
func (s *Service) grantGoal(ctx context.Context, plan *weaverdom.Plan, scene Scene) error {
	if s.goals == nil {
		return fmt.Errorf("goal tracker not wired")
	}
	now := domain.NewGameTime()
	g := goaldom.NewGoal(plan.TargetActor, goaldom.GoalType("talk_to_actor"), plan.GoalText, goaldom.PriorityHigh, now)
	s.goals.Add(plan.TargetActor, g)

	if s.events != nil {
		evt := event.NewGameEvent(
			event.EventTypeGoalCreated,
			plan.TargetActor, scene.Location, scene.WorldID, scene.Tick,
			event.GoalCreatedEventData{
				ActorID:     plan.TargetActor,
				GoalID:      string(g.ID),
				GoalType:    string(g.Type),
				Description: plan.GoalText,
				Priority:    "high",
				Source:      "weaver",
			},
		)
		if err := s.events.Append(ctx, evt); err != nil {
			return err
		}
	}
	return nil
}

// RestoreGrantedGoals folds weaver-granted goals from the event log back into
// the live tracker — fixture goals re-hydrate from the seed, these from their
// events. Call on simulation start, after the fixture hydration.
func (s *Service) RestoreGrantedGoals(ctx context.Context, worldID domain.WorldID) {
	if s == nil || s.goals == nil {
		return
	}
	startTick := worldStartTick(ctx, s.events, worldID)
	crit := event.StreamCriteria{}.ForWorld(worldID).WithEventTypes(event.EventTypeGoalCreated)
	if startTick > 0 {
		crit.FromTick = &startTick
	}
	events, err := s.events.GetEventStream(ctx, crit)
	if err != nil {
		return
	}
	now := domain.NewGameTime()
	restored := 0
	for _, evt := range events {
		data, ok := evt.Data.(event.GoalCreatedEventData)
		if !ok || data.Source != "weaver" {
			continue
		}
		g := goaldom.NewGoal(data.ActorID, goaldom.GoalType(data.GoalType), data.Description, goaldom.PriorityHigh, now)
		g.ID = goaldom.GoalID(data.GoalID)
		s.goals.Add(data.ActorID, g)
		restored++
	}
	if restored > 0 {
		s.logger.Info("weaver-granted goals restored", zap.Int("goals", restored))
	}
}

// Package front models STORY FRONTS — the GM-craft answer (Apocalypse / Dungeon
// World) to a static world. A front is a developing SITUATION with its own
// momentum: a scheme, a threat, a brewing event that ADVANCES on a clock whether or
// not the player acts, and faster when they ignore it. As the clock fills, ordered
// PORTENTS foreshadow what is coming (telegraphing); LEADS are the redundant clues
// that point the player toward it (the three-clue rule). When the clock fills, the
// front's DOOM lands — a committed consequence in the world.
//
// The domain here is pure mechanics (a clock, its portents, its doom): the weaver
// decides WHEN to advance and HOW to surface a front, the LLM authors the prose of
// situation/portents/doom, and the consequence is committed by the core. Fronts
// persist by event-sourcing (FrontStarted/Advanced/Resolved folded from the log),
// like the weaver's arc — no state table, replay-safe.
package front

import "github.com/dnd-llm/dnd-llm/internal/domain"

// FrontID identifies a front across its lifetime of events.
type FrontID string

// ConsequenceType is the CLOSED catalogue of a front's possible dooms — each maps
// to a REAL world mechanic, so a doom is a true state change, not prose on a timer.
// The author (prep phase) picks one; the weaver applies it deterministically (play
// phase). Grow the catalogue by adding a row backed by an existing mechanic.
type ConsequenceType string

const (
	// ConsequenceRuinLocation destroys a location's load-bearing structure, so the
	// place becomes uninhabitable (the habitability mechanic) — a ford that closes,
	// a hall that falls. Target is a location.
	ConsequenceRuinLocation ConsequenceType = "ruin_location"
	// ConsequenceChangeEntity drives an entity through a catalogue effect (the
	// mutator) — a thing breaks, spoils, vanishes. Target is an entity, Detail an
	// effect key.
	ConsequenceChangeEntity ConsequenceType = "change_entity"
	// ConsequenceShiftDisposition turns an NPC's feeling toward the player (fear,
	// anger, affection). Target is an NPC, Detail the signed shift.
	ConsequenceShiftDisposition ConsequenceType = "shift_disposition"
	// ConsequenceShiftTownDisposition turns the WHOLE town's feeling toward one NPC —
	// suspicion or gratitude spreading (a scapegoat shunned, a hero embraced). The
	// NPC↔NPC counterpart, for outcomes that are between townsfolk, not toward the
	// player. Target is the NPC the town turns on, Detail the signed shift.
	ConsequenceShiftTownDisposition ConsequenceType = "shift_town_disposition"
	// ConsequenceRevealKnowledge makes an authored truth become KNOWN — the EPISTEMIC
	// outcome the catalogue lacked: not a thing changing or a feeling souring, but a
	// fact entering the world's knowledge. Target is a lore entity (the authored
	// answer, born unknown — in nobody's scope until revealed); applying it grants a
	// world-knows link, so the truth becomes common knowledge that surfaces in every
	// NPC's prompt and the player can learn by asking (the same mechanism as a
	// city_wide seed entity). This is what lets an investigate/gather_info goal — or a
	// player's lead — produce a REAL discovery (a knowledge edge in the graph) instead
	// of a counter ticking to nothing. Detail is unused.
	ConsequenceRevealKnowledge ConsequenceType = "reveal_knowledge"
	// ConsequenceRestoreLocation MENDS a location's ruined load-bearing structure, so
	// the place becomes habitable again (the habitability mechanic reopens it) — the
	// deliberate INVERSE of ruin_location, and the catalogue's first BOON: a real
	// positive change, not the mere absence of a doom. It is what a front's remedy
	// lands when the player acts on a discovered truth (clears the channel, and the
	// frozen-shut ford reopens). Target is a location. Idempotent / best-effort: a
	// location not yet ruined is left as-is (the remedy still resolves favourably).
	ConsequenceRestoreLocation ConsequenceType = "restore_location"
)

// Consequence is a front's doom: a real mechanical outcome plus its narration. The
// narration is PREP-authored prose (like a seed entity's gist) — the play-phase LLM
// may surface or recolour it, but the OUTCOME is the deterministic state change.
type Consequence struct {
	Type      ConsequenceType
	Target    string // resolved id (location/entity/npc) the doom lands on
	Detail    string // type-specific param (an effect key, a disposition delta)
	Narration string // authored prose of the doom landing
}

// Lead is one clue pointing the player at a front — a deed (cue) at a place. Authored
// redundantly (the three-clue rule) so a missed clue does not dead-end the thread;
// engaging one progresses or defuses the front.
type Lead struct {
	Location domain.LocationID
	Cue      string // the deed/theme that engages this lead
	// Subject is the authored ENTITY this lead is about (the river, the bell, the
	// docks). When the player's turn grounds a reference to it, the lead engages
	// DETERMINISTICALLY by membership — the grounding the parser already did is the
	// signal, no fuzzy cue call. Empty when the lead has no concrete subject to ground
	// (a pure act with no nameable object); those keep the cue classifier.
	Subject domain.EntityID
}

// Activation says WHEN a dormant authored front may be raised by the weaver: on
// player stagnation, on visiting a place, always-eligible, etc. The weaver still
// picks among the eligible by relevance — this only gates candidacy.
type Activation struct {
	Trigger string            // closed: "stagnation" | "visit" | "always" | ...
	Place   domain.LocationID // for "visit": where
}

// Def is an AUTHORED front — prep content from the seed (like an entity or an NPC),
// not runtime-generated. It carries the developing situation, its driver NPC, the
// foreshadowing portents, the redundant leads, the real-consequence doom and the
// activation gate. The weaver hydrates these dormant defs each start and raises one
// into a live Front when its activation fires and relevance selects it.
type Def struct {
	Key        string
	Situation  string
	Driver     domain.ActorID
	Portents   []string
	Leads      []Lead
	Doom       Consequence
	Activation Activation
	// DefusedBy is an optional lore entity whose PUBLIC knowledge dissolves this
	// front's premise — a discovered truth that undercuts the situation (the real
	// cause of a crisis clears the scapegoat the front would otherwise doom). When
	// that entity becomes common knowledge, the front resolves as defused instead of
	// firing its doom: the suspicion has no fuel once the town knows the truth. Empty
	// for fronts no discovery can defuse.
	DefusedBy domain.EntityID
	// Discovery is an optional lore entity the player UNCOVERS by handling this front —
	// the truth their own investigation brings to light. When the player defuses the
	// front (engaging its driver or a lead), this entity is revealed (made common
	// knowledge, the same reveal_knowledge a gather_info goal fires), so the player who
	// does the legwork learns what they found, not only the NPC who pursues it. Empty
	// for fronts that surface no authored truth. (DefusedBy is the mirror: a truth that
	// dissolves the front; Discovery is a truth the front's resolution brings to light.)
	Discovery domain.EntityID
	// Remedy is the authored RESOLVING ACTION a discovered truth unlocks: knowing the
	// cause is half the loop, ACTING on it is the other half. When the player does the
	// remedy action (their deed engages Remedy.Cue) AND its NeedsTruth is common
	// knowledge, the front resolves FAVOURABLY — averting the doom, the real healing
	// change — and surfaces the authored narration. Empty Cue → no remedy (the front
	// can only be defused or doomed). This closes «расследуй → узнай → почини».
	Remedy Remedy
}

// Remedy is a front's authored resolving action — the player's hands-on fix once they
// know the truth. Cue is the deed that triggers it (matched by the same classifier as a
// lead); NeedsTruth is the discovery that must already be common knowledge to attempt it;
// Narration is the authored prose of the world healing; Boon is the real positive change
// the fix lands (the symmetric mirror of the front's Doom — restore a ruined ford, revive
// a stilled thing). A zero-Type Boon means the remedy only averts the doom and narrates,
// landing no positive change of its own (the pre-boon behaviour).
type Remedy struct {
	Cue        string
	NeedsTruth domain.EntityID
	Narration  string
	Boon       Consequence
}

// ClockSize is how many segments a def's clock holds: one per portent, then the
// doom. A front with no authored portents still gets a two-beat clock (a warning,
// then the blow).
func (d Def) ClockSize() int {
	if n := len(d.Portents) + 1; n >= 2 {
		return n
	}
	return 2
}

// Clock measures how close a front's doom is: Filled of Size segments. A fresh
// front starts at 0; the doom is due at Size.
type Clock struct {
	Filled int
	Size   int
}

// Ripe reports whether the clock has filled — the doom is now due.
func (c Clock) Ripe() bool { return c.Size > 0 && c.Filled >= c.Size }

// Fraction is how full the clock is, 0..1 (0 for an unsized clock) — the pressure
// the weaver reads to pick a rung of the surfacing ladder (telegraph → pull → push).
func (c Clock) Fraction() float64 {
	if c.Size <= 0 {
		return 0
	}
	f := float64(c.Filled) / float64(c.Size)
	if f > 1 {
		return 1
	}
	return f
}

// Front is a LIVE instance of an authored Def: the def's content (situation,
// portents, leads, doom, driver) plus the runtime clock the weaver advances and the
// flags it folds from the event log. The Def is the single source of the front's
// story; the runtime only tracks how far it has pressed forward.
type Front struct {
	Def      *Def
	Clock    Clock
	Opened   domain.Tick // the tick it was raised (for engagement scanning)
	Resolved bool
}

// Key is the front's identity — its def's key (one live instance per def).
func (f *Front) Key() string {
	if f.Def == nil {
		return ""
	}
	return f.Def.Key
}

// Advance fills the clock by `step` segments (negative/zero is a no-op), clamped to
// the size, and reports whether it JUST ripened — the moment the doom becomes due.
// A resolved or already-ripe front does not advance.
func (f *Front) Advance(step int) (ripened bool) {
	if f.Resolved || step <= 0 || f.Clock.Ripe() {
		return false
	}
	f.Clock.Filled += step
	if f.Clock.Filled > f.Clock.Size {
		f.Clock.Filled = f.Clock.Size
	}
	return f.Clock.Ripe()
}

// Portent returns the authored foreshadowing beat for the CURRENT clock position —
// the telegraph for the segment most recently filled (Def.Portents[Filled-1]). Empty
// when the clock is fresh or no beat was authored for this step; the final fill
// speaks through the doom, not a portent.
func (f *Front) Portent() string {
	if f.Def == nil {
		return ""
	}
	i := f.Clock.Filled - 1
	if i < 0 || i >= len(f.Def.Portents) {
		return ""
	}
	return f.Def.Portents[i]
}

package weaver

import (
	"context"
	"fmt"
	"strings"

	appllm "github.com/dnd-llm/dnd-llm/internal/application/llm"
	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/actor"
	weaverdom "github.com/dnd-llm/dnd-llm/internal/domain/weaver"
	infrallm "github.com/dnd-llm/dnd-llm/internal/infrastructure/llm"
)

// Content generation: Go has already chosen the kind and the target emotion;
// the LLM only writes the words, framed by a grammar. The subject dynamic
// enum pins scene events and rumors to the existing lore — the model
// physically cannot drag a new name into the world through these kinds (only
// the arrival kind may, and it goes through the entity layer).

// subjectNone is the sentinel for "no lore entity fits".
const subjectNone = "ничто из перечисленного"

type sceneEventSchema struct {
	Description string `json:"description" maxlen:"180"`
	Subject     string `json:"subject"` // dynamic enum: scene lore + sentinel
}

type rumorSchema struct {
	Rumor   string `json:"rumor" maxlen:"160"`
	Subject string `json:"subject"` // dynamic enum: scene lore + sentinel
	// The optional actionable hook. When the rumor names a ritual — a deed at a
	// place that pays off — these pin it; place = placeNone keeps the rumor pure
	// flavour. The verdict engine matches a later player deed against cue + time.
	Place     string `json:"place"`               // dynamic enum: known places + sentinel
	Deed      string `json:"deed" maxlen:"80"`    // что нужно сделать в этом месте
	TimeOfDay string `json:"time_of_day"`         // closed enum: ночь | день | в любое время
	Payoff    string `json:"payoff" maxlen:"160"` // что произойдёт на самом деле, если сделать
}

// placeNone is the sentinel for "this rumor names no ritual place".
const placeNone = "нигде конкретно"

// Closed time-of-day enum for a hook: when the ritual must be performed.
const (
	hookTimeNight = "ночь"
	hookTimeDay   = "день"
	hookTimeAny   = "в любое время"
)

var hookTimeEnum = []string{hookTimeNight, hookTimeDay, hookTimeAny}

type npcImpulseSchema struct {
	GoalDescription string `json:"goal_description" maxlen:"120"` // инфинитив
	OpeningLine     string `json:"opening_line" maxlen:"140"`
}

type buildLocationSchema struct {
	Name         string `json:"name" maxlen:"40"`
	Description  string `json:"description" maxlen:"160"`
	LocationType string `json:"location_type"` // closed enum, see buildTypeEnum
}

// buildTypeEnum is the closed set of types a built city sublocation may take —
// plain corners of a town, no settings-breaking grandeur. Stored as the
// location's type string (lowercase, like the fixture's own).
var buildTypeEnum = []string{
	"residential", "shop", "workshop", "warehouse",
	"shrine", "ruins", "garden", "yard", "dock",
}

// FillContent writes the plan's content through the LLM under a grammar — the
// weaver's narration boundary. There is NO Go-authored fallback: all content is the
// model's job, grounded in the world's own lore (the deterministic-core contract —
// code never composes player-facing prose). The LLM is a HARD dependency of that
// boundary; its availability is a cross-cutting SYSTEM concern (health monitoring),
// not something the content path degrades around with hardcoded prose. A failed
// call (or an absent model) returns an error and the weaver simply skips this turn's
// intervention rather than fabricate — a persistent outage is surfaced by infra
// monitoring, not papered over here. Exported so llmbench probes the exact generator.
func (s *Service) FillContent(ctx context.Context, plan *weaverdom.Plan, scene Scene) error {
	if plan.Kind == weaverdom.KindNPCImpulse {
		s.pickImpulseTarget(plan, scene)
		if plan.TargetActor == "" {
			plan.Kind = weaverdom.KindSceneEvent // nobody to send
		}
	}
	if s.llm == nil {
		return fmt.Errorf("weaver requires an LLM to author content")
	}
	return s.generateContent(ctx, plan, scene)
}

// pickImpulseTarget chooses the NPC to send after the player: a story NPC who
// is NOT in the scene (someone arriving is the point).
func (s *Service) pickImpulseTarget(plan *weaverdom.Plan, scene Scene) {
	here := map[string]bool{}
	for _, a := range scene.CoLocated {
		here[string(a.ID)] = true
	}
	for _, a := range scene.Roster {
		if a.Type != actor.ActorTypeStoryNPC || here[string(a.ID)] || a.Identity == nil {
			continue
		}
		plan.TargetActor = a.ID
		return
	}
}

// generateContent runs the kind's grammar-framed call.
func (s *Service) generateContent(ctx context.Context, plan *weaverdom.Plan, scene Scene) error {
	lore, byName := loreEnum(scene)

	switch plan.Kind {
	case weaverdom.KindSceneEvent, weaverdom.KindWorldShift:
		prompt := s.scenePrompt(plan, scene, "Опиши короткое сенсорное происшествие в этом месте — звук, свет, движение. Без людей и их реплик, без обращения к игроку.")
		if plan.Kind == weaverdom.KindWorldShift {
			prompt = s.scenePrompt(plan, scene, "Опиши лёгкую перемену в погоде или настроении всего городка — то, что заметят все. Без людей и их реплик.")
		}
		schema, _, err := infrallm.Decode[sceneEventSchema](ctx, s.llm, infrallm.Request{
			SystemPrompt: weaverSystem,
			UserPrompt:   prompt,
			Temperature:  0.8,
			MaxTokens:    300,
			Language:     "ru",
			Options:      &infrallm.RequestOptions{DynamicEnums: map[string][]string{"subject": lore}},
		})
		if err != nil {
			return err
		}
		// The grammar's hard cap can chop mid-sentence; trim back to whole prose.
		plan.Description = appllm.SentenceTrim(schema.Description)
		plan.SubjectRef = byName[schema.Subject]
		return nil

	case weaverdom.KindRumorDrop:
		teller := actorName(scene.CoLocated, plan.TargetActor)
		places, byPlace := placeEnum(scene)
		prompt := s.rumorPrompt(plan, scene, teller)
		schema, _, err := infrallm.Decode[rumorSchema](ctx, s.llm, infrallm.Request{
			SystemPrompt: weaverSystem,
			UserPrompt:   prompt,
			Temperature:  0.85,
			MaxTokens:    320,
			Language:     "ru",
			Options: &infrallm.RequestOptions{DynamicEnums: map[string][]string{
				"subject":     lore,
				"place":       places,
				"time_of_day": hookTimeEnum,
			}},
		})
		if err != nil {
			return err
		}
		plan.Rumor = appllm.SentenceTrim(schema.Rumor)
		plan.SubjectRef = byName[schema.Subject]
		// A hook is laid only when the model named a real place AND a deed: the
		// rumor became a quest beat, not pure atmosphere.
		if placeID, ok := byPlace[schema.Place]; ok && strings.TrimSpace(schema.Deed) != "" {
			plan.HookLocation = placeID
			plan.HookCue = appllm.SentenceTrim(schema.Deed)
			plan.HookTime = normalizeHookTime(schema.TimeOfDay)
			plan.HookPayoff = appllm.SentenceTrim(schema.Payoff)
		}
		return nil

	case weaverdom.KindNPCImpulse:
		target := actorName(scene.Roster, plan.TargetActor)
		prompt := s.scenePrompt(plan, scene,
			fmt.Sprintf("Придумай, зачем %s срочно ищет путника. goal_description — цель СТРОГО в инфинитиве (например: «рассказать путнику о тревожном сне»). opening_line — первая реплика при встрече.", target))
		schema, _, err := infrallm.Decode[npcImpulseSchema](ctx, s.llm, infrallm.Request{
			SystemPrompt: weaverSystem,
			UserPrompt:   prompt,
			Temperature:  0.85,
			MaxTokens:    300,
			Language:     "ru",
		})
		if err != nil {
			return err
		}
		plan.GoalText = schema.GoalDescription
		plan.OpeningLine = appllm.SentenceTrim(schema.OpeningLine)
		return nil

	case weaverdom.KindBuildLocation:
		prompt := s.buildLocationPrompt(scene)
		schema, _, err := infrallm.Decode[buildLocationSchema](ctx, s.llm, infrallm.Request{
			SystemPrompt: weaverSystem,
			UserPrompt:   prompt,
			Temperature:  0.85,
			MaxTokens:    320,
			Language:     "ru",
			Options:      &infrallm.RequestOptions{DynamicEnums: map[string][]string{"location_type": buildTypeEnum}},
		})
		if err != nil {
			return err
		}
		plan.BuildName = strings.TrimSpace(schema.Name)
		plan.BuildDesc = appllm.SentenceTrim(schema.Description)
		plan.BuildType = schema.LocationType
		return nil
	}
	return fmt.Errorf("kind %q has no generator", plan.Kind)
}

const weaverSystem = `Ты — невидимый рассказчик живого мира: подбрасываешь миру маленькие события, которые направляют настроение истории. Пиши приземлённо и конкретно, в духе тихой речной мистики городка.

## ЗАПРЕЩЕНО
- слова «судьба», «как по заказу», «вдруг почему-то», любая мета-речь о сюжете;
- обращаться к игроку или называть его избранным;
- выдумывать новые имена людей и названия мест.`

// scenePrompt renders the shared situation block.
func (s *Service) scenePrompt(plan *weaverdom.Plan, scene Scene, task string) string {
	var b strings.Builder
	if scene.WorldPremise != "" {
		fmt.Fprintf(&b, "Мир: %s\n", scene.WorldPremise)
	}
	if scene.WorldEra != "" {
		fmt.Fprintf(&b, "Эпоха и уклад: %s\n", scene.WorldEra)
	}
	fmt.Fprintf(&b, "Место: %s — %s\n", scene.LocationName, scene.LocationDesc)
	if len(scene.LoreFacts) > 0 {
		b.WriteString("Известные вещи и предания:\n")
		for _, f := range scene.LoreFacts {
			fmt.Fprintf(&b, "- %s: %s\n", f.Name, f.Gist)
		}
	}
	fmt.Fprintf(&b, "\nЦель: вызвать у путника чувство «%s».\n\n%s\nЕсли происшествие связано с одной из перечисленных вещей — назови её в subject, иначе subject = «%s».\nВерни JSON.",
		plan.TargetEmotion, task, subjectNone)
	return b.String()
}

// rumorPrompt frames the rumor call: the shared situation, the rumor task, and
// the OPTIONAL actionable hook. The model decides whether the rumor names a
// ritual (a deed at one of the listed places that pays off) or stays pure
// flavour (place = placeNone) — the same sentinel discipline as subject.
func (s *Service) rumorPrompt(plan *weaverdom.Plan, scene Scene, teller string) string {
	var b strings.Builder
	if scene.WorldPremise != "" {
		fmt.Fprintf(&b, "Мир: %s\n", scene.WorldPremise)
	}
	if scene.WorldEra != "" {
		fmt.Fprintf(&b, "Эпоха и уклад: %s\n", scene.WorldEra)
	}
	fmt.Fprintf(&b, "Место: %s — %s\n", scene.LocationName, scene.LocationDesc)
	if len(scene.LoreFacts) > 0 {
		b.WriteString("Известные вещи и предания:\n")
		for _, f := range scene.LoreFacts {
			fmt.Fprintf(&b, "- %s: %s\n", f.Name, f.Gist)
		}
	}
	if len(scene.Places) > 0 {
		b.WriteString("Места мира:\n")
		for _, p := range scene.Places {
			fmt.Fprintf(&b, "- %s\n", p.Name)
		}
	}
	fmt.Fprintf(&b, "\nЦель: вызвать у путника чувство «%s».\n\n", plan.TargetEmotion)
	fmt.Fprintf(&b, "Сочини короткий слух, которым %s делится с путником: о городе, реке или одной из перечисленных вещей. Одна-две фразы живой речи, без обращения по имени.\n", teller)
	fmt.Fprintf(&b, "Если слух связан с одной из перечисленных вещей — назови её в subject, иначе subject = «%s».\n\n", subjectNone)
	b.WriteString("Иногда слух — это поверье с обрядом: «если в таком-то месте сделать то-то — случится такое-то». Если твой слух именно таков, заполни:\n")
	b.WriteString("- place — одно из перечисленных мест, где обряд сбудется;\n")
	b.WriteString("- deed — что именно там сделать (короткий инфинитив, например «бросить камешек в воду»);\n")
	b.WriteString("- time_of_day — когда (ночь / день / в любое время);\n")
	b.WriteString("- payoff — что произойдёт НА САМОМ ДЕЛЕ, когда путник это сделает (живое сенсорное описание, без мета-слов о сюжете).\n")
	fmt.Fprintf(&b, "Если слух — просто молва без обряда, поставь place = «%s» и оставь deed и payoff пустыми.\n\nВерни JSON.", placeNone)
	return b.String()
}

// buildLocationPrompt frames the world-growth call: the premise and era, the
// places that ALREADY exist (so the model invents a new corner, not a copy),
// and a request for one plausible sublocation of THIS town.
func (s *Service) buildLocationPrompt(scene Scene) string {
	var b strings.Builder
	if scene.WorldPremise != "" {
		fmt.Fprintf(&b, "Мир: %s\n", scene.WorldPremise)
	}
	if scene.WorldEra != "" {
		fmt.Fprintf(&b, "Эпоха и уклад: %s\n", scene.WorldEra)
	}
	fmt.Fprintf(&b, "Город: %s\n", scene.LocationName)
	if len(scene.Places) > 0 {
		b.WriteString("Уже существуют места:\n")
		for _, p := range scene.Places {
			fmt.Fprintf(&b, "- %s\n", p.Name)
		}
	}
	b.WriteString("\nПридумай ЕЩЁ ОДНО место этого городка, которого ещё нет в списке — обыденный уголок, куда путник мог бы забрести: тихий двор, заброшенный склад, маленькое святилище у воды. Не повторяй существующие.\n")
	b.WriteString("name — короткое название места (как у остальных). description — одна живая сенсорная фраза, чем оно встречает входящего. location_type — из предложенного перечня.\n\nВерни JSON.")
	return b.String()
}

// placeEnum builds the hook's place enum (known locations + sentinel) and the
// name→id lookup.
func placeEnum(scene Scene) ([]string, map[string]domain.LocationID) {
	enum := make([]string, 0, len(scene.Places)+1)
	byName := make(map[string]domain.LocationID, len(scene.Places))
	for _, p := range scene.Places {
		if p.Name == "" {
			continue
		}
		if _, dup := byName[p.Name]; dup {
			continue
		}
		byName[p.Name] = p.ID
		enum = append(enum, p.Name)
	}
	enum = append(enum, placeNone)
	return enum, byName
}

// normalizeHookTime maps the closed time-of-day enum to the stored hook value;
// "в любое время" (and anything unexpected) becomes empty — no time constraint.
func normalizeHookTime(s string) string {
	switch strings.TrimSpace(s) {
	case hookTimeNight:
		return hookTimeNight
	case hookTimeDay:
		return hookTimeDay
	}
	return ""
}

// loreEnum builds the subject enum and the name→id lookup.
func loreEnum(scene Scene) ([]string, map[string]string) {
	enum := make([]string, 0, len(scene.LoreFacts)+1)
	byName := make(map[string]string, len(scene.LoreFacts))
	for _, f := range scene.LoreFacts {
		if _, dup := byName[f.Name]; dup {
			continue
		}
		byName[f.Name] = f.ID
		enum = append(enum, f.Name)
	}
	enum = append(enum, subjectNone)
	return enum, byName
}

// actorName finds an actor's name in a list.
func actorName(actors []*actor.Actor, id domain.ActorID) string {
	for _, a := range actors {
		if a.ID == id && a.Identity != nil {
			return a.Identity.Name
		}
	}
	return "кто-то из горожан"
}

