// The committed fixture's authored GOAL OUTCOME resolves like a front doom: an NPC's aim,
// when achieved, lands a real consequence (Goran proving the guard's fault turns the town
// against the captain). The same buildConsequence resolution as a front doom.
func TestBuildGoals_Outcome(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join("..", "..", "seed", "cities", "zarechye.json"))
	if err != nil {
		t.Fatalf("read fixture: %v", err)
	}
	var cs CitySeed
	if err := json.Unmarshal(raw, &cs); err != nil {
		t.Fatalf("parse fixture: %v", err)
	}
	var goran NPCSeed
	for _, n := range cs.NPCs {
		if n.Key == "goran" {
			goran = n
		}
	}
	if goran.Key == "" {
		t.Fatal("goran not found in fixture")
	}
	goals := buildGoals(cs.SeedKey, goran.Key, ActorIDFor(cs.SeedKey, goran.Key), goran.Goals, domain.NewGameTime())
	if len(goals) == 0 || goals[0].Outcome == nil {
		t.Fatal("Goran's goal must carry a resolved authored outcome")
	}
	o := goals[0].Outcome
	if o.Type != front.ConsequenceShiftTownDisposition {
		t.Errorf("outcome type = %q, want shift_town_disposition", o.Type)
	}
	if o.Target != ActorIDFor(cs.SeedKey, "daroy").String() {
		t.Error("outcome target must resolve to Daroy's deterministic id")
	}
	if o.Narration == "" {
		t.Error("the outcome carries authored narration")
	}
}

// Mirra's gather_info goal carries a resolved reveal_knowledge outcome: achieving it
// makes the authored truth about the river COMMON KNOWLEDGE — the epistemic payoff that
// turns an investigate goal from a counter into a real discovery. The target resolves to
