// TestFixtureBuildsValidEntities loads the committed fixture and asserts every
// authored world entity maps to a valid aggregate with resolvable references —
// the same checks loadEntities enforces at runtime, but caught at test time.
func TestFixtureBuildsValidEntities(t *testing.T) {
	path := filepath.Join("..", "..", "seed", "cities", "zarechye.json")
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read fixture: %v", err)
	}
	var seed CitySeed
	if err := json.Unmarshal(raw, &seed); err != nil {
		t.Fatalf("parse fixture: %v", err)
	}
	if len(seed.Entities) == 0 {
		t.Fatal("fixture has no entities — the knowledge layer needs an authored baseline")
	}

	worldID := WorldIDFor(seed.SeedKey)
	npcKeys := make(map[string]bool, len(seed.NPCs))
	for _, n := range seed.NPCs {
		npcKeys[n.Key] = true
	}
	locKeys := make(map[string]bool, len(seed.City.Sublocations))
	for _, sub := range seed.City.Sublocations {
		locKeys[sub.Key] = true
	}

	// A reveal_knowledge consequence (a goal outcome or a front doom) makes its target
	// entity REACHABLE through the discovery mechanism — an authored truth born unknown
	// (no owner/location/knower) is legitimately sealed until revealed, not dead content.
	revealTargets := make(map[string]bool)
	collectReveal := func(d *DoomSeed) {
		if d != nil && d.Consequence == string(front.ConsequenceRevealKnowledge) {
			revealTargets[d.TargetKey] = true
		}
	}
	for _, n := range seed.NPCs {
		for _, g := range n.Goals {
			collectReveal(g.Outcome)
		}
	}
	for i := range seed.Fronts {
		collectReveal(&seed.Fronts[i].Doom)
	}

	entityKeys := make(map[string]bool, len(seed.Entities))
	for _, es := range seed.Entities {
		if entityKeys[es.Key] {
			t.Errorf("duplicate entity key %q", es.Key)
		}
		entityKeys[es.Key] = true
	}

	for _, es := range seed.Entities {
		e, err := buildEntity(seed.SeedKey, es, worldID)
		if err != nil {
			t.Errorf("entity %q builds invalid aggregate: %v", es.Key, err)
			continue
		}
		if got := len([]rune(e.Gist)); got > 160 {
			t.Errorf("entity %q gist is %d runes, budget is 160", es.Key, got)
		}
		if es.OwnerKey != "" && !npcKeys[es.OwnerKey] {
			t.Errorf("entity %q references unknown owner %q", es.Key, es.OwnerKey)
		}
		if es.LocationKey != "" && !locKeys[es.LocationKey] {
			t.Errorf("entity %q references unknown location %q", es.Key, es.LocationKey)
		}
		for _, k := range es.KnownByKeys {
			if !npcKeys[k] {
				t.Errorf("entity %q references unknown npc %q in known_by", es.Key, k)
			}
		}
		for _, m := range es.Mentions {
			if !entityKeys[m] {
				t.Errorf("entity %q mentions unknown entity %q", es.Key, m)
			}
		}
		if es.OwnerKey == "" && es.LocationKey == "" && len(es.KnownByKeys) == 0 && !es.CityWide && !revealTargets[es.Key] {
			t.Errorf("entity %q is unreachable: no owner, location, knowers, city-wide flag, or reveal_knowledge target", es.Key)
		}
	}

	if EntityIDFor(seed.SeedKey, "night_bread") != EntityIDFor(seed.SeedKey, "night_bread") {
		t.Error("EntityIDFor is not deterministic")
	}
	if EntityIDFor(seed.SeedKey, "night_bread") == EntityIDFor(seed.SeedKey, "night_flour") {
		t.Error("different entity keys produced the same EntityID")
	}
}

