// CueCovered reports whether a player's deed words cover an authored CUE phrase —
// enough of the cue's content words stem-match a deed word. Two overlapping words
// are required for a normal cue (so an unrelated deed in the right place cannot trip
// it); a one-word cue needs its single word. Shared by the rumor-hook verdict and
// the story-front lead-engagement check so both read a deed against a cue the same.
func CueCovered(deedWords []string, cue string) bool {
	cueWords := ContentWords(cue)
	if len(cueWords) == 0 {
		return false
	}
	matches := 0
	for _, cw := range cueWords {
		for _, dw := range deedWords {
			if WordsMatch(cw, dw) {
				matches++
				break
			}
		}
	}
	threshold := 2
	if len(cueWords) < 2 {
		threshold = 1
	}
	return matches >= threshold
}

