// Package rutext is the word-level matching toolkit for Russian text the frame
// code leans on. Matching runs on Snowball stems, not raw prefixes: «ночная»
// and «ночной» share a stem (a true match), while «стол» and «столица» no
// longer collide (a false match the old prefix heuristic let through). Two
// strictnesses live here — stem equality for topic focus and grounding, where
// precision matters, and a looser stem-or-prefix collision for scribe dedup,
// where recall matters more (a distorted name like «Росатомный» must still
// catch the canon «Росатый»).
package rutext

import (
	"strings"
	"unicode"
	"unicode/utf8"
)

// ContentWords lowers the string and keeps words of ≥3 runes, stripped of
// surrounding punctuation — the same bar the search index uses for aliases.
func ContentWords(s string) []string {
	var out []string
	for w := range strings.FieldsSeq(strings.ToLower(s)) {
		w = strings.TrimFunc(w, func(r rune) bool {
			return !unicode.IsLetter(r) && !unicode.IsNumber(r)
		})
		if utf8.RuneCountInString(w) >= 3 {
			out = append(out, w)
		}
	}
	return out
}

// WordsMatch reports whether two words are the same word in different forms —
// stem equality. This is the strict tier: «ночная»≡«ночной», but «стол»≢
// «столица». A handful of base forms the stemmer over-trims («прилив»→«прил»
// vs «прилива»→«прилив») slip through as non-matches and degrade to the search
// cascade, which is the intended fallback.
func WordsMatch(a, b string) bool {
	return Stem(a) == Stem(b)
}

// WordsCollide is the looser tier for deduplication: a stem match, or — for
// names the stemmer splits apart — a shared prefix of ≥max(3, min(len)-2)
// runes. Recall over precision: «Росатый»/«Росатомный» must collide so a
// distorted capture doesn't spawn a duplicate entity.
func WordsCollide(a, b string) bool {
	if WordsMatch(a, b) {
		return true
	}
	return prefixMatch(a, b)
}

// prefixMatch is the legacy heuristic, kept only as the recall net inside
// WordsCollide: a shared leading run long enough to be the stem.
func prefixMatch(a, b string) bool {
	ra, rb := []rune(a), []rune(b)
	short := min(len(ra), len(rb))
	need := max(short-2, 3)
	if short < need {
		return false
	}
	for i := range need {
		if ra[i] != rb[i] {
			return false
		}
	}
	return true
}

// allWordsBy reports whether every needle word matches some haystack word
// under the given word matcher.
func allWordsBy(needleWords, haystackWords []string, match func(a, b string) bool) bool {
	for _, nw := range needleWords {
		matched := false
		for _, hw := range haystackWords {
			if match(nw, hw) {
				matched = true
				break
			}
		}
		if !matched {
			return false
		}
	}
	return true
}

// AllWordsIn reports whether every word of needle has a stem-matching word in
// the haystack word list.
func AllWordsIn(needleWords, haystackWords []string) bool {
	return allWordsBy(needleWords, haystackWords, WordsMatch)
}

// AnyWordIn reports whether at least one word of needle has a stem-matching
// word in the haystack word list.
func AnyWordIn(needleWords, haystackWords []string) bool {
	for _, nw := range needleWords {
		for _, hw := range haystackWords {
			if WordsMatch(nw, hw) {
				return true
			}
		}
	}
	return false
}

// NamesCollide reports whether two names are word-level duplicates: every
// content word of one collides (the looser WordsCollide tier) with a word of
// the other. «Поток Тихводь» collides with «Тихводь»; «Росатомный Прилив»
// with «Росатый Прилив» — the deduplication bar for model-introduced names,
// where recall beats precision.
func NamesCollide(a, b string) bool {
	aw, bw := ContentWords(a), ContentWords(b)
	if len(aw) == 0 || len(bw) == 0 {
		return false
	}
	return allWordsBy(aw, bw, WordsCollide) || allWordsBy(bw, aw, WordsCollide)
}

// collectives are the Russian collective numerals for people (двое..десятеро),
// the natural way to count a small group: «трое свидетелей», not «три».
var collectives = map[int]string{
	2: "двое", 3: "трое", 4: "четверо", 5: "пятеро",
	6: "шестеро", 7: "семеро", 8: "восьмеро", 9: "девятеро", 10: "десятеро",
}

// CollectiveNumeral returns the Russian collective numeral for a small count of
// people (n in [2,10]), or "" when n falls outside that range and a bare digit
// should be used instead. Lets the code state an exact count of people in the
// closed vocabulary, so prose never has to invent one («все трое» over four).
func CollectiveNumeral(n int) string {
	return collectives[n]
}

package player

import (
	"context"
	"sort"
	"strings"

	"github.com/dnd-llm/dnd-llm/internal/application/conversation"
	appllm "github.com/dnd-llm/dnd-llm/internal/application/llm"
	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/event"
)

// Rumor hooks are latent NARRATIVE affordances the weaver plants: a deed at a
// place that pays off. This is the story mirror of the prop fund — instead of a
// latent thing that crystallizes on touch, a latent consequence that fires when
// the player performs the rumored ritual. The fold reconstructs the incarnation's
// live hooks from the event log (planted by RumorHeard, retired by HookFulfilled),
// then the verdict engine matches the player's deed against them deterministically.

// hookWindow bounds how far back the hook fold scans. A planted rumor must stay
// live long enough for the player to follow it across several visits, so this is
// far wider than the conversation fold — but still a bounded, cheap read.
const hookWindow domain.Tick = 6000

// Closed time-of-day buckets a hook condition is stated in (the stored values
// normalizeHookTime writes). "" means no constraint.
const (
	hookNight = "ночь"
	hookDay   = "день"
)

// pendingHook is a live hook and the id of the rumor that planted it.
type pendingHook struct {
	hook    *event.RumorHook
	rumorID string
}

// matchHook returns the pending rumor hook the player's deed fulfills at their current
// location, or nil. Location and time-of-day gate DETERMINISTICALLY; whether the
// free-form deed MEANS the hook's rumored cue is unstructured perception, so the
// grammar-bound cue classifier judges it — the same shared classifier that defuses a
// story-front lead, replacing the old stem-overlap crutch (which fired on coincidental
// words). No classifier wired → no fuzzy payoff.
func (s *TurnService) matchHook(ctx context.Context, tc *turnContext, deed extractedDeed) *pendingHook {
	if s.events == nil {
		return nil
	}
	phrase := deedPhrase(deed)
	if phrase == "" {
		return nil
	}
	hooks := foldPendingHooks(ctx, s.events, tc.worldID, tc.tick)
	candidates := candidateHooks(hooks, tc.player.GetCurrentLocation(), timeBucket(int(tc.gameTime.Hour())))
	for _, ph := range candidates {
		if s.cues.DeedEngages(ctx, phrase, []string{ph.hook.Cue}) {
			return ph
		}
	}
	return nil
}

// candidateHooks returns the pending hooks whose place and time-of-day condition hold
// for the player here and now — the deterministic gate before the fuzzy cue judgement.
// Pure: the verdict engine's gating logic, testable without an event store or model.
func candidateHooks(hooks []*pendingHook, here domain.LocationID, now string) []*pendingHook {
	var out []*pendingHook
	for _, ph := range hooks {
		if domain.LocationID(ph.hook.LocationID) != here {
			continue
		}
		if !timeMatches(ph.hook.TimeOfDay, now) {
			continue
		}
		out = append(out, ph)
	}
	return out
}

// foldPendingHooks folds the incarnation's rumor hooks not yet fulfilled.
// Wall-clock order with a reseed reset, exactly like the conversation fold: a
// reseed marker buries the previous incarnation's hooks (its tick numbers repeat
// in the new one). Takes the minimal stream reader so it tests without a full
// event store.
func foldPendingHooks(ctx context.Context, store conversation.StreamReader, worldID domain.WorldID, tick domain.Tick) []*pendingHook {
	crit := event.StreamCriteria{}.ForWorld(worldID).WithEventTypes(
		event.EventTypeRumorHeard,
		event.EventTypeHookFulfilled,
		event.EventTypeWorldReseeded,
	)
	if tick > hookWindow {
		from := tick - hookWindow
		crit.FromTick = &from
	}
	events, err := store.GetEventStream(ctx, crit)
	if err != nil || len(events) == 0 {
		return nil
	}
	sort.SliceStable(events, func(i, j int) bool { return events[i].CreatedAt.Before(events[j].CreatedAt) })

	live := map[string]*pendingHook{}
	for _, evt := range events {
		switch evt.Type {
		case event.EventTypeWorldReseeded:
			live = map[string]*pendingHook{}
		case event.EventTypeRumorHeard:
			d, ok := evt.Data.(event.RumorHeardEventData)
			if !ok || d.Hook == nil || d.Hook.Cue == "" {
				continue
			}
			id := evt.ID.String()
			live[id] = &pendingHook{hook: d.Hook, rumorID: id}
		case event.EventTypeHookFulfilled:
			d, ok := evt.Data.(event.HookFulfilledEventData)
			if !ok {
				continue
			}
			delete(live, d.RumorID)
		}
	}
	out := make([]*pendingHook, 0, len(live))
	for _, ph := range live {
		out = append(out, ph)
	}
	return out
}

// deedPhrase reassembles what the player said into one phrase — the deed, its target and
// its instrument — for the cue classifier to weigh against the rumored ritual. The raw
// words the player chose, not stems: the model reads intent, not token overlap.
func deedPhrase(deed extractedDeed) string {
	parts := make([]string, 0, 3)
	for _, p := range []string{deed.Deed, deed.Target, deed.Instrument} {
		if strings.TrimSpace(p) != "" {
			parts = append(parts, p)
		}
	}
	return strings.Join(parts, " ")
}

// timeBucket folds the hour into the hook's night/day buckets, reusing the
// world's own time-of-day boundaries so the condition reads the clock the same
// way the narrator does. Dusk counts as night — a ritual "ночью" is welcome at
// вечер too.
func timeBucket(hour int) string {
	switch appllm.TimeOfDayRu(hour) {
	case "вечер", "ночь":
		return hookNight
	default:
		return hookDay
	}
}

// timeMatches reports whether the current bucket satisfies the hook's condition;
// an empty condition holds at any time.
func timeMatches(want, now string) bool {
	return want == "" || want == now
}

