		t.Fatal("mirra not found in fixture")
	}
	goals := buildGoals(cs.SeedKey, mirra.Key, ActorIDFor(cs.SeedKey, mirra.Key), mirra.Goals, domain.NewGameTime())
	var gather *front.Consequence
	for _, g := range goals {
		if g.Type == "gather_info" {
			gather = g.Outcome
		}
	}
	if gather == nil {
		t.Fatal("Mirra's gather_info goal must carry a resolved reveal_knowledge outcome")
	}
	if gather.Type != front.ConsequenceRevealKnowledge {
		t.Errorf("outcome type = %q, want reveal_knowledge", gather.Type)
	}
	if gather.Target != EntityIDFor(cs.SeedKey, "river_true_cause").String() {
		t.Error("outcome target must resolve to the river_true_cause entity id")
	}
	if gather.Narration == "" {
		t.Error("the outcome carries authored narration")
	}
}

// The committed fixture's authored fronts resolve into domain defs with every seed
// key (driver, leads, doom target) mapped to its deterministic id — the prep-phase
// content the weaver hydrates at play time.
func TestBuildFronts_Fixture(t *testing.T) {
	path := filepath.Join("..", "..", "seed", "cities", "zarechye.json")
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read fixture: %v", err)
	}
	var cs CitySeed
	if err := json.Unmarshal(raw, &cs); err != nil {
		t.Fatalf("parse fixture: %v", err)
	}

	defs, err := BuildFronts(cs)
	if err != nil {
		t.Fatalf("BuildFronts: %v", err)
	}
	if len(defs) == 0 {
		t.Fatal("the fixture authors no fronts")
	}

	var river *front.Def
	for _, d := range defs {
		if d.Key == "river_falling_silent" {
			river = d
		}
	}
	if river == nil {
		t.Fatal("river_falling_silent front not found")
	}

	if river.Driver != ActorIDFor(cs.SeedKey, "mirra") {
		t.Error("driver must resolve to Mirra's deterministic id")
	}
	if len(river.Portents) != 3 {
		t.Errorf("expected 3 portents, got %d", len(river.Portents))
	}
	if len(river.Leads) != 3 {
		t.Errorf("expected 3 leads (three-clue), got %d", len(river.Leads))
	}
	if river.Doom.Type != front.ConsequenceRuinLocation {
		t.Errorf("doom type = %q, want ruin_location", river.Doom.Type)
	}
	if river.Doom.Target != LocationIDFor(cs.SeedKey, "docks").String() {
		t.Error("doom target must resolve to the docks location id")
	}
	// The remedy lands a real BOON — the symmetric inverse of the doom: restoring the
	// very docks the doom froze shut (clear the channel → the ford reopens).
	if river.Remedy.Boon.Type != front.ConsequenceRestoreLocation {
		t.Errorf("remedy boon type = %q, want restore_location", river.Remedy.Boon.Type)
	}
	if river.Remedy.Boon.Target != LocationIDFor(cs.SeedKey, "docks").String() {
		t.Error("remedy boon must restore the same docks the doom ruined")
	}
	// Handling the river front reveals the authored cause: the player who investigates
	// learns what they found, not only the NPC who pursues it.
	if river.Discovery != EntityIDFor(cs.SeedKey, "river_true_cause") {
		t.Error("river front Discovery must resolve to the river_true_cause entity id")
	}
	if river.Doom.Narration == "" {
		t.Error("the doom carries authored narration")
	}
	if river.Activation.Trigger != "stagnation" {
		t.Errorf("activation = %q, want stagnation", river.Activation.Trigger)
	}
	if river.ClockSize() != 4 {
		t.Errorf("clock size = %d, want 4 (3 portents + doom)", river.ClockSize())
	}

	// A SECOND authored front with a different consequence proves the system is not
	// hard-wired to one: the change_entity doom resolves its entity target + effect.
	var bell *front.Def
	for _, d := range defs {
		if d.Key == "bell_falling_silent" {
			bell = d
		}
	}
	if bell == nil {
		t.Fatal("bell_falling_silent front not found")
	}
	if bell.Doom.Type != front.ConsequenceChangeEntity {
		t.Errorf("bell doom type = %q, want change_entity", bell.Doom.Type)
	}
	if bell.Doom.Target != EntityIDFor(cs.SeedKey, "old_bell").String() {
		t.Error("bell doom target must resolve to the old_bell entity id")
	}
	if bell.Doom.Detail != "расколоть" {
		t.Errorf("bell doom detail (effect key) = %q, want расколоть", bell.Doom.Detail)
	}
	// The bell front carries a REMEDY the discovered truth unlocks: ringing the bell
	// resolves it favourably once river_toll is common knowledge — закрытие петли
	// «расследуй → узнай → почини».
	if bell.Remedy.Cue == "" {
		t.Error("bell front must author a remedy cue (ring the bell)")
	}
	if bell.Remedy.NeedsTruth != EntityIDFor(cs.SeedKey, "river_toll") {
		t.Error("bell remedy must require the river_toll truth to be known")
	}
	if bell.Remedy.Narration == "" {
		t.Error("the remedy carries authored healing narration")
	}
}

// The scapegoat front (suspicion on the outsider) resolves its authored DefusedBy to the
// river_true_cause entity id: once that truth is common knowledge, the front defuses
// instead of dooming an innocent merchant — a discovery with a real, lasting consequence.
func TestBuildFronts_DefusedBy(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join("..", "..", "seed", "cities", "zarechye.json"))
	if err != nil {
		t.Fatalf("read fixture: %v", err)
	}
	var cs CitySeed
	if err := json.Unmarshal(raw, &cs); err != nil {
		t.Fatalf("parse fixture: %v", err)
	}
	defs, err := BuildFronts(cs)
	if err != nil {
		t.Fatalf("BuildFronts: %v", err)
	}
	var scapegoat *front.Def
	for _, d := range defs {
		if d.Key == "suspicion_falls_on_outsider" {
			scapegoat = d
		}
	}
	if scapegoat == nil {
		t.Fatal("suspicion_falls_on_outsider front not found")
	}
	if scapegoat.DefusedBy != EntityIDFor(cs.SeedKey, "river_true_cause") {
		t.Errorf("DefusedBy = %q, want river_true_cause entity id", scapegoat.DefusedBy)
	}
}

// An unknown doom consequence is an authoring mistake that fails loudly.
func TestBuildFronts_RejectsUnknownConsequence(t *testing.T) {
	cs := CitySeed{
		SeedKey: "t",
		Fronts: []FrontSeed{{
			Key:       "bad",
			DriverKey: "someone",
			Doom:      DoomSeed{Consequence: "make_it_rain", TargetKey: "x"},
		}},
	}
	if _, err := BuildFronts(cs); err == nil {
		t.Error("an unknown consequence must fail the build")
	}
}

