// ErrNotJoined means the player has no actor in this world yet.
var ErrNotJoined = errors.New("player has not joined this world")

// Turn progress stages streamed to the client while the LLM works.
const (
	StageIntent = "intent" // понимаю, что игрок имеет в виду
	StageActing = "acting" // исполняю действия игрока
	StageWorld  = "world"  // мир делает свой ход
)

// tickBudget bounds the world's own tick, independent of the turn deadline:
// a worst-case tick (every NPC re-deciding after a reseed) is a batched LLM
// volley that must finish and COMMIT even when the player's replies already
// ate most of the turn. The client may stop waiting; the world must not tear.
const tickBudget = 150 * time.Second

// locationLister is the slice of the persistence layer the service needs to
// name and enumerate locations.
type locationLister interface {
	ListLocationStatesByWorld(ctx context.Context, worldID domain.WorldID) ([]*persistence.LocationState, error)
}

// NPCLine is one NPC reply addressed to the player. The player-facing badge
// is the GESTURE (body language — generated with the words, so it cannot
// contradict them); the emotion label stays internal: it drives relationship
// drift, and shown next to the text it kept reading as a mismatch
// («(радость): ничего не знаю»).
type NPCLine struct {
	ActorID domain.ActorID
	Name    string
	Text    string
	Gesture string
	Emotion string
}

// TurnEventView is a world event of the tick, rendered for the player's feed.
type TurnEventView struct {
	ActorName string
	Text      string
	Type      string
}

// TurnResult is everything one player turn produced.
type TurnResult struct {
	// Narrative describes what the player's own actions led to.
	Narrative string
	// Question, when set, is a clarification request: the input could not be
	// (fully) executed and the world did NOT tick for the unclear part.
	Question string
	// Replies are NPC lines spoken directly to the player this turn.
	Replies []NPCLine
	// Events are the tick's world events visible from the player's location.
	Events []TurnEventView
	// Tick is the world tick the turn's events were committed on. One
	// semantics for every outcome — full turn, failed tick, partial turn: the
	// tick the turn played out in (0 only when nothing executed at all).
	Tick int
	// Shop is the merchant's window a browse rendered this turn (engine
	// prices); nil otherwise. The UI shows it as a panel; acting on it stays
	// textual.
	Shop *ShopView
	// Emotion is the player's explicit emotional state this turn (L5). Set whenever the
	// player named a non-calm feeling — pure state («прихожу в ярость») or alongside a
	// deed («в ярости бью стражника»). It is resolved as a contested self-regulation and
	// applied to the actor (see self_regulation.go); surfaced here for the client too.
	// Empty / StateCalm = none.
	Emotion string
}

// TurnService turns one chat message into world changes: parse → ground
// mentions → validate → execute as events → one world tick → a readable
// result. One turn at a time: the mutex keeps player turns from interleaving
// with each other.
type TurnService struct {
	parser       *extraction.IntentParser
	resolver     *extraction.MentionResolver
	dialogue     *appllm.DialogueService
	narrator     *appllm.NarrationService
	selector     *appllm.EffectSelector
	knowledge    *knowledge.Service
	scribe       *knowledge.Scribe
	mutator      *knowledge.Mutator
	crystallizer *knowledge.Crystallizer
	furnisher    *knowledge.Furnisher
	cues         *appllm.CueClassifier // judges a deed against a rumor hook's cue / an NPC's goal aim
	weaver       *appweaver.Service
	goals        *appgoal.GoalTracker // the player can advance a co-located NPC's goal by helping
	doom         appweaver.Doom       // lands a goal's outcome the player drove to completion
	actors       actor.ActorRepository
	worlds       world.WorldRepository
	events       event.EventStore
	sim          *simulation.Controller
	locs         locationLister
	morph        *morph.Service
	// The verdict engine's consequence channels: synchronous emotions and
	// memories for the deed's target and witnesses (facts before prose).
	memory   *appmemory.MemoryService
	behavior *actor.BehaviorSystem
	logger   *zap.Logger

	// checkRoll resolves an uncertain deed (self-regulation, …) into a graded
	// outcome. Injectable so tests force a tier; defaults to the deterministic dice.
	checkRoll func(seed int64, pool int, pos check.Position) check.Outcome

	// mu serializes player turns: one turn at a time. Conversation state is
	// deliberately NOT process state — the active conversation is folded from
	// the event log per turn (see conversation.go), so it survives restarts
	// and can never disagree with what the log says happened.
	mu sync.Mutex
}

// TurnServiceDeps bundles the service's dependencies.
type TurnServiceDeps struct {
	Parser       *extraction.IntentParser
	Resolver     *extraction.MentionResolver
	Dialogue     *appllm.DialogueService
	Narrator     *appllm.NarrationService
	Selector     *appllm.EffectSelector
	Knowledge    *knowledge.Service
	Scribe       *knowledge.Scribe
	Mutator      *knowledge.Mutator
	Crystallizer *knowledge.Crystallizer
	Furnisher    *knowledge.Furnisher
	Cues         *appllm.CueClassifier
	Weaver       *appweaver.Service
	Goals        *appgoal.GoalTracker
	Doom         appweaver.Doom
	Actors       actor.ActorRepository
	Worlds       world.WorldRepository
	Events       event.EventStore
	Sim          *simulation.Controller
	Locs         locationLister
	Morph        *morph.Service
	Memory       *appmemory.MemoryService
	Behavior     *actor.BehaviorSystem
	Logger       *zap.Logger
}

// NewTurnService builds a TurnService.
func NewTurnService(deps TurnServiceDeps) *TurnService {
	logger := deps.Logger
	if logger == nil {
		logger = zap.NewNop()
	}
	return &TurnService{
		parser:       deps.Parser,
		resolver:     deps.Resolver,
		dialogue:     deps.Dialogue,
		narrator:     deps.Narrator,
		selector:     deps.Selector,
		knowledge:    deps.Knowledge,
		scribe:       deps.Scribe,
		mutator:      deps.Mutator,
		crystallizer: deps.Crystallizer,
		furnisher:    deps.Furnisher,
		cues:         deps.Cues,
		weaver:       deps.Weaver,
		goals:        deps.Goals,
		doom:         deps.Doom,
		actors:       deps.Actors,
		worlds:       deps.Worlds,
		events:       deps.Events,
		sim:          deps.Sim,
		locs:         deps.Locs,
		morph:        deps.Morph,
		memory:       deps.Memory,
		behavior:     deps.Behavior,
		logger:       logger,
		checkRoll:    check.Resolve,
	}
}

// turnContext is everything one turn reads repeatedly: the player, the world
// clock, the location directory and the live roster, loaded once up front.
type turnContext struct {
	player       *actor.Actor
	worldID      domain.WorldID
	worldPremise string // the world's authored description (canon for prompts)
	worldEra     string // the world's time-and-setting canon (keeps generation in period)
	input        string // the player's raw message this turn — their expressed intent, the
	//                     authoritative signal of what they are doing (an observe leaves no
	//                     event trace, but it is right here); read by the weaver scene.
	tick      domain.Tick
	gameTime  domain.GameTime
	locations map[domain.LocationID]*persistence.LocationState
	roster    []*actor.Actor // all living actors except the player

	// arrivedAt marks a location the player moved to earlier THIS turn, so a
	// follow-up observe («выхожу на площадь и осматриваюсь») doesn't repeat
	// the arrival description verbatim.
	arrivedAt domain.LocationID

	// conv caches the turn's folded conversation; convLoaded distinguishes
	// "not folded yet" from "folded: no active talk".
	conv       *Conversation
	convLoaded bool

	// mentions is the turn's grounded MentionSet (С2): every entity the player
	// referred to, resolved to its world id. The deterministic hooks read it by
	// membership; it is journaled for replay. Filled in ProcessInput after the parse.
	mentions *extraction.MentionSet

	// expField caches the turn's experiential field — the player's reference scope
	// (here-now ∪ visited ∪ remembered ∪ known) assembled once for grounding;
	// fieldLoaded distinguishes "not assembled yet" from "assembled: empty".
	expField   *experientialField
	fieldLoaded bool
}

func (tc *turnContext) locationName(id domain.LocationID) string {
	if loc, ok := tc.locations[id]; ok {
		return loc.Name
	}
	return string(id)
}

func (tc *turnContext) locationDescription(id domain.LocationID) string {
	if loc, ok := tc.locations[id]; ok {
		if d, _ := loc.State["description"].(string); d != "" {
			return d
		}
	}
	return ""
}

// actorByID finds a roster NPC by id, nil when unknown.
func (tc *turnContext) actorByID(id domain.ActorID) *actor.Actor {
	for _, a := range tc.roster {
		if a.ID == id {
			return a
		}
	}
	return nil
}

// coLocated returns the living NPCs standing where the player stands.
func (tc *turnContext) coLocated() []*actor.Actor {
	here := tc.player.GetCurrentLocation()
	var out []*actor.Actor
	for _, a := range tc.roster {
		if a.GetCurrentLocation() == here {
			out = append(out, a)
		}
	}
	return out
}

// ProcessInput plays one full player turn. progress (optional) is invoked with
// a Stage* constant as the turn moves through its phases.
func (s *TurnService) ProcessInput(
	ctx context.Context,
	userID, text string,
	progress func(stage string),
) (*TurnResult, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	if progress == nil {
		progress = func(string) {}
	}

	worldID := s.sim.WorldID()
	ctx = repository.WithWorldID(ctx, worldID)

	tc, err := s.loadTurnContext(ctx, worldID, userID)
	if err != nil {
		return nil, err
	}
	tc.input = text

	// The player speaking IS the claim to drive the world: if the simulation
	// runs autonomously (e.g. after an operator resume), take the controls back.
	if s.sim.Mode() != simulation.ModePlayerDriven {
		if err := s.sim.SetMode(simulation.ModePlayerDriven); err != nil {
			return nil, fmt.Errorf("switch to player-driven mode: %w", err)
		}
	}

	// A felled player cannot act. If they are merely DOWN (unconscious), the world
	// resolves their fate while they only watch: a willing soul may brave the danger
	// to drag them clear — or, if they have terrified the town, the hazard finishes
	// them. If they are DEAD, the story is over for this character. Either way, no
	// parse: the player's words cannot move a body that will not answer.
	if tc.player.IsDead() {
		return &TurnResult{Narrative: "Ты мёртв. Для этого героя история окончена — чтобы начать заново, пересоздай мир."}, nil
	}
	if playerUnconscious(tc.player) {
		return s.resolveIncapacitated(ctx, worldID, userID, tc), nil
	}

	// Stage 0: parse the message into atomic actions. Gibberish is not a
	// server error — it is a question back to the player.
	progress(StageIntent)
	parsed, _, err := s.parser.Parse(ctx, text, s.parseContext(ctx, tc))
	if errors.Is(err, extraction.ErrNoActions) {
		return &TurnResult{Question: "Не понял, что ты хочешь сделать — опиши действие иначе."}, nil
	}
	if err != nil {
		return nil, fmt.Errorf("parse input: %w", err)
	}
	// A state-only turn: L5 found a feeling with no deed («прихожу в ярость») and routed it
	// out of the deed pipeline (Actions empty, Emotion set). The feeling IS the turn —
	// resolve it as a CONTESTED self-regulation (the world opposes it; a roll decides how
	// much lands), then let the world tick so the new state lives and NPCs perceive it.
