// Ownership transfers are mechanics, not prose. Taking, giving, buying,
// selling and stealing all converge on the same primitives: ground the thing
// in what is physically HERE, decide how it changes hands — deterministic
// relink for unowned things, the owner's in-character consent (a dialogue
// line carrying a decision) for owned ones, a stealth contest for covert
// takes — then execute: relink owner, move coins, append the transfer event.

// ============================================================================
// take
// ============================================================================

func (s *TurnService) doTake(ctx context.Context, tc *turnContext, action extraction.ParsedPlayerAction) (*actionOutcome, error) {
	mention := strings.TrimSpace(action.Topic)
	if mention == "" {
		return &actionOutcome{question: "Что именно взять?"}, nil
	}

	thing, question, err := s.groundPresentThing(ctx, tc, mention)
	if err != nil {
		// A technical grounding failure must degrade, not cancel the whole
		// turn (the old behaviour killed multi-action turns over one bad
		// lookup): treat it as "not found" and let the gate judge.
		s.logger.Warn("take grounding failed; degrading to not-found", zap.String("mention", mention), zap.Error(err))
		thing, question = nil, "Здесь не видно такого."
	}
	if thing == nil {
		// Not among the present things: the common-sense gate may birth a
		// mundane item out of thin air («хватаю факел» in a tavern), one LLM
		// call total. A refusal falls back to the honest question.
		if stub := s.crystallizeAt(ctx, tc, mention); stub != nil {
			if err := s.executeTransfer(ctx, tc, stub, nil, tc.player.ID, 0, event.TransferPickup); err != nil {
				return nil, err
			}
			return s.transferNarrative(ctx, tc, action, fmt.Sprintf("Ты берёшь: %s.", stub.Name)), nil
		}
		if question == "" {
			question = "Здесь не видно такого."
		}
		return &actionOutcome{question: question}, nil
	}
	if question != "" {
		return &actionOutcome{question: question}, nil
	}

	// Physical form bounds what bare hands can carry off (entity.Kind.Carriable):
	// lore is immaterial, a feature too large and fixed, a substance slips through
	// fingers (a handful at most — a quantity needs a vessel). Only a discrete item
	// is carried off whole. Dash-apposition keeps the phrasing morphology-safe.
	switch thing.Kind {
	case entity.KindLore:
		return &actionOutcome{narrative: fmt.Sprintf("%s — это предание, не вещь: в руки его не взять.", thing.Name)}, nil
	case entity.KindFeature:
		return &actionOutcome{narrative: fmt.Sprintf("%s — часть этого мира, с собой не унести.", thing.Name)}, nil
	case entity.KindSubstance:
		return &actionOutcome{narrative: fmt.Sprintf("%s — пригоршню зачерпнуть можно, но чтобы унести, нужна посуда.", thing.Name)}, nil
	}

	owner := s.ownerOf(ctx, thing)
	if owner != nil && *owner == tc.player.ID {
		return &actionOutcome{narrative: fmt.Sprintf("%s и так при тебе.", thing.Name)}, nil
	}

	// Owner standing right here: covert wording means a stealth contest; an
	// open take of a WARE settles at the deterministic engine price (money is
	// mechanics — no NPC will in the loop); only what money cannot buy
	// (value = 0) goes through the in-character consent path.
	if owner != nil {
		if holder := tc.actorByID(*owner); holder != nil && holder.GetCurrentLocation() == tc.player.GetCurrentLocation() {
			if action.Covert {
				return s.stealFrom(ctx, tc, thing, holder)
			}
			if thing.Value > 0 {
				return s.buyAtPrice(ctx, tc, thing, holder)
			}
			return s.proposeTransfer(ctx, tc, thing, holder, appllm.OfferPlayerBuys, action)
		}
	}

	// Unowned, or the owner is elsewhere while the thing lies here: it can be
	// picked up. The world remembers the pickup either way; an absent owner's
	// grievance is a future mechanic, not a blocker.
	if err := s.executeTransfer(ctx, tc, thing, owner, tc.player.ID, 0, event.TransferPickup); err != nil {
		return nil, err
	}
	return s.transferNarrative(ctx, tc, action, fmt.Sprintf("Ты забираешь: %s.", thing.Name)), nil
}

// ============================================================================
// give
// ============================================================================

func (s *TurnService) doGive(ctx context.Context, tc *turnContext, action extraction.ParsedPlayerAction) (*actionOutcome, error) {
	mention := strings.TrimSpace(action.Topic)
	if mention == "" {
		return &actionOutcome{question: "Что именно отдать?"}, nil
	}

	thing, question, err := s.groundPresentThing(ctx, tc, mention)
	if err != nil {
		// Give never crystallizes (one cannot gift a thing that does not
		// exist), but a technical failure still must not cancel the turn.
		s.logger.Warn("give grounding failed; degrading", zap.String("mention", mention), zap.Error(err))
		return &actionOutcome{question: "Здесь не видно такого."}, nil
	}
	if question != "" {
		return &actionOutcome{question: question}, nil
	}

	owner := s.ownerOf(ctx, thing)
	if owner == nil || *owner != tc.player.ID {
		return &actionOutcome{narrative: fmt.Sprintf("%s — не твоя вещь, не тебе её отдавать.", thing.Name)}, nil
	}

	addressees, question, err := s.resolveAddressees(ctx, tc, action.Who)
	if err != nil {
		return nil, err
	}
	if question != "" {
		return &actionOutcome{question: question}, nil
	}
	var target *actor.Actor
	switch len(addressees) {
	case 0:
		co := tc.coLocated()
		if len(co) == 1 {
			target = co[0]
		} else {
			return &actionOutcome{question: "Кому именно отдать?"}, nil
		}
	case 1:
		target = addressees[0]
	default:
		return &actionOutcome{question: "Одну вещь — одному человеку. Кому именно?"}, nil
	}

	// Money is mechanics: selling a ware settles at the engine price; a gift
	// is accepted by disposition. The consent path remains only for selling
	// what money cannot buy (value = 0 — let the NPC's will judge that).
	if strings.TrimSpace(action.Payment) != "" && thing.Value > 0 {
		return s.sellAtPrice(ctx, tc, thing, target)
	}
	if strings.TrimSpace(action.Payment) == "" {
		return s.giveGift(ctx, tc, thing, target)
	}
	return s.proposeTransfer(ctx, tc, thing, target, appllm.OfferPlayerSells, action)
}

// ============================================================================
// attack
// ============================================================================

func (s *TurnService) doAttack(ctx context.Context, tc *turnContext, action extraction.ParsedPlayerAction) (*actionOutcome, error) {
	addressees, question, err := s.resolveAddressees(ctx, tc, action.Who)
	if err != nil {
		return nil, err
	}
	if question != "" {
		return &actionOutcome{question: question}, nil
	}
	if len(addressees) == 0 {
		return &actionOutcome{question: "На кого именно?"}, nil
	}
	target := addressees[0]

	// The deed is the bare act (verb + optional instrument). The TARGET is NOT
	// folded in: it's carried by the verdict (v.targetNPC) and named by the
	// facts — repeating it here made the victim's own memory read «На меня
	// нападают: Вася … ударить: Купец Изольт» (first person framing, third
	// person self-reference) and the witness's double-name the target. No name
	// in the deed also means no morphology concern.
	deed := "ударить"
	if how := strings.TrimSpace(action.Topic); how != "" {
		deed += " " + how
	}

	// The blow's BODILY toll is an uncertain contest: a check (biased by the player's
	// feeling — rage harder but wilder, fear pulled but wary) sets how it lands and what
	// it costs. Resolve and commit the harm BEFORE the social verdict, so the strike fact
	// colours the narration and the target's wound is real, not just their fright.
	strike := s.resolveStrike(tc, target)
	s.applyStrike(ctx, tc, target, strike)

	// Атака — готовый вердикт: цель заземлена точным граундингом, заряд
	// враждебен по определению. Ядро коммитит событие, эмоции, отношение и
	// память жертвы со свидетелями СЕЙЧАС; рендерер описывает свершившееся.
	v := &verdict{
		kind:      verdictAssault,
		targetNPC: target,
		facts:     append([]string{strikeFact(strike.tier)}, assaultFacts(target.Identity.Name, len(tc.coLocated())-1)...),
		// A blow before the watch draws the law's challenge — the struck target,
		// even a guard, is the one wronged and leads nothing.
		lawConfront: lawConfrontationFact(guardsAmong(witnessesExcept(tc.coLocated(), target.ID))),
	}
	if err := s.applyVerdict(ctx, tc, deed, v); err != nil {
		return nil, fmt.Errorf("apply attack verdict: %w", err)
	}

	narrative, err := s.narrator.NarratePlayerAction(ctx, s.verdictNarrationInput(ctx, tc, deed, v, action.Topic))
	if err != nil {
		s.logger.Warn("attack narration failed", zap.Error(err))
		narrative = fmt.Sprintf("Ты пытаешься %s. %s", deed, strings.Join(v.facts, " "))
	}
	return &actionOutcome{narrative: withConfront(narrative, v)}, nil
}

// hostileShift / friendlyShift are the relationship deltas of a hostile blow
// and an accepted gift — the same scale conversation sentiment uses.
const (
	hostileShift  = 8
	friendlyShift = 4
)

