// proposeTransfer puts the proposal to the thing's owner (or receiver) as a
// conversation move: the offer opens/continues the talk, the NPC answers in
// character with a structured decision, and deterministic code executes it.
func (s *TurnService) proposeTransfer(
	ctx context.Context,
	tc *turnContext,
	thing *entity.Entity,
	counterpart *actor.Actor,
	direction appllm.OfferDirection,
	action extraction.ParsedPlayerAction,
) (*actionOutcome, error) {
	// The proposal is a conversation move — it lands in the same fold-backed
	// talk as any line, so the haggle's history is simply the conversation's.
	conv := s.activeConversation(ctx, tc)
	if conv == nil || !conv.Has(counterpart.ID) {
		if conv != nil {
			s.endConversation(ctx, tc, conv)
		}
		var err error
		if conv, err = s.startConversation(ctx, tc, []*actor.Actor{counterpart}, thing.Name); err != nil {
			return nil, fmt.Errorf("open transfer conversation: %w", err)
		}
	}

	// The player's own words enter the log when they spoke; the structured
	// proposal itself reaches the NPC through the offer frame.
	if line := strings.TrimSpace(action.Utterance); line != "" {
		playerLine := event.NewGameEvent(
			event.EventTypeDialogueLine,
			tc.player.ID, tc.player.GetCurrentLocation(), tc.worldID, tc.tick,
			event.DialogueEventData{
				ConversationID: conv.ID,
				SpeakerID:      tc.player.ID,
				ListenerIDs:    []domain.ActorID{counterpart.ID},
				Text:           line,
				Language:       "ru",
			},
		)
		if err := s.events.Append(ctx, playerLine); err != nil {
			return nil, fmt.Errorf("append player line: %w", err)
		}
	}

	dc := appllm.DialogueContext{
		Speaker:        counterpart,
		Listener:       tc.player,
		Topic:          thing.Name,
		Mood:           npcMood(counterpart),
		ConversationID: conv.ID,
		WorldID:        tc.worldID,
		CurrentTick:    tc.tick,
	}
	offer := appllm.Offer{
		Direction:   direction,
		ItemName:    thing.Name,
		ItemGist:    thing.Gist,
		PlayerPrice: strings.TrimSpace(action.Payment),
	}

	// Facts before prose: the will is decided first (a tiny frame), the core
	// EXECUTES it, and only then the reply is rendered with the executed
	// verdict in the prompt — «готов взять!» can no longer ride a refusal.
	decision, err := s.dialogue.DecideOffer(ctx, dc, offer)
	if err != nil {
		s.logger.Warn("offer decision failed", zap.String("npc", counterpart.Identity.Name), zap.Error(err))
		return &actionOutcome{narrative: fmt.Sprintf("%s обдумывает твоё предложение.", counterpart.Identity.Name)}, nil
	}

	var settledNote string
	if decision.Decision == appllm.OfferAccepted {
		note, err := s.executeConsented(ctx, tc, thing, counterpart, direction, decision.Price)
		if err != nil {
			return nil, err
		}
		if note != "" {
			// The purse vetoed the deal: the decision honestly degrades.
			decision = &appllm.OfferDecision{Decision: appllm.OfferRefused}
			settledNote = note
		}
	}

	// Facts before prose, at the surface too: every consent outcome carries a
	// deterministic, closed-vocabulary line stating what changed hands. Before,
	// a refusal's only signal was the model's lyric and the player could not
	// tell whether the thing moved. The purse-veto note, when present, already
	// is that fact, so it wins.
	if settledNote == "" {
		settledNote = offerOutcomeFact(counterpart.Identity.Name, thing.Name, direction, *decision)
	}
	reply := s.offerReply(ctx, tc, conv.ID, counterpart, dc, offer, *decision)
	return &actionOutcome{reply: reply, narrative: settledNote}, nil
}

// offerOutcomeFact states a consent transfer's outcome in one deterministic
// line, built from the executed verdict — never the model. The spoken reply
// then only COLOURS this fact. Mirrors the gift path's «{Name} принимает: …».
func offerOutcomeFact(npcName, thingName string, direction appllm.OfferDirection, decision appllm.OfferDecision) string {
	playerTakes := direction == appllm.OfferPlayerBuys
	switch decision.Decision {
	case appllm.OfferAccepted:
		if playerTakes {
			return fmt.Sprintf("%s отдаёт: %s.", npcName, thingName)
		}
		return fmt.Sprintf("%s принимает: %s.", npcName, thingName)
	case appllm.OfferCounter:
		return fmt.Sprintf("%s просит за это: %d мон.", npcName, decision.Price)
	default: // OfferRefused and any unknown verdict: the safe, honest reading.
		if playerTakes {
			return fmt.Sprintf("%s не отдаёт: %s.", npcName, thingName)
		}
		return fmt.Sprintf("%s не берёт: %s.", npcName, thingName)
	}
}

// offerReply renders and journals the NPC's spoken answer from the executed
// decision. Degrades to a closed line — the deal already stands either way.
func (s *TurnService) offerReply(
	ctx context.Context,
	tc *turnContext,
	convID string,
	counterpart *actor.Actor,
	dc appllm.DialogueContext,
	offer appllm.Offer,
	decision appllm.OfferDecision,
) *NPCLine {
	resp, err := s.dialogue.SpeakOfferOutcome(ctx, dc, offer, decision)
	if err != nil {
		s.logger.Warn("offer outcome reply failed", zap.String("npc", counterpart.Identity.Name), zap.Error(err))
		text := map[string]string{
			appllm.OfferAccepted: "По рукам.",
			appllm.OfferCounter:  fmt.Sprintf("Моя цена — %d мон.", decision.Price),
			appllm.OfferRefused:  "Нет. Эта вещь не для того.",
		}[decision.Decision]
		resp = &appllm.OfferResponse{Content: text, Decision: decision.Decision, Price: decision.Price}
	}

	// The NPC's answer is a spoken line in the log — the next haggling round
	// builds on it through the conversation history.
	npcLine := event.NewGameEvent(
		event.EventTypeDialogueLine,
		counterpart.ID, tc.player.GetCurrentLocation(), tc.worldID, tc.tick,
		event.DialogueEventData{
			ConversationID: convID,
			SpeakerID:      counterpart.ID,
			ListenerIDs:    []domain.ActorID{tc.player.ID},
			Text:           resp.Content,
			Emotion:        resp.Emotion,
			Language:       "ru",
		},
	)
	if err := s.events.Append(ctx, npcLine); err != nil {
		s.logger.Warn("append offer reply failed", zap.Error(err))
	}

	return &NPCLine{
		ActorID: counterpart.ID,
		Name:    counterpart.Identity.Name,
		Text:    resp.Content,
		Gesture: resp.BodyLanguage,
		Emotion: resp.Emotion,
	}
}

// executeConsented settles an accepted offer: coins move, ownership relinks,
// the transfer is journaled. Returns a non-empty note when the player's purse
// vetoed the deal (the honest degradation path).
func (s *TurnService) executeConsented(
	ctx context.Context,
	tc *turnContext,
	thing *entity.Entity,
	counterpart *actor.Actor,
	direction appllm.OfferDirection,
