// ownerVigilance is how hard an owner is to fool, in dice the thief LOSES from their
// pool: their wariness (paranoia), the extra eyes of a crowd, and a watchful dislike
// of the thief. The successor to the old hand-tuned chance penalties, now expressed
// in the shared currency of the check pool.
func ownerVigilance(tc *turnContext, owner *actor.Actor) int {
	dice := 0
	if owner.Identity != nil && owner.Identity.Personality != nil {
		dice += int(math.Round(float64(owner.Identity.Personality.Paranoia) * paranoiaVigilanceDice))
	}
	if extraEyes := len(tc.coLocated()) - 1; extraEyes > 0 {
		dice += extraEyes / crowdEyesPerDie
	}
	if affectionToward(owner, tc.player.ID) < 0 {
		dice++ // a wary owner keeps a closer watch on a disliked guest
	}
	return dice
}

// ============================================================================
// shared primitives
// ============================================================================

// groundPresentThing grounds the mention in the scene's PHYSICAL contents.
// Tier zero is the lexical focus over present names; the resolver LLM decides
// only when lexicon fails. Knowing about a thing elsewhere is not enough —
// hands need it here.
func (s *TurnService) groundPresentThing(ctx context.Context, tc *turnContext, mention string) (*entity.Entity, string, error) {
	if s.knowledge == nil {
		return nil, "Здесь нет такого.", nil
	}
	here := tc.player.GetCurrentLocation()
	holders := []domain.ActorID{tc.player.ID}
	for _, a := range tc.coLocated() {
		holders = append(holders, a.ID)
	}
	present, err := s.knowledge.ListPresent(ctx, knowledge.Scope{
		WorldID:  tc.worldID,
		ActorID:  tc.player.ID,
		Location: here,
	}, holders)
	if err != nil {
		return nil, "", fmt.Errorf("list present things: %w", err)
	}
	if len(present) == 0 {
		return nil, "Здесь нет ничего, что можно было бы взять в руки.", nil
	}

	byID := make(map[domain.EntityID]*entity.Entity, len(present))
	candidates := make([]extraction.Candidate, 0, len(present))
	for _, e := range present {
		byID[e.ID] = e
		candidates = append(candidates, extraction.Candidate{
			ID:    string(e.ID),
			Name:  e.Name,
			Note:  truncateRunes(e.Gist, 80),
			Forms: s.candidateForms(e.Name, e.Aliases),
		})
	}
	// One grammar-bound resolution: the structural accelerator lands a named thing
	// («кружку» → кружка) without the model; a fuzzy description falls to it. The
	// present scope is the frame — hands reach only what is here.
	group, err := s.resolver.ResolveGroup(ctx, tc.worldID, mention, extraction.MentionWhat, candidates)
	if err != nil {
		return nil, "", err
	}
	if len(group) == 0 {
		return nil, "Здесь не видно такого — оглядись или спроси у людей.", nil
	}
	if e, ok := byID[domain.EntityID(group[0].ID)]; ok {
		return e, "", nil
	}
	return nil, "Здесь не видно такого.", nil
}

// ownerOf returns the entity's owning actor, nil when unowned.
func (s *TurnService) ownerOf(ctx context.Context, e *entity.Entity) *domain.ActorID {
	links, err := s.knowledge.Links(ctx, e.ID)
	if err != nil {
		return nil
	}
	for _, l := range links {
		if l.LinkType == entity.LinkOwner && l.SubjectType == entity.SubjectActor {
			id := domain.ActorID(l.SubjectID)
			return &id
		}
	}
	return nil
}

// executeTransfer is the deterministic handover: ownership relinks, the
// located_at pin lifts (the thing now travels with its holder), the world
// remembers the event.
func (s *TurnService) executeTransfer(
	ctx context.Context,
	tc *turnContext,
	thing *entity.Entity,
	from *domain.ActorID,
	to domain.ActorID,
	price int,
	kind event.TransferKind,
) error {
	if err := s.knowledge.TransferOwnership(ctx, thing.ID, to); err != nil {
		return fmt.Errorf("transfer ownership: %w", err)
	}

	evt := event.NewGameEvent(
		event.EventTypeEntityTransferred,
		to, tc.player.GetCurrentLocation(), tc.worldID, tc.tick,
		event.EntityTransferEventData{
			EntityID:    thing.ID.String(),
			EntityName:  thing.Name,
			FromActorID: from,
			ToActorID:   to,
			Price:       price,
			Kind:        kind,
		},
	)
	if err := s.events.Append(ctx, evt); err != nil {
		return fmt.Errorf("append transfer event: %w", err)
	}
	return nil
}

// transferNarrative dresses a settled pickup in narrator prose, degrading to
// the closed fallback line. The transfer is ALREADY executed — the fact says
// so, and the renderer cannot describe a failure to grab.
func (s *TurnService) transferNarrative(ctx context.Context, tc *turnContext, action extraction.ParsedPlayerAction, fallback string) *actionOutcome {
	deed := strings.TrimSpace(action.Topic)
	if deed == "" {
		deed = "взять вещь"
	} else {
		deed = "взять: " + deed
	}
	narrative, err := s.narrator.NarratePlayerAction(ctx,
		s.narrateFactsInput(ctx, tc, deed, []string{fallback}, action.Topic, false))
	if err != nil || strings.TrimSpace(narrative) == "" {
		return &actionOutcome{narrative: fallback}
	}
	return &actionOutcome{narrative: narrative}
}

// shiftRelationship moves an NPC's standing toward the player through the shared
// relationship primitive. Many callers use it (a gift, a kindness, an assault, a
// destruction), so the reason follows the SIGN of the shift — a souring is hostility, a
// warming is kindness. The old fixed «дар» (a gift) was right when this had a single
// gift caller, but once it was reused for hostile shifts it mislabelled every assault as
// a present — poisoning any memory or narration keyed on the relationship's reason.
func (s *TurnService) shiftRelationship(ctx context.Context, tc *turnContext, npc *actor.Actor, delta int) {
	reason := "доброта"
	if delta < 0 {
		reason = "враждебность"
	}
	events := social.ShiftRelationship(npc, tc.player, delta, reason, tc.worldID, tc.tick)
	for _, evt := range events {
		if err := s.events.Append(ctx, evt); err != nil {
			s.logger.Warn("append relationship shift failed", zap.Error(err))
		}
	}
	if err := s.actors.Update(ctx, npc); err != nil {
		s.logger.Warn("persist relationship shift failed", zap.Error(err))
	}
}

