// ── L5 cases: explicit emotional state ────────────────────────────────────────

// stateCase tests L5's TWO focused passes: DetectState (emotion enum) AND StripState (the
// state-strip). normHas = a deed substring the remainder MUST keep (no deed lost); normNot =
// a state substring it MUST drop (state peeled). Either may be empty to skip. State-ONLY
// utterances expect an empty remainder (deedless), so normHas stays empty and normNot checks
// the strip.
type stateCase struct {
	utterance, want string
	normHas, normNot string
}

var stateCases = []stateCase{
	{"прихожу в ярость и переворачиваю стол", "гнев", "переворачиваю", "ярость"},
	{"в ужасе застываю, не в силах шевельнуться", "страх", "", "ужас"}, // state-only → remainder deedless
	{"со слезами радости обнимаю брата", "радость", "обнимаю", "слез"},
	{"с отвращением отшатываюсь от трупа", "отвращение", "", "отвращени"},
	{"в горе оседаю на колени у могилы", "печаль", "", "горе"},
	{"ошеломлённый, не верю своим глазам", "удивление", "", "ошеломл"},
	{"руки дрожат, но я натягиваю тетиву и пускаю стрелу", "страх", "натягиваю", "дрожат"}, // bodily sign + deed
	// e2e seam #1: involuntary-reaction FINITE verbs read as deeds to L2 unless L5 peels them.
	// Held-out from the prompt (which uses в смятении/дух перехватило/сердце ёкнуло, not these).
	{"холодею от страха, но жму на рычаг", "страх", "жму", "холоде"},
	{"цепенею от ужаса и всё равно тянусь к мечу", "страх", "тянусь", "цепене"},
	// guards: NO explicit emotion → calm, and the remainder is the deed VERBATIM (nothing stripped)
	{"со всей силы бью стражника по голове", "спокойствие", "бью стражника", ""},
	{"спокойно осматриваю комнату и иду дальше", "спокойствие", "осматриваю", ""},
	// guard: a REFRAIN deed («не делаю X») is deliberate abstention, NOT state — the strip
	// must KEEP it (e2e #6 regression: strip dropped «не сметаю бумаги»). Held-out verb/object.
	{"не открываю сундук, тихо отхожу к окну", "спокойствие", "не открываю сундук", ""},
	// PROBE: ACTIVE self-calming intent (the «остаться спокойным под огнём» case). L5 reads
	// these as «спокойствие», but is it the SOUGHT-calm or the no-feeling default? And does
	// StripState peel them to a deedless remainder (pure state)? Held-out from both prompts.
	{"пытаюсь взять себя в руки", "спокойствие", "", ""},
	{"глубоко дышу, унимая дрожь в руках", "спокойствие", "", ""},
	{"стараюсь сохранять хладнокровие посреди суматохи", "спокойствие", "", ""},
	// M (false friend): a VERBAL/SOCIAL act DIRECTED at a person (thank, praise, greet) carries
	// feeling-content but is a DEED — the player CHOSE to address someone; it is not an inner
	// state involuntarily lived. The strip must KEEP it (the bug: «благодарю» peeled to empty →
	// the turn mis-routed to self-regulation). Held-out from the prompt (which uses извиниться/
	// окликнуть/поздравить, not these).
	{"сердечно благодарю Анну за её доброту", "спокойствие", "благодар", ""},
	{"хвалю кузнеца за добрую работу", "спокойствие", "хвал", ""},
	{"учтиво приветствую стражника у ворот", "спокойствие", "приветств", ""},
}

func runState(ctx context.Context, p infrallm.SchemaCompleter, samples int) {
	for i, c := range stateCases {
		fmt.Printf("\n%s\n#%-2d хотим [%s]  держит=%q  снимает=%q\n   «%s»\n%s\n",
			strings.Repeat("═", 90), i+1, c.want, c.normHas, c.normNot, c.utterance, strings.Repeat("─", 90))
		for s := 1; s <= samples; s++ {
			emo, eErr := extraction.DetectState(ctx, p, c.utterance)
			deeds, dErr := extraction.StripState(ctx, p, c.utterance)
			if eErr != nil || dErr != nil {
				fmt.Printf("  ⃟%d ✗ emotion=%v strip=%v\n", s, eErr, dErr)
				continue
			}
			low := strings.ToLower(deeds)
			emoOK := emo == c.want
			hasOK := c.normHas == "" || strings.Contains(low, strings.ToLower(c.normHas))
			notOK := c.normNot == "" || !strings.Contains(low, strings.ToLower(c.normNot))
			mark := "✓"
			if !emoOK || !hasOK || !notOK {
				mark = "✗"
			}
			detail := ""
			if !emoOK {
				detail += " [эмоция]"
			}
			if !hasOK {
				detail += " [потерял деяние]"
			}
			if !notOK {
				detail += " [состояние не снято]"
			}
			fmt.Printf("  ⃟%d  %-12s → «%s»  %s%s\n", s, emo, deeds, mark, detail)
		}
	}
}

