// ── Ls speech: the speech-act layer (ClassifySpeechAct) IN ISOLATION ──────────
// Tell statement / question / trade / DEED apart (a physical deed mid-dialogue must
// fall through, kind=deed) and name the addressee by closed-vocab deixis (собеседник /
// все / name). Score one field per case. Held-out from speechPrompt.
type speechCase struct {
	utterance   string
	inConv      bool
	affords     []string // addressee affordances → dynamic kind enum (nil = non-merchant)
	field, want string   // kind | addressee
}

// merchantAffords is the affordance set when a merchant is addressable: trade is in the
// grammar. nil means no merchant — trade is grammatically impossible.
var merchantAffords = []string{extraction.SpeechTrade}

var speechCases = []speechCase{
	// kind: the THREE lanes told apart (speak / trade / deed — NOT statement-vs-question:
	// that cut is unstable on 4B and not perception's job; see speechPrompt comment).
	// All trade-context cases run WITH a merchant addressable (merchantAffords).
	{"довольно лжи, говори правду", true, merchantAffords, "kind", "speak"}, // assertion/command line
	{"откуда у тебя этот шрам?", true, merchantAffords, "kind", "speak"},    // general question about the PERSON
	// trade CLASS — wares-inquiry across forms (imperative + interrogative, several commerce
	// verbs). The 4B reads a bare «чем торгуешь?» as conversation; the prompt teaches the
	// SUBJECT test (about the GOODS for sale → trade), validated over the whole class here.
	{"покажи-ка, чем богат твой прилавок", true, merchantAffords, "kind", "trade"}, // imperative
	{"чем торгуешь, почтенный?", true, merchantAffords, "kind", "trade"},           // interrogative «торговать» — the seam
	{"что продаёшь, хозяин?", true, merchantAffords, "kind", "trade"},              // interrogative «продавать»
	{"а что у тебя в лавке нынче?", true, merchantAffords, "kind", "trade"},        // «в лавке»
	// trade BOUNDARY false friends — commerce verb, but ABOUT the merchant/business, NOT a
	// wares request → speak. These keep the class rule from over-reaching to «any торг-word».
	{"честно ли торгуешь, плут?", true, merchantAffords, "kind", "speak"}, // about his HONESTY
	{"как нынче торговля идёт?", true, merchantAffords, "kind", "speak"},  // about his BUSINESS state
	// GATE: a NON-merchant addressee (affords=nil) — trade is not in the grammar, so even an
	// explicit wares request CANNOT become trade; it must fall to speak. Proves the leak the
	// dynamic enum closes («чем торгуешь?» to a guard ≠ a shop window).
	{"что продаёшь, хозяин?", true, nil, "kind", "speak"},          // wares Q to a non-merchant → speak
	{"покажи-ка свой товар, служивый", true, nil, "kind", "speak"}, // explicit display req to a non-merchant → speak
	// deed: physical mid-dialogue → fall through (afforded set is irrelevant)
	{"вскакиваю и опрокидываю стол", true, merchantAffords, "kind", "deed"},
	{"молча кладу монету на стойку", true, merchantAffords, "kind", "deed"}, // silent action, «молч» false friend
	// addressee: closed-vocab deixis
	{"эй, народ, расступись!", false, nil, "addressee", "все"},
	{"кто-нибудь здесь видел стражника?", false, nil, "addressee", "все"},
	{"Бром, придержи-ка дверь", false, nil, "addressee", "Бром"},
}

func runSpeech(ctx context.Context, p infrallm.SchemaCompleter, samples int) {
	for i, c := range speechCases {
		conv := ""
		if c.inConv {
			conv = " (в разговоре)"
		}
		fmt.Printf("\n%s\n#%-2d [%s=%s]%s  «%s»\n%s\n",
			strings.Repeat("═", 90), i+1, c.field, c.want, conv, c.utterance, strings.Repeat("─", 90))
		for s := 1; s <= samples; s++ {
			sa, err := extraction.ClassifySpeechAct(ctx, p, c.utterance, c.inConv, c.affords)
			if err != nil {
				fmt.Printf("  ⃟%d ✗ %v\n", s, err)
				continue
			}
			got := sa.Kind
			if c.field == "addressee" {
				got = sa.Addressee
			}
			mark := "✓"
			if got != c.want {
				mark = "✗"
			}
			fmt.Printf("  ⃟%d  [kind=%s addr=«%s»] %s  %s\n", s, sa.Kind, sa.Addressee, got, mark)
		}
	}
}

