// ── domain: bench the domain-specific fields never validated as their own layer ─
// Payment / Covert / Duration / browse / say / PartnerMention / EveryoneMention lived
// inside the single extract call without ever being benched. Run the REAL parser and
// auto-score ONE field per case to find where the 4B's signal is strong vs weak — then
// decide which field needs its own narrow layer (like modality) and which holds in
// extract. Phrases are NOT the extractSystemPrompt examples (removal-test discipline).

type domainCase struct {
	phrase   string
	inConv   bool   // ParseContext.InConversation (needed for say / browse / PartnerMention)
	merchant bool   // a merchant is addressable → trade afforded (gates browse via dynamic enum)
	field    string // which field to score: action|payment|covert|duration|who|modality|count
	want     string // expected value (covert as "true"/"false")
}

var domainCases = []domainCase{
