	{"беру с полки свечу", false, false, "payment", ""}, // no price → must stay empty
	// Covert — stealth take
	{"тихонько вытаскиваю кинжал из-за пояса спящего", false, false, "covert", "true"},
	{"незаметно сую кольцо себе в карман", false, false, "covert", "true"},
	{"снимаю плащ с крючка у входа", false, false, "covert", "false"}, // open take → false
