	{"ты лжёшь мне в лицо", true, false, "action", "say"},
	// PartnerMention / EveryoneMention — closed-vocab references
	{"спрашиваю у неё, где найти брод", true, false, "who", "собеседник"},
	{"кричу всем вокруг: пожар!", false, false, "who", "все"},

	// ── регрессии из интеграции (косяки, на которые наткнулись) ──
	// L1 не должен схлопывать «не X, только Y» → деяние-воздержание выживает (refrain)
	{"не вскрываю сундук, только разглядываю замок", false, false, "modality", "refrain"},
	// L3 conditional через полный парсер (раньше L1-нормализация затирала «если»)
	{"если враг шагнёт ближе, рублю его сплеча", false, false, "modality", "conditional"},
	// «чтобы» — это ЦЕЛЬ, не условие → actual (раньше путалось)
	{"швыряю табурет в окно, чтобы разбить стекло", false, false, "modality", "actual"},
	// attempt через полный парсер
	{"силюсь сдвинуть валун с тропы", false, false, "modality", "attempt"},
	// сегментатор НЕ должен сливать два финитных глагола (был merge)
	{"толкаю торговца в грудь и валю его наземь", false, false, "count", "2"},
	// сегментатор НЕ должен дробить хвостовое «пока» в фантом (был phantom)
	{"караулю у двери, пока все не уснут", false, false, "count", "1"},
	// Деяние = ГЛАГОЛ × ПАЦИЕНС: один глагол над ДВУМЯ разными предметами через «и» →
	// ДВА деяния (per-patient — ядро резолвит каждый отдельно; 4B так и делает).
	{"забираю с верстака молоток и клещи", false, false, "count", "2"},
	{"снимаю со стены лук и колчан", false, false, "count", "2"},
	{"сгребаю со стола монеты и игральные кости", false, false, "count", "2"}, // 2 пациенса (монеты | игр. кости)
	{"беру кружку эля и краюху хлеба", false, false, "count", "2"},
	// CONTRAST: два ФИНИТНЫХ глагола → тоже 2 (но по глаголам, не по пациенсам)
	{"хватаю меч и бросаюсь на стражника", false, false, "count", "2"},
	{"распахиваю ставни и выглядываю наружу", false, false, "count", "2"},
	// GUARD intra-NP: ОДИН предмет из НЕСКОЛЬКИХ слов — НЕ рвать (был баг: «игральные кости»→2)
	{"подбираю со стола игральные кости", false, false, "count", "1"}, // признак+предмет = одна вещь
	{"уношу со стойки кувшин молока", false, false, "count", "1"},     // предмет+чего = одна вещь
}

func domainField(a extraction.ParsedPlayerAction, field string) string {
	switch field {
	case "action":
		return a.Action
	case "payment":
		return a.Payment
	case "duration":
		return a.Duration
	case "who":
		return a.Who
	case "modality":
		return a.Modality
	case "covert":
		if a.Covert {
			return "true"
		}
		return "false"
	}
	return ""
}

func runDomain(ctx context.Context, p infrallm.SchemaCompleter, samples int) {
	parser := extraction.NewIntentParser(p)
	for i, c := range domainCases {
		conv := ""
		if c.inConv {
			conv = " (в разговоре)"
		}
		fmt.Printf("\n%s\n#%-2d [%s=%s]%s  «%s»\n%s\n",
			strings.Repeat("═", 90), i+1, c.field, c.want, conv, c.phrase, strings.Repeat("─", 90))
		pc := extraction.ParseContext{InConversation: c.inConv}
		if c.merchant {
			pc.Affordances = merchantAffords
		}
		for s := 1; s <= samples; s++ {
			pt, _, err := parser.Parse(ctx, c.phrase, pc)
			if err != nil {
				fmt.Printf("  ⃟%d ✗ %v\n", s, err)
				continue
			}
			var got string
			switch c.field {
			case "count": // number of deeds the message segmented into (merge / phantom regressions)
				got = strconv.Itoa(len(pt.Actions))
			case "modality": // the deed's envelope — scan for a non-default value
				got = extraction.ModalityActual
				for _, a := range pt.Actions {
					if a.Modality != "" && a.Modality != extraction.ModalityActual {
						got = a.Modality
						break
					}
				}
			default: // take the field from the action that carries it (first non-empty), else action[0]
				for _, a := range pt.Actions {
					if v := domainField(a, c.field); v != "" && v != "false" {
						got = v
						break
					}
				}
				if got == "" && len(pt.Actions) > 0 {
					got = domainField(pt.Actions[0], c.field)
				}
			}
			mark := "✓"
			if got != c.want {
				mark = "✗"
			}
			fmt.Printf("  ⃟%d  %s  %s\n", s, got, mark)
		}
	}
}

