func runSegment(ctx context.Context, p infrallm.SchemaCompleter, samples int, only string) {
	for i, c := range segCases {
		if only != "" && !strings.Contains(c.cat, only) {
			continue
		}
		fmt.Printf("\n%s\n#%-2d [%s]  «%s»\n      хотим: %s\n%s\n",
			strings.Repeat("═", 90), i+1, c.cat, c.phrase, c.want, strings.Repeat("─", 90))
		for s := 1; s <= samples; s++ {
			frags, err := segment(ctx, p, c.phrase)
			if err != nil {
				fmt.Printf("  ⃟%d ✗ %v\n", s, err)
				continue
			}
			fmt.Printf("  ⃟%d  %s\n", s, strings.Join(frags, "  |  "))
		}
	}
}

func runModality(ctx context.Context, p infrallm.SchemaCompleter, samples int) {
	for i, c := range modCases {
		fmt.Printf("\n%s\n#%-2d хотим [%s]\n   реплика: «%s»\n   деяние:  «%s»\n%s\n",
			strings.Repeat("═", 90), i+1, c.want, c.utterance, c.deed, strings.Repeat("─", 90))
		for s := 1; s <= samples; s++ {
			m, err := extraction.DetectModality(ctx, p, c.utterance, c.deed)
			if err != nil {
				fmt.Printf("  ⃟%d ✗ %v\n", s, err)
				continue
			}
			line := fmt.Sprintf("  ⃟%d  %s", s, m.Modality)
			if strings.TrimSpace(m.Trigger) != "" {
				line += "  (триггер: " + m.Trigger + ")"
			}
			if m.Modality != c.want {
				line += "  ✗"
			} else {
				line += "  ✓"
			}
			fmt.Println(line)
		}
	}
}

func runFull(ctx context.Context, p infrallm.SchemaCompleter, samples int) {
	for i, phrase := range fullPhrases {
		fmt.Printf("\n%s\n#%-2d  «%s»\n%s\n", strings.Repeat("═", 90), i+1, phrase, strings.Repeat("─", 90))
		for s := 1; s <= samples; s++ {
			frags, err := segment(ctx, p, phrase)
			if err != nil {
				fmt.Printf("  ⃟%d ✗ segment %v\n", s, err)
				continue
			}
			enr, err := enrichFragments(ctx, p, phrase, frags)
			if err != nil {
				fmt.Printf("  ⃟%d ✗ enrich %v\n", s, err)
				continue
			}
			fmt.Printf("  ⃟%d\n", s)
			for j, d := range enr {
				fr, err := extractFrame(ctx, p, d)
				if err != nil {
					fmt.Printf("    [%d] «%s» ✗ extract %v\n", j+1, d, err)
					continue
				}
				mod, err := extraction.DetectModality(ctx, p, phrase, d)
				modStr := "actual"
				if err == nil && mod.Modality != "" {
					modStr = mod.Modality
					if strings.TrimSpace(mod.Trigger) != "" {
						modStr += " «" + mod.Trigger + "»"
					}
				}
				fmt.Printf("    [%d] «%s»  →  %s/%s/%s  [%s]\n", j+1, d, fr.Verb, fr.Kind, fr.Charge, modStr)
				for _, r := range []struct{ k, v string }{{"target", fr.Target}, {"instrument", fr.Instrument}, {"locus", fr.Locus}, {"intent", fr.Intent}, {"manner", fr.Manner}} {
					if r.v != "" {
						fmt.Printf("          %s → %s\n", r.k, r.v)
					}
				}
			}
		}
	}
}

package main

import (
	"context"
	"fmt"
	"strings"

	"github.com/dnd-llm/dnd-llm/internal/application/extraction"
	infrallm "github.com/dnd-llm/dnd-llm/internal/infrastructure/llm"
)

// ── e2e pipeline: ONE message through the WHOLE layer stack ────────────────────
//
// The per-layer subcommands (segment, modality, …) each bench ONE layer in
// isolation. This one does the opposite: it drives the REAL production parser
// (extraction.ParseTraced — single source of truth, the same Parse the turn path
// calls) so a boundary message flows through every layer AT ONCE, ENTERING some and
// BYPASSING others, and prints the flow layer by layer. The point is the SEAMS: a
// deed L2 drops, a marker an L3 gate misses, an emotion L2 must not treat as a deed,
// a routed query that must skip the deed pipeline entirely. Cases are picked so each
// lights a DIFFERENT subset of layers.
//
// Layers shown:
//   L1 discourse  — action|query + revision-normalized utterance (ALWAYS; query routes out)
//   Ls speech     — speak|trade|deed, gated by mayBeSpeech (routes out on speak/trade)
//   L2 segment    — the deeds the utterance cut into (ALWAYS on the deed lane)
//   roles         — per deed: kind/charge + target/instrument/locus/intent/manner
//   L3 modality   — per deed, GATED on a marker word (else actual, bypassed)
//   Lc covert     — per deed, GATED on an acquisitive deed OR a stealth cue
//   Lp payment    — per deed, GATED on take/give
//   Ld duration   — per deed, ALWAYS
//   L4 ground     — the references the deed hands the resolver (DB-scoped downstream)
//   L5 state      — the player's explicit emotion (parallel channel, not the action path)
//
// NOTE on integration gaps this VIEW surfaces (not bench bugs — findings):
//   · L1.5 enrich (anaphora → name) is validated in the `full` bench but NOT wired into
//     Parse, so a pronoun crossing a subordinate clause may reach L4 unresolved.
//   · L4 grounding and L5 state are not inlined in Parse (live in the turn service /
//     Stage 4); here L5 is driven directly and L4 is shown as the hand-off queue.

type pipeCase struct {
	phrase    string
	inConv    bool
	affords   []string
	probe     string         // what flow / seam this case exercises
	wantRoute string         // "" (deed lane) | "query" | "speech"
	wantDeeds int            // expected L2 deed count; 0 = skip (routed)
	wantMod   map[int]string // deed idx → expected modality; absent = skip
	wantState string         // expected L5 emotion; "" → спокойствие
	seam      string         // non-empty: a KNOWN seam this case reveals (a ✗ here is the finding)
}

// pipelineCases — boundary inputs, each through a DIFFERENT path. Held-out from every
// layer's prompt (the closed signal words «не/если/пока/хотя нет/сперва» are defining
// markers, allowed; the CONTENT — verbs, names, things — is held out).
var pipelineCases = []pipeCase{
	{
		phrase: "пинаю валяющийся башмак",
		probe:  "минимальный путь: L2+roles+Ld+L4; L1-правка, Ls, L3, Lp, L5 — в обход",
		wantDeeds: 1, wantMod: map[int]string{0: "actual"},
	},
	{
		phrase: "сколько у трактирщика осталось эля?",
		probe:  "L1 распознаёт вопрос → query-роут; весь дид-конвейер в обход",
		wantRoute: "query",
	},
	{
		phrase: "лезу в окно, хотя нет, выламываю засов",
		probe:  "L1 нормализует отмену ДО L2 — сегментатор видит исправленную реплику (1 деяние)",
		wantDeeds: 1,
	},
	{
		phrase: "холодею от страха, но всё равно жму на рычаг",
		probe:  "L5 ловит страх; L2 НЕ делает «холодею от страха» деянием (это состояние) → 1 деяние",
		wantDeeds: 1, wantState: "страх",
	},
	{
		phrase: "пока часовой клюёт носом, я подбираюсь к нему со спины",
		probe:  "богатый путь: L3 conditional(пока) + Lc covert(со спины) + L4(часовой); анафора «нему» — проверка шва L1.5",
		wantDeeds: 1, wantMod: map[int]string{0: "conditional"},
	},
	{
		phrase: "не сметаю бумаги со стола, лишь придвигаю свечу ближе",
		probe:  "L3 refrain на деянии-1 (не…); деяние-2 actual; «лишь» — акцент, не модальность",
		wantDeeds: 2, wantMod: map[int]string{0: "refrain", 1: "actual"},
	},
	{
		phrase:  "а что за зелья стоят у тебя на верхней полке?",
		inConv:  true,
		affords: merchantAffords,
		probe:   "в разговоре Ls-гейт всегда вкл; запрос про товар → trade → browse-роут",
		wantRoute: "speech",
	},
	{
		phrase: "потираю озябшие ладони",
		probe:  "безопасный бит: L2 1 деяние, нет цели → L4 в обход; L3/Lc/Lp в обход; L5 спокойствие",
		wantDeeds: 1, wantState: "спокойствие",
	},
	{
		phrase: "едва купец отвернётся, я смахиваю кошель с прилавка",
		probe:  "L3 зовётся всегда (лексический гейт снят, #3 done); остаточный шов — КЛАССИФИКАТОР не обобщает «едва» на conditional",
		wantDeeds: 1, wantMod: map[int]string{0: "conditional"},
		seam:   "гейт mayHaveModality удалён (CLAUDE.md: никаких списков слов в ядре) — «едва» теперь ДОХОДИТ до L3. Но сам классификатор читает «едва»/«стоит…как» как actual (а «когда»/«чуть» — верно): определение conditional в промпте якорится на если/пока/как только и не передаёт ВЕСЬ класс зачинов-триггеров. Чинить в #2 — усилить ОПРЕДЕЛЕНИЕ (триггерное событие по смыслу), не список примеров.",
	},
}

func runPipeline(ctx context.Context, p infrallm.SchemaCompleter, samples int) {
	parser := extraction.NewIntentParser(p)
	pass, fail := 0, 0
	for i, c := range pipelineCases {
		fmt.Printf("\n%s\n#%-2d  «%s»%s\n      ▸ %s\n",
			strings.Repeat("═", 100), i+1, c.phrase, convTag(c.inConv), c.probe)
		if c.seam != "" {
			fmt.Printf("      ⚠ известный шов: %s\n", c.seam)
		}
		fmt.Println(strings.Repeat("─", 100))
		for s := 1; s <= samples; s++ {
			if samples > 1 {
				fmt.Printf("  ── проход %d ──\n", s)
			}
			ok := renderPipeline(ctx, parser, c)
			if ok {
				pass++
			} else {
				fail++
			}
		}
	}
	fmt.Printf("\n%s\n  e2e: %d ✓ / %d ✗  по %d кейсам × %d\n", strings.Repeat("═", 100), pass, fail, len(pipelineCases), samples)
	fmt.Println("  (✗ на кейсе с пометкой «известный шов» — это НАХОДКА, а не регресс: см. шов выше)")
}

func convTag(inConv bool) string {
	if inConv {
		return "  [в разговоре]"
	}
	return ""
}

// renderPipeline drives the real ParseTraced (L5 included), prints the layer-by-layer
// flow, and runs the case's auto-checks. Returns whether all checks passed.
func renderPipeline(ctx context.Context, parser *extraction.IntentParser, c pipeCase) bool {
	pc := extraction.ParseContext{InConversation: c.inConv, Affordances: c.affords}
	pt, tr, err := parser.ParseTraced(ctx, c.phrase, pc)
	if err != nil {
		fmt.Printf("    ✗ Parse: %v\n", err)
		return false
	}
	// L5 now runs INSIDE Parse (normalization stack, before L2) — the trace carries its
	// verdict, so the bench reads the real in-path emotion + state-strip, not a side call.
	emotion := tr.Emotion
	if emotion == "" {
		emotion = extraction.StateCalm
	}

	// L1 discourse — always.
	dType := tr.Discourse.Type
	if dType == "" {
		dType = "action (L1 недоступен)"
	}
	norm := strings.TrimSpace(tr.Discourse.Normalized)
	l1 := fmt.Sprintf("L1 discourse  ▸ %s", dType)
	if norm != "" && norm != c.phrase {
		l1 += fmt.Sprintf("  →норм «%s»", norm)
	}
	fmt.Println("    " + l1)

	// Routed lanes skip the deed pipeline.
	switch tr.Routed {
	case "query":
		fmt.Println("    Ls speech     · обход")
		fmt.Println("    L2..Ld        · обход (вопрос → GM отвечает, не исполняется)")
		printAction(pt, "    действие      ▸ ")
		fmt.Printf("    L5 state      ▸ %s\n", stateTag(emotion))
		return checkRoute(c, tr, pt, emotion)
	case "speech":
		fmt.Printf("    Ls speech     ▸ гейт вкл → %s\n", speechTag(tr.SpeechAct))
		fmt.Println("    L2..Ld        · обход (речь → отдельная дорожка)")
		printAction(pt, "    действие      ▸ ")
		fmt.Printf("    L5 state      ▸ %s\n", stateTag(emotion))
		return checkRoute(c, tr, pt, emotion)
	}

	// Ls gate (consulted but fell through to deeds, or not consulted).
	if tr.SpeechGate {
		fmt.Printf("    Ls speech     ▸ гейт вкл → %s (сквозь, к деяниям)\n", speechTag(tr.SpeechAct))
	} else {
		fmt.Println("    Ls speech     · обход (гейт выкл)")
	}

	// L2 segment.
	fmt.Printf("    L2 segment    ▸ %d дея(ний): %s\n", len(tr.Spans), strings.Join(tr.Spans, "  |  "))

	// per deed: roles + envelopes + L4 hand-off.
	for j, a := range pt.Actions {
		fmt.Printf("      деяние[%d] «%s»\n", j+1, spanOf(tr.Spans, j))
		fmt.Printf("        roles     ▸ %s/%s%s\n", a.Action, a.Charge, rolesTail(a))
		fmt.Printf("        L3 modal  ▸ %s\n", modalityTag(a))
		fmt.Printf("        Lc covert ▸ %s\n", covertTag(tr.CovertCue, a))
		fmt.Printf("        Lp pay    ▸ %s\n", paymentTag(a))
		fmt.Printf("        Ld dur    ▸ %s\n", emptyDash(a.Duration))
		fmt.Printf("        L4 ground → %s\n", groundQueue(a))
	}

	// L5 state — parallel channel.
	fmt.Printf("    L5 state      ▸ %s\n", stateTag(emotion))

	return checkDeeds(c, pt, emotion)
}

// ── per-layer renderers ───────────────────────────────────────────────────────

func spanOf(spans []string, j int) string {
	if j < len(spans) {
		return spans[j]
	}
	return "?"
}

func rolesTail(a extraction.ParsedPlayerAction) string {
	var b strings.Builder
	for _, r := range []struct{ k, v string }{
		{"who", a.Who}, {"where", a.Where}, {"target", a.Target}, {"instrument", a.Instrument},
		{"topic", a.Topic}, {"utterance", a.Utterance},
	} {
		if r.v != "" {
			fmt.Fprintf(&b, "  %s=%s", r.k, r.v)
		}
	}
	return b.String()
}

// modalityTag renders L3's verdict. L3 now runs on EVERY deed (no lexical gate — see
// CLAUDE.md «Никакой привязки к словам естественного языка в ядре»), so there is no
// «bypass» state: the closed enum is always the LLM's, never a Go word-list's default.
func modalityTag(a extraction.ParsedPlayerAction) string {
	m := a.Modality
	if m == "" {
		m = extraction.ModalityActual
	}
	if t := strings.TrimSpace(a.Trigger); t != "" {
		m += fmt.Sprintf(" «%s»", t)
	}
	return m
}

// covertTag mirrors Parse's manner gate: a covert probe runs iff the deed is
// acquisitive (take/give/other) OR the utterance carries a stealth cue.
func covertTag(cue bool, a extraction.ParsedPlayerAction) string {
	acquisitive := a.Action == "take" || a.Action == "give" || a.Action == "other"
	if !acquisitive && !cue {
		return "false · обход (не acquisitive, нет cue)"
	}
	if a.Covert {
		return "true"
	}
	return "false (проба прошла → открыто)"
}

func paymentTag(a extraction.ParsedPlayerAction) string {
	if a.Action != "take" && a.Action != "give" {
		return "— · обход (не take/give)"
	}
	if a.Payment == "" {
		return "даром (цена не названа)"
	}
	return a.Payment
}

func groundQueue(a extraction.ParsedPlayerAction) string {
	refs := make([]string, 0, 4)
	for _, v := range []string{a.Who, a.Where, a.Target, a.Instrument} {
		if strings.TrimSpace(v) != "" {
			refs = append(refs, v)
		}
	}
	if len(refs) == 0 {
		return "— · обход (нечего заземлять)"
	}
	return strings.Join(refs, ", ")
}

func speechTag(sa *extraction.SpeechAct) string {
	if sa == nil {
		return "deed (сквозь)"
	}
	s := sa.Kind
	if sa.Addressee != "" {
		s += "→" + sa.Addressee
	}
	if sa.Content != "" {
		s += fmt.Sprintf(" «%s»", sa.Content)
	}
	return s
}

func stateTag(emotion string) string {
	if emotion == extraction.StateCalm {
		return emotion + " · обход (явной эмоции нет)"
	}
	return emotion
}

func printAction(pt *extraction.ParsedTurn, prefix string) {
	if len(pt.Actions) == 0 {
		fmt.Println(prefix + "—")
		return
	}
	a := pt.Actions[0]
	line := a.Action
	if a.Who != "" {
		line += "  who=" + a.Who
	}
	if a.Topic != "" {
		line += "  topic=" + a.Topic
	}
	if a.Utterance != "" {
		line += fmt.Sprintf("  «%s»", a.Utterance)
	}
	fmt.Println(prefix + line)
}

func emptyDash(s string) string {
	if s == "" {
		return "—"
	}
	return s
}

// ── auto-checks ───────────────────────────────────────────────────────────────

func checkRoute(c pipeCase, tr *extraction.PerceptionTrace, pt *extraction.ParsedTurn, emotion string) bool {
	ok := true
	ok = check(&ok, "route", c.wantRoute, tr.Routed)
	if c.wantState != "" {
		ok = check(&ok, "L5", c.wantState, emotion)
	}
	_ = pt
	return finish(c, ok)
}

func checkDeeds(c pipeCase, pt *extraction.ParsedTurn, emotion string) bool {
	ok := true
	if c.wantRoute != "" {
		ok = check(&ok, "route", c.wantRoute, "(deed-lane)")
	}
	if c.wantDeeds > 0 {
		ok = check(&ok, "deeds", fmt.Sprint(c.wantDeeds), fmt.Sprint(len(pt.Actions)))
	}
	for idx, want := range c.wantMod {
		got := "actual"
		if idx < len(pt.Actions) && pt.Actions[idx].Modality != "" {
			got = pt.Actions[idx].Modality
		}
		ok = check(&ok, fmt.Sprintf("modal[%d]", idx), want, got)
	}
	if c.wantState != "" {
		ok = check(&ok, "L5", c.wantState, emotion)
	}
	return finish(c, ok)
}

func check(ok *bool, label, want, got string) bool {
	mark := "✓"
	if want != got {
		mark = "✗"
		*ok = false
	}
	fmt.Printf("        %s %s: хотим %q, есть %q\n", mark, label, want, got)
	return *ok
}

func finish(c pipeCase, ok bool) bool {
	if ok {
		fmt.Println("    ⇒ ✓ поток как ожидался")
	} else if c.seam != "" {
		fmt.Println("    ⇒ ⚠ ✗ — ожидаемый шов (находка, см. выше), не регресс")
	} else {
		fmt.Println("    ⇒ ✗ расхождение")
	}
	return ok
}

package extraction

import "testing"

// TestQueryAction confirms a player's question becomes an observe deed (answered, not
// executed) carrying the question as its topic.
func TestQueryAction(t *testing.T) {
	a := queryAction("что лежит на столе")
	if a.Action != "observe" {
		t.Errorf("query should route to observe, got %q", a.Action)
	}
	if a.Topic != "что лежит на столе" {
		t.Errorf("query text should be the topic, got %q", a.Topic)
	}
	if a.Modality != ModalityActual {
		t.Errorf("query modality should be actual, got %q", a.Modality)
	}
}

package weaver

import (
	"context"
	"fmt"
	"sort"

	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/event"
	"github.com/dnd-llm/dnd-llm/internal/domain/front"
	weaverdom "github.com/dnd-llm/dnd-llm/internal/domain/weaver"
	"go.uber.org/zap"
)

// Doom applies a fired front's authored consequence as a REAL world change — the
// play-side adapter that maps the closed catalogue (ruin_location, change_entity,
// shift_disposition) to live mechanics (habitability, the mutator, dispositions). A
// front never lands as mere prose: without a wired Doom the weaver does not raise
// fronts at all.
type Doom interface {
	Apply(ctx context.Context, worldID domain.WorldID, c front.Consequence, tick domain.Tick) error
}

// SetFronts installs the authored front defs (from the seed, resolved by
// seed.BuildFronts) — hydrated each start and reseed, like granted goals. The weaver
// reads these dormant defs and raises one into a live front when its activation fires.
func (s *Service) SetFronts(defs []*front.Def) {
	if s == nil {
		return
	}
	m := make(map[string]*front.Def, len(defs))
	for _, d := range defs {
		if d != nil && d.Key != "" {
			m[d.Key] = d
		}
	}
	s.mu.Lock()
	s.frontDefs = m
	s.mu.Unlock()
}

// foldFronts rebuilds the world's live fronts from the log, hydrated against the
// authored defs.
func (s *Service) foldFronts(ctx context.Context, worldID domain.WorldID) []*front.Front {
	s.mu.Lock()
	defs := s.frontDefs
	s.mu.Unlock()
	start := worldStartTick(ctx, s.events, worldID)
	return foldActiveFronts(ctx, s.events, worldID, start, defs)
}

// startedFrontKeys is the set of front defs already RAISED this incarnation (live or
// resolved) — so selection never re-opens a front that has run its course.
func (s *Service) startedFrontKeys(ctx context.Context, worldID domain.WorldID) map[string]bool {
	out := map[string]bool{}
	start := worldStartTick(ctx, s.events, worldID)
	crit := event.StreamCriteria{}.ForWorld(worldID).WithEventTypes(event.EventTypeFrontStarted)
	if start > 0 {
		crit.FromTick = &start
	}
	events, err := s.events.GetEventStream(ctx, crit)
	if err != nil {
		return out
	}
	for _, evt := range events {
		if d, ok := evt.Data.(event.FrontStartedEventData); ok {
			out[d.FrontKey] = true
		}
	}
	return out
}

// selectFront picks the dormant authored front to raise for the current pacing issue
// — DETERMINISTIC, no LLM. A def is a candidate when its activation matches the
// situation and it has not been raised this incarnation; among candidates the most
// player-relevant wins (a clue or its driver in the player's place), ties by key for
// stability. Returns nil when no front fits — or when no Doom adapter is wired (a
// front must be able to land a real consequence, never narrate one).
func (s *Service) selectFront(issue weaverdom.IssueType, sig *Signals, scene Scene) *front.Def {
	if s.doom == nil {
		return nil
	}
	s.mu.Lock()
	defs := s.frontDefs
	s.mu.Unlock()
	if len(defs) == 0 {
		return nil
	}
	started := s.startedFrontKeys(context.Background(), scene.WorldID)

	var best *front.Def
	bestScore := -1
	for _, key := range sortedKeys(defs) {
		def := defs[key]
		if started[def.Key] || !activationFits(def.Activation, issue, scene) {
			continue
		}
		score := frontRelevance(def, scene)
		if score > bestScore {
			best, bestScore = def, score
		}
	}
	return best
}

// activationFits reports whether a def's authored activation gate matches the current
// pacing issue and scene: "stagnation" answers a stalled player, "visit" fires when
// the player reaches the named place, "always" is open to any develop-story issue.
func activationFits(a front.Activation, issue weaverdom.IssueType, scene Scene) bool {
	switch a.Trigger {
	case "stagnation":
		return issue == weaverdom.IssueStagnation
	case "visit":
		return a.Place == scene.Location
	case "always":
		return true
	default:
		return false
	}
}

// frontRelevance scores how much THIS player should care right now: a clue (lead) or
// the driver standing in the player's current place draws them in. Deterministic.
func frontRelevance(def *front.Def, scene Scene) int {
	score := 0
	for _, l := range def.Leads {
		if l.Location == scene.Location {
			score += 2
		}
	}
	for _, a := range scene.CoLocated {
		if a.ID == def.Driver {
			score += 1
		}
	}
	return score
}

// raiseFront opens a dormant def into a live front: it journals FrontStarted (by
// key). The front then presses forward on its own each turn — its authored portents
// telegraph the coming doom and its leads pull the player toward it; engaging the
// driver or a lead defuses it. Called from execute for a KindOpenFront plan.
func (s *Service) raiseFront(ctx context.Context, plan *weaverdom.Plan, scene Scene) error {
	if plan.FrontKey == "" {
		return fmt.Errorf("open_front plan without a front key")
	}
	started := event.NewGameEvent(
		event.EventTypeFrontStarted,
		domain.ActorID(scene.WorldID), scene.Location, scene.WorldID, scene.Tick,
		event.FrontStartedEventData{FrontKey: plan.FrontKey},
	)
	if err := s.events.Append(ctx, started); err != nil {
		return fmt.Errorf("append front started: %w", err)
	}
	return nil
}

// advanceActiveFront presses the world's live front forward by one segment each turn
// — the moving world — surfacing the segment's AUTHORED portent, unless the player
// has engaged its driver (which defuses it). When the clock fills, the doom lands as
// a REAL world change plus its authored narration. Returns the player-facing prose
// for this turn's front beat, if any. Called at the start of Commit.
func (s *Service) advanceActiveFront(ctx context.Context, scene Scene) string {
	if !s.Enabled() {
		return ""
	}
	fronts := s.foldFronts(ctx, scene.WorldID)
	if len(fronts) == 0 {
		return ""
	}
	f := fronts[len(fronts)-1] // the most recently raised live front

	if s.playerEngagedFront(ctx, scene, f) {
		// Handling the front IS the investigation: the player uncovers its authored
		// truth (made common knowledge), so doing the legwork teaches them what they
		// found — not only the NPC who pursues the same thread.
		s.revealFrontDiscovery(ctx, scene, f)
		s.resolveFront(ctx, scene, f, false)
		return "" // defused — the player took the thread; no doom
	}

	// A discovered truth, now common knowledge, can dissolve a front's premise (the
	// real cause clears the scapegoat the front would otherwise doom). The suspicion
	// has no fuel once the town knows the truth, so the front defuses — no unjust doom.
	if s.frontDefusedByKnownTruth(ctx, f) {
		s.resolveFront(ctx, scene, f, false)
		return ""
	}

	// The player acts on what they learned: knowing the cause unlocks the fix. When their
	// deed is the authored remedy AND its truth is common knowledge, the front resolves
	// FAVOURABLY — the doom is averted, the world heals — and the authored prose surfaces.
	// The remedy lands its BOON as a real positive change (the mirror of fireDoom applying
	// the doom) BEFORE the front resolves, so the world actually heals, not just narrates.
	if heal := s.frontRemedy(ctx, scene, f); heal != "" {
		s.applyRemedyBoon(ctx, scene, f)
		s.resolveFront(ctx, scene, f, false)
		return heal
	}

	ripened := f.Advance(1)
	s.appendFrontAdvanced(ctx, scene, f)
	if ripened {
		return s.fireDoom(ctx, scene, f)
	}
	if portent := f.Portent(); portent != "" {
		s.appendScene(ctx, scene, portent) // telegraph the authored beat
		return portent
	}
	return ""
}

// applyRemedyBoon lands a remedy's authored BOON as a real positive world change —
// the symmetric mirror of fireDoom applying a front's doom, through the same
// consequence applier. A zero-Type Boon (the remedy only averts and narrates) or a
// nil applier is a clean no-op. A failed boon is logged, never fatal: the remedy
// still resolves the front and surfaces its narration.
func (s *Service) applyRemedyBoon(ctx context.Context, scene Scene, f *front.Front) {
	if s.doom == nil || f.Def == nil || f.Def.Remedy.Boon.Type == "" {
		return
	}
	if err := s.doom.Apply(ctx, scene.WorldID, f.Def.Remedy.Boon, scene.Tick); err != nil {
		s.logger.Warn("front remedy boon failed to apply", zap.String("front", f.Key()), zap.Error(err))
	}
}

// frontRemedy reports the healing narration when the player's deed IS the front's authored
// remedy and its truth is common knowledge — the «know the cause → act on it» half of the
// loop. Returns "" when there is no remedy, the truth is not yet known, or the deed does
// not match the remedy cue. The cheap truth check runs BEFORE the LLM cue match, so the
// classifier fires only when a remedy is actually possible (the truth is out).
func (s *Service) frontRemedy(ctx context.Context, scene Scene, f *front.Front) string {
	r := f.Def.Remedy
	if r.Cue == "" || s.cues == nil {
		return ""
	}
	if r.NeedsTruth != "" {
		if s.truth == nil {
			return ""
		}
		known, err := s.truth.IsWorldKnown(ctx, r.NeedsTruth)
		if err != nil || !known {
			return ""
		}
	}
	if !s.cues.DeedEngages(ctx, scene.PlayerDeed, []string{r.Cue}) {
		return ""
	}
	return r.Narration
}

// revealFrontDiscovery makes the front's authored Discovery truth common knowledge when
// the player defuses it — the same reveal_knowledge consequence a gather_info goal fires,
// landed through the shared doom port. No Discovery or no doom port → a no-op. Best-effort:
// a failed reveal only costs the truth's spread, never the defuse itself.
func (s *Service) revealFrontDiscovery(ctx context.Context, scene Scene, f *front.Front) {
	if f.Def.Discovery == "" || s.doom == nil {
		return
	}
	c := front.Consequence{Type: front.ConsequenceRevealKnowledge, Target: string(f.Def.Discovery)}
	if err := s.doom.Apply(ctx, scene.WorldID, c, scene.Tick); err != nil {
		s.logger.Warn("front discovery reveal failed", zap.String("front", f.Key()), zap.Error(err))
	}
}

// frontDefusedByKnownTruth reports whether the front's premise has been dissolved by a
// now-public truth (its authored DefusedBy entity became common knowledge). A read-only
// check through the narrow TruthPort; nil port or no DefusedBy → never defused this way.
// A port error is logged and treated as "not yet known" — the front keeps its course
// rather than defusing on a failed read.
func (s *Service) frontDefusedByKnownTruth(ctx context.Context, f *front.Front) bool {
	if s.truth == nil || f.Def.DefusedBy == "" {
		return false
	}
	known, err := s.truth.IsWorldKnown(ctx, f.Def.DefusedBy)
	if err != nil {
		s.logger.Warn("front truth-defuse check failed", zap.String("front", f.Key()), zap.Error(err))
		return false
	}
	return known
}

// fireDoom lands a ripened front's doom: the REAL consequence first (the world
// changes), then its authored narration to the player, then the front is resolved.
func (s *Service) fireDoom(ctx context.Context, scene Scene, f *front.Front) string {
	if f.Def == nil {
		return ""
	}
	if s.doom != nil {
		if err := s.doom.Apply(ctx, scene.WorldID, f.Def.Doom, scene.Tick); err != nil {
			s.logger.Warn("front doom failed to apply", zap.String("front", f.Key()), zap.Error(err))
		}
	}
	s.resolveFront(ctx, scene, f, true)
	if narration := f.Def.Doom.Narration; narration != "" {
		s.appendScene(ctx, scene, narration)
		return narration
	}
	return ""
}

// resolveFront closes a front (doomed or defused) — folded out of the live set next.
func (s *Service) resolveFront(ctx context.Context, scene Scene, f *front.Front, doomed bool) {
	evt := event.NewGameEvent(
		event.EventTypeFrontResolved,
		domain.ActorID(scene.WorldID), scene.Location, scene.WorldID, scene.Tick,
		event.FrontResolvedEventData{FrontKey: f.Key(), Doomed: doomed},
	)
	if err := s.events.Append(ctx, evt); err != nil {
		s.logger.Warn("front resolve append failed", zap.Error(err))
	}
}

// appendFrontAdvanced journals the clock tick (the world pressed the front forward).
func (s *Service) appendFrontAdvanced(ctx context.Context, scene Scene, f *front.Front) {
	evt := event.NewGameEvent(
		event.EventTypeFrontAdvanced,
		domain.ActorID(scene.WorldID), scene.Location, scene.WorldID, scene.Tick,
		event.FrontAdvancedEventData{FrontKey: f.Key(), Filled: f.Clock.Filled},
	)
	if err := s.events.Append(ctx, evt); err != nil {
		s.logger.Warn("front advance append failed", zap.Error(err))
	}
}

// appendScene surfaces a front beat (an authored portent or doom narration) as a
// scene event in the player's place — perceived by NPCs and shown in the player's
// feed, exactly like the weaver's other ambient happenings.
func (s *Service) appendScene(ctx context.Context, scene Scene, description string) {
	evt := event.NewGameEvent(
		event.EventTypeRandomEventTriggered,
		domain.ActorID(scene.WorldID), scene.Location, scene.WorldID, scene.Tick,
		event.RandomEventEventData{
			LocationID:  string(scene.Location),
			Description: description,
			Category:    "scene",
		},
	)
	if err := s.events.Append(ctx, evt); err != nil {
		s.logger.Warn("front scene append failed", zap.Error(err))
	}
}

// playerEngagedFront reports whether the player has taken the thread since the front
// was raised — defusing it (the doom was the price of IGNORING it). Two signals:
//   - STRUCTURED (deterministic): the player spoke with the front's driver.
//   - FUZZY (the LLM's job, not stem-matching): the player's intent THIS turn engages a
//     lead's authored cue at the place they stand (investigating the clue — the
//     three-clue pull made functional).
//
// The fuzzy signal reads the player's RAW MESSAGE (scene.PlayerDeed), not the deed log:
// the message is the authoritative record of what the player is doing, and an
// investigation may leave no event trace at all (an observe is read-only). Location
// gates hard (a deterministic place match); whether the free-form intent MEANS the cue
// is unstructured perception, so the LLM decides under a dynamic enum.
func (s *Service) playerEngagedFront(ctx context.Context, scene Scene, f *front.Front) bool {
	if f.Def == nil {
		return false
	}
	if s.spokeWithDriver(ctx, scene, f) {
		return true
	}
	// Membership first: if the player grounded a reference to a lead's authored
	// subject, they engaged it DETERMINISTICALLY — the grounding is the signal, no
	// model call. Leads not matched by membership (subjectless, or a subject the
	// player did not name) fall back to the fuzzy cue classifier.
	var cues []string
	for _, l := range f.Def.Leads {
		if l.Location != scene.Location {
			continue
		}
		if scene.mentioned(string(l.Subject)) {
			return true
		}
		cues = append(cues, l.Cue)
	}
	return len(cues) > 0 && s.cues.DeedEngages(ctx, scene.PlayerDeed, cues)
}

// spokeWithDriver reports whether the player has talked with the front's driver since it
// opened — a structured, deterministic engagement signal (no LLM): going to the person
// at the heart of the situation takes its thread.
func (s *Service) spokeWithDriver(ctx context.Context, scene Scene, f *front.Front) bool {
	driver := f.Def.Driver
	if driver == "" {
		return false
	}
	from := f.Opened
	crit := event.StreamCriteria{}.ForWorld(scene.WorldID).WithEventTypes(event.EventTypeDialogueLine)
	crit.FromTick = &from
	events, err := s.events.GetEventStream(ctx, crit)
	if err != nil {
		return false
	}
	for _, evt := range events {
		d, ok := evt.Data.(event.DialogueEventData)
		if !ok {
			continue
		}
		if (d.SpeakerID == scene.PlayerID && contains(d.ListenerIDs, driver)) ||
			(d.SpeakerID == driver && contains(d.ListenerIDs, scene.PlayerID)) {
			return true
		}
	}
	return false
}

func contains(ids []domain.ActorID, id domain.ActorID) bool {
	for _, x := range ids {
		if x == id {
			return true
		}
	}
	return false
}

// sortedKeys returns the def keys in a stable order (deterministic selection ties).
func sortedKeys(defs map[string]*front.Def) []string {
	keys := make([]string, 0, len(defs))
	for k := range defs {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// Package front models STORY FRONTS — the GM-craft answer (Apocalypse / Dungeon
// World) to a static world. A front is a developing SITUATION with its own
// momentum: a scheme, a threat, a brewing event that ADVANCES on a clock whether or
// not the player acts, and faster when they ignore it. As the clock fills, ordered
// PORTENTS foreshadow what is coming (telegraphing); LEADS are the redundant clues
// that point the player toward it (the three-clue rule). When the clock fills, the
// front's DOOM lands — a committed consequence in the world.
//
// The domain here is pure mechanics (a clock, its portents, its doom): the weaver
// decides WHEN to advance and HOW to surface a front, the LLM authors the prose of
// situation/portents/doom, and the consequence is committed by the core. Fronts
// persist by event-sourcing (FrontStarted/Advanced/Resolved folded from the log),
// like the weaver's arc — no state table, replay-safe.
package front

import "github.com/dnd-llm/dnd-llm/internal/domain"

// FrontID identifies a front across its lifetime of events.
type FrontID string

// ConsequenceType is the CLOSED catalogue of a front's possible dooms — each maps
// to a REAL world mechanic, so a doom is a true state change, not prose on a timer.
// The author (prep phase) picks one; the weaver applies it deterministically (play
// phase). Grow the catalogue by adding a row backed by an existing mechanic.
type ConsequenceType string

const (
	// ConsequenceRuinLocation destroys a location's load-bearing structure, so the
	// place becomes uninhabitable (the habitability mechanic) — a ford that closes,
	// a hall that falls. Target is a location.
	ConsequenceRuinLocation ConsequenceType = "ruin_location"
	// ConsequenceChangeEntity drives an entity through a catalogue effect (the
	// mutator) — a thing breaks, spoils, vanishes. Target is an entity, Detail an
	// effect key.
	ConsequenceChangeEntity ConsequenceType = "change_entity"
	// ConsequenceShiftDisposition turns an NPC's feeling toward the player (fear,
	// anger, affection). Target is an NPC, Detail the signed shift.
	ConsequenceShiftDisposition ConsequenceType = "shift_disposition"
	// ConsequenceShiftTownDisposition turns the WHOLE town's feeling toward one NPC —
	// suspicion or gratitude spreading (a scapegoat shunned, a hero embraced). The
	// NPC↔NPC counterpart, for outcomes that are between townsfolk, not toward the
	// player. Target is the NPC the town turns on, Detail the signed shift.
	ConsequenceShiftTownDisposition ConsequenceType = "shift_town_disposition"
	// ConsequenceRevealKnowledge makes an authored truth become KNOWN — the EPISTEMIC
	// outcome the catalogue lacked: not a thing changing or a feeling souring, but a
	// fact entering the world's knowledge. Target is a lore entity (the authored
	// answer, born unknown — in nobody's scope until revealed); applying it grants a
	// world-knows link, so the truth becomes common knowledge that surfaces in every
	// NPC's prompt and the player can learn by asking (the same mechanism as a
	// city_wide seed entity). This is what lets an investigate/gather_info goal — or a
	// player's lead — produce a REAL discovery (a knowledge edge in the graph) instead
	// of a counter ticking to nothing. Detail is unused.
	ConsequenceRevealKnowledge ConsequenceType = "reveal_knowledge"
	// ConsequenceRestoreLocation MENDS a location's ruined load-bearing structure, so
	// the place becomes habitable again (the habitability mechanic reopens it) — the
	// deliberate INVERSE of ruin_location, and the catalogue's first BOON: a real
	// positive change, not the mere absence of a doom. It is what a front's remedy
	// lands when the player acts on a discovered truth (clears the channel, and the
	// frozen-shut ford reopens). Target is a location. Idempotent / best-effort: a
	// location not yet ruined is left as-is (the remedy still resolves favourably).
	ConsequenceRestoreLocation ConsequenceType = "restore_location"
)

// Consequence is a front's doom: a real mechanical outcome plus its narration. The
// narration is PREP-authored prose (like a seed entity's gist) — the play-phase LLM
// may surface or recolour it, but the OUTCOME is the deterministic state change.
type Consequence struct {
	Type      ConsequenceType
	Target    string // resolved id (location/entity/npc) the doom lands on
	Detail    string // type-specific param (an effect key, a disposition delta)
	Narration string // authored prose of the doom landing
}

// Lead is one clue pointing the player at a front — a deed (cue) at a place. Authored
// redundantly (the three-clue rule) so a missed clue does not dead-end the thread;
// engaging one progresses or defuses the front.
type Lead struct {
	Location domain.LocationID
	Cue      string // the deed/theme that engages this lead
	// Subject is the authored ENTITY this lead is about (the river, the bell, the
	// docks). When the player's turn grounds a reference to it, the lead engages
	// DETERMINISTICALLY by membership — the grounding the parser already did is the
	// signal, no fuzzy cue call. Empty when the lead has no concrete subject to ground
	// (a pure act with no nameable object); those keep the cue classifier.
	Subject domain.EntityID
}

// Activation says WHEN a dormant authored front may be raised by the weaver: on
// player stagnation, on visiting a place, always-eligible, etc. The weaver still
// picks among the eligible by relevance — this only gates candidacy.
type Activation struct {
	Trigger string            // closed: "stagnation" | "visit" | "always" | ...
	Place   domain.LocationID // for "visit": where
}

// Def is an AUTHORED front — prep content from the seed (like an entity or an NPC),
// not runtime-generated. It carries the developing situation, its driver NPC, the
// foreshadowing portents, the redundant leads, the real-consequence doom and the
// activation gate. The weaver hydrates these dormant defs each start and raises one
// into a live Front when its activation fires and relevance selects it.
type Def struct {
	Key        string
	Situation  string
	Driver     domain.ActorID
	Portents   []string
	Leads      []Lead
	Doom       Consequence
	Activation Activation
	// DefusedBy is an optional lore entity whose PUBLIC knowledge dissolves this
	// front's premise — a discovered truth that undercuts the situation (the real
	// cause of a crisis clears the scapegoat the front would otherwise doom). When
	// that entity becomes common knowledge, the front resolves as defused instead of
	// firing its doom: the suspicion has no fuel once the town knows the truth. Empty
	// for fronts no discovery can defuse.
	DefusedBy domain.EntityID
	// Discovery is an optional lore entity the player UNCOVERS by handling this front —
	// the truth their own investigation brings to light. When the player defuses the
	// front (engaging its driver or a lead), this entity is revealed (made common
	// knowledge, the same reveal_knowledge a gather_info goal fires), so the player who
	// does the legwork learns what they found, not only the NPC who pursues it. Empty
	// for fronts that surface no authored truth. (DefusedBy is the mirror: a truth that
	// dissolves the front; Discovery is a truth the front's resolution brings to light.)
	Discovery domain.EntityID
	// Remedy is the authored RESOLVING ACTION a discovered truth unlocks: knowing the
	// cause is half the loop, ACTING on it is the other half. When the player does the
	// remedy action (their deed engages Remedy.Cue) AND its NeedsTruth is common
	// knowledge, the front resolves FAVOURABLY — averting the doom, the real healing
	// change — and surfaces the authored narration. Empty Cue → no remedy (the front
	// can only be defused or doomed). This closes «расследуй → узнай → почини».
	Remedy Remedy
}

// Remedy is a front's authored resolving action — the player's hands-on fix once they
// know the truth. Cue is the deed that triggers it (matched by the same classifier as a
// lead); NeedsTruth is the discovery that must already be common knowledge to attempt it;
// Narration is the authored prose of the world healing; Boon is the real positive change
// the fix lands (the symmetric mirror of the front's Doom — restore a ruined ford, revive
// a stilled thing). A zero-Type Boon means the remedy only averts the doom and narrates,
// landing no positive change of its own (the pre-boon behaviour).
type Remedy struct {
	Cue        string
	NeedsTruth domain.EntityID
	Narration  string
	Boon       Consequence
}

// ClockSize is how many segments a def's clock holds: one per portent, then the
// doom. A front with no authored portents still gets a two-beat clock (a warning,
// then the blow).
func (d Def) ClockSize() int {
	if n := len(d.Portents) + 1; n >= 2 {
		return n
	}
	return 2
}

// Clock measures how close a front's doom is: Filled of Size segments. A fresh
// front starts at 0; the doom is due at Size.
type Clock struct {
	Filled int
	Size   int
}

// Ripe reports whether the clock has filled — the doom is now due.
func (c Clock) Ripe() bool { return c.Size > 0 && c.Filled >= c.Size }

// Fraction is how full the clock is, 0..1 (0 for an unsized clock) — the pressure
// the weaver reads to pick a rung of the surfacing ladder (telegraph → pull → push).
func (c Clock) Fraction() float64 {
	if c.Size <= 0 {
		return 0
	}
	f := float64(c.Filled) / float64(c.Size)
	if f > 1 {
		return 1
	}
	return f
}

// Front is a LIVE instance of an authored Def: the def's content (situation,
// portents, leads, doom, driver) plus the runtime clock the weaver advances and the
// flags it folds from the event log. The Def is the single source of the front's
// story; the runtime only tracks how far it has pressed forward.
type Front struct {
	Def      *Def
	Clock    Clock
	Opened   domain.Tick // the tick it was raised (for engagement scanning)
	Resolved bool
}

// Key is the front's identity — its def's key (one live instance per def).
func (f *Front) Key() string {
	if f.Def == nil {
		return ""
	}
	return f.Def.Key
}

// Advance fills the clock by `step` segments (negative/zero is a no-op), clamped to
// the size, and reports whether it JUST ripened — the moment the doom becomes due.
// A resolved or already-ripe front does not advance.
func (f *Front) Advance(step int) (ripened bool) {
	if f.Resolved || step <= 0 || f.Clock.Ripe() {
		return false
	}
	f.Clock.Filled += step
	if f.Clock.Filled > f.Clock.Size {
		f.Clock.Filled = f.Clock.Size
	}
	return f.Clock.Ripe()
}

// Portent returns the authored foreshadowing beat for the CURRENT clock position —
// the telegraph for the segment most recently filled (Def.Portents[Filled-1]). Empty
// when the clock is fresh or no beat was authored for this step; the final fill
// speaks through the doom, not a portent.
func (f *Front) Portent() string {
	if f.Def == nil {
		return ""
	}
	i := f.Clock.Filled - 1
	if i < 0 || i >= len(f.Def.Portents) {
		return ""
	}
	return f.Def.Portents[i]
}

