func runGround(ctx context.Context, p infrallm.SchemaCompleter, samples int) {
	for i, c := range groundCases {
		fmt.Printf("\n%s\n#%-2d хотим [%s]\n   упоминание: «%s»\n%s\n",
			strings.Repeat("═", 90), i+1, c.want, c.reference, strings.Repeat("─", 90))
		for s := 1; s <= samples; s++ {
			got, err := groundReference(ctx, p, c.reference, c.candidates)
			if err != nil {
