// ── L1 cases: discourse type + revision normalization ────────────────────────

type discourseCase struct {
	utterance, wantType, note string // note = что ждём в normalized (глазами)
}

var discourseCases = []discourseCase{
	{"бью стражника и отступаю к стене", "action", "без изменений"},
	{"иду к двери... нет, сначала гашу свечу", "action", "гашу свечу, потом иду к двери"},
	{"достаю меч, хотя нет, оставляю его в ножнах", "action", "оставляю меч в ножнах"},
	{"стреляю в орка, нет, сперва прячусь за щит", "action", "сперва прячусь за щит, потом стреляю в орка"},
	{"что лежит на этом столе?", "query", "вопрос"},
	{"кто эти люди у костра?", "query", "вопрос"},
	{"сколько у меня осталось золота?", "query", "вопрос (мета)"},
	{"осматриваю комнату и иду к сундуку", "action", "без изменений"},
	// Вопрос, ОБРАЩЁННЫЙ К ПЕРСОНАЖУ, — это разговор (action), не мета-query к ГМ.
	{"спрашиваю кузнеца, откуда на реке огни", "action", "вопрос к NPC = разговор"},
	{"спросить у привратника, кто заходил ночью", "action", "вопрос к NPC = действие"},
	{"подхожу к торговке и спрашиваю про её товар", "action", "обращение к NPC = действие"},
}

func runDiscourse(ctx context.Context, p infrallm.SchemaCompleter, samples int) {
	for i, c := range discourseCases {
		fmt.Printf("\n%s\n#%-2d хотим [%s] — %s\n   «%s»\n%s\n",
			strings.Repeat("═", 90), i+1, c.wantType, c.note, c.utterance, strings.Repeat("─", 90))
		for s := 1; s <= samples; s++ {
			d, err := extraction.NormalizeDiscourse(ctx, p, c.utterance)
			if err != nil {
				fmt.Printf("  ⃟%d ✗ %v\n", s, err)
				continue
			}
			mark := "✓"
			if d.Type != c.wantType {
				mark = "✗"
			}
			fmt.Printf("  ⃟%d  [%s] %s  «%s»\n", s, d.Type, mark, d.Normalized)
		}
	}
}

// ── L5 cases: explicit emotional state ────────────────────────────────────────

// stateCase tests L5's TWO focused passes: DetectState (emotion enum) AND StripState (the
// state-strip). normHas = a deed substring the remainder MUST keep (no deed lost); normNot =
// a state substring it MUST drop (state peeled). Either may be empty to skip. State-ONLY
// utterances expect an empty remainder (deedless), so normHas stays empty and normNot checks
// the strip.
type stateCase struct {
	utterance, want string
	normHas, normNot string
}

var stateCases = []stateCase{
	{"прихожу в ярость и переворачиваю стол", "гнев", "переворачиваю", "ярость"},
	{"в ужасе застываю, не в силах шевельнуться", "страх", "", "ужас"}, // state-only → remainder deedless
	{"со слезами радости обнимаю брата", "радость", "обнимаю", "слез"},
	{"с отвращением отшатываюсь от трупа", "отвращение", "", "отвращени"},
	{"в горе оседаю на колени у могилы", "печаль", "", "горе"},
	{"ошеломлённый, не верю своим глазам", "удивление", "", "ошеломл"},
