package main

import (
	"context"
	"fmt"
	"os"
	"strings"

	"github.com/dnd-llm/dnd-llm/internal/application/knowledge"
	appllm "github.com/dnd-llm/dnd-llm/internal/application/llm"
	llm "github.com/dnd-llm/dnd-llm/internal/infrastructure/llm"
)

var stderrDbg = os.Stderr

// Probe for the facts-first narrator (appllm.NarrateFacts): the renderer
// receives ALREADY-COMMITTED outcomes from the verdict engine and must
// describe exactly them — never cancel, soften or invent a different ending.
// This replaced the old sensor-narrator probe: the sensor work (used/target/
// charge) moved upstream into the intent parser, and the narrator's whole
// quality bar is now fidelity to the given facts.

// narrFactsCase is one deed + verdict facts with graded expectations.
type narrFactsCase struct {
	name     string
	in       appllm.NarrateFactsInput
	wantText []string // substrings («|»-alternates) the prose must touch
	denyText []string // substrings that mark the prose contradicting the facts
}

var narrFactsCases = []narrFactsCase{
	{
		// Состоявшийся поджог: проза обязана гореть, а не гладить стулья
		// (живой баг O: «касаешься стула, слышишь сухой звук»).
		name: "fire-success",
		in: appllm.NarrateFactsInput{
			Deed: "поджечь стол факелом",
			Facts: []string{
				"Огонь занялся: сухое дерево стола загорается.",
				"Свидетели в панике отшатываются.",
			},
			LocationName: "Лунный Брод",
			LocationDesc: "Бревенчатая таверна на сваях; сухое старое дерево, промасленные столы.",
			TimeOfDay:    "вечер",
			Witnesses:    []string{"Мирра Соль", "Старый Гром"},
			Scene:        &knowledge.Scene{},
		},
		wantText: []string{"огонь|плам|загор|вспых|жар|гор"},
		denyText: []string{"не загор|не вспых|ничего не выходит|касаешься стула"},
	},
	{
		// Честный отказ: средства нет — проза показывает, КАК не вышло, и не
		// дарит игроку успех (стоп-словарь поджога).
		name: "fire-impotent",
		in: appllm.NarrateFactsInput{
			Deed: "поджечь таверну",
			Facts: []string{
				"Поджечь нечем: при тебе нет ни огня, ни огнива.",
			},
			LocationName: "Лунный Брод",
			LocationDesc: "Бревенчатая таверна на сваях; сухое старое дерево.",
			TimeOfDay:    "вечер",
			Witnesses:    []string{"Мирра Соль"},
			Scene:        &knowledge.Scene{},
		},
		wantText: []string{"нечем|нет огня|ни огня|без огня|пуст"},
			// ASSERTIVE success markers only — a bare «вспыхивает»/«загорается» also matches the
			// CORRECT negation («ничто не вспыхивает»), so the substring grader falsely failed a
			// faithful impotent narration. Mirror of the empty-scene fix: catch fire that actually
			// TOOK HOLD (subject-bound / phrase), not a verb that lives in negation too.
