// ============================================================================
// narrator/location-dormant — NarrationService.GenerateLocationDescription
// ============================================================================
//
// DORMANT PATH (owner decision 2026-06-19): this prompt is NOT wired into the
// player-driven runtime — LocationService.GenerateDescription, its only caller,
// has zero call-sites, and the live scene is narrated by the facts-first narrator
// (NarrateFacts). It is kept, NOT deleted, because on-the-fly location generation
// is a likely future need; benching it now means the path is measured BEFORE it is
// wired. The probe name carries «dormant» so a reader knows this is a preserved-
// but-unused frame. Drives the exact production call (gateway → NarrationService →
// buildLocationSystemPrompt + Complete).
//
// MEASURED STATE (Gemma 4 E4B, 2026-06-19): this path is BROKEN as-is. The prompt
// goes through gateway.Complete with NO grammar/schema, and the small model defaults
// to a markdown-fenced JSON OBJECT («```json\n{"описание_места": …}»), not the
// 2–3-sentence prose the prompt asks for; formatNarration strips only quotes, so a
// player would see raw JSON. So the grade GATES on shape first: anything fenced or
// JSON-shaped scores 0 (it is not prose), regardless of grounding. Direction when
// wired: constrain to a single grammar-bound prose-string schema (the project's
// standard for model output), as the live narrator already does — do NOT free-Complete
// on 4B. Held-out places; the prose checks below only apply once the shape is prose.

type locationCase struct {
	name    string
	details string
	style   appllm.NarrationStyle
	anchors []string // each group («|»-alternates) the prose should touch (grounding)
}

var locationCases = []locationCase{
	{
		name:    "Затопленная крипта",
		details: "Подземелье под часовней: вода стоит по колено, каменные саркофаги уходят в темноту, эхо капель.",
		style:   appllm.StyleNeutral,
		anchors: []string{"вод|сыр|затопл|кап", "камен|саркофаг|гроб|крипт|склеп"},
	},
	{
		name:    "Сторожевая башня на утёсе",
		details: "Полуразрушенная башня над морем: ветер свистит в выщербленных бойницах, винтовая лестница осыпается.",
		style:   appllm.StyleDark,
		anchors: []string{"башн|утёс|утес|мор|ветер", "лестниц|бойниц|камн|развал|руин"},
	},
	{
		name:    "Грибная пещера",
		details: "Влажный грот, где со стен свисают светящиеся грибы, бросая голубоватый свет на мокрый камень.",
		style:   appllm.StyleMystery,
		anchors: []string{"гриб|грот|пещер", "свет|голуб|сия|мерца|влаж|мокр"},
	},
}

func locationDormantProbe() Probe {
	cases := locationCases
	return Probe{
		Name:     "narrator/location-dormant",
		Category: "quality",
		Reps:     len(cases) * 2, // each place twice — narration runs warm
		Run: func(ctx context.Context, p *llm.VLLMProvider, rep int) Outcome {
			tc := cases[rep%len(cases)]

			// Build the production stack over the bare provider: gateway →
			// NarrationService, so the exact buildLocationSystemPrompt + Complete
			// path runs (no prompt duplication in the bench).
			gw := llm.NewLLMGateway(map[string]llm.LLMProvider{"primary": p}, llm.WithPrimary("primary"))
			ns := appllm.NewNarrationService(gw)

			desc, err := ns.GenerateLocationDescription(ctx, &appllm.LocationInfo{
				Name:        tc.name,
				Description: tc.details,
			}, tc.style)
			if err != nil {
				return failFrame(nil, "location %s: %v", tc.name, err)
			}
			if strings.TrimSpace(desc) == "" {
				return failFrame(nil, "empty location description")
			}

			out := Outcome{Resp: nil, Pass: true, HasQuality: true, Fields: map[string]string{
				"place":       tc.name,
				"description": desc,
			}}

			// SHAPE GATE (first): the result must be PLAIN PROSE. A code fence or a
			// JSON object means the un-grammar'd Complete fell into structured output
			// (the live failure on 4B) — that is a total miss for a narration path,
			// graded 0 regardless of what the JSON happens to contain.
			trimmed := strings.TrimSpace(desc)
			if strings.Contains(desc, "```") || strings.HasPrefix(trimmed, "{") || strings.Contains(desc, "\":") {
				out.Issues = append(out.Issues, "not prose: markdown-fenced/JSON output, not a description")
				out.Quality = 0
				return out
			}

			low := strings.ToLower(desc)
			score := 0.0
			// Grounding: each anchor group should surface (the prose stays about
			// THIS place, not a generic invention).
			per := 0.6 / float64(len(tc.anchors))
			for _, group := range tc.anchors {
				if containsAny(low, group) {
					score += per
				} else {
					out.Issues = append(out.Issues, "grounding anchor missing: "+group)
				}
			}
			// Length: the prompt asks 2–3 sentences — neither a one-liner nor a wall.
			words := len(strings.Fields(desc))
			if words >= 10 && words <= 90 {
				score += 0.4
			} else {
				out.Issues = append(out.Issues, fmt.Sprintf("length %d words (want ~10–90)", words))
			}

			out.Quality = score
			return out
		},
	}
}

func narratorFactsProbe() Probe {
	cases := narrFactsCases
	if iso := os.Getenv("ISO_CASE"); iso != "" { // TEMP MEASUREMENT: isolate one case at high N
		for _, c := range narrFactsCases {
			if c.name == iso {
				if os.Getenv("GENDER_NOPIN") != "" {
					c.in.Genders = nil // baseline: no gender pin
				}
				cases = []narrFactsCase{c}
			}
		}
	}
	reps := len(cases) * 2
	if os.Getenv("ISO_CASE") != "" {
		reps = 30
	}
	return Probe{
		Name:     "narrator/facts",
		Category: "quality",
		Reps:     reps, // T=0.8 — каждый кейс дважды
		Run: func(ctx context.Context, p *llm.VLLMProvider, rep int) Outcome {
			tc := cases[rep%len(cases)]

			narrative, resp, err := appllm.NarrateFacts(ctx, p, tc.in)
			if err != nil {
				return failFrame(resp, "narrate facts %s: %v", tc.name, err)
			}

			out := Outcome{Resp: resp, Pass: true, HasQuality: true, Fields: map[string]string{
				"case":      tc.name,
				"narrative": narrative,
			}}

			low := strings.ToLower(narrative)
			score := 1.0
			for _, deny := range tc.denyText {
				if containsAny(low, strings.ToLower(deny)) {
					score = 0
					out.Issues = append(out.Issues, tc.name+": contradicts the facts: "+deny)
				}
			}
			for _, want := range tc.wantText {
				if !containsAny(low, strings.ToLower(want)) {
					score -= 0.5
					out.Issues = append(out.Issues, tc.name+": expected anchor missing: "+want)
				}
			}
			if len([]rune(strings.TrimSpace(narrative))) < 40 {
				score = 0
				out.Issues = append(out.Issues, "narration too short")
			}
			if score < 0 {
				score = 0
			}
			out.Quality = score
			if os.Getenv("DBG_NARR") != "" { // per-case dump for measurement runs
				fmt.Fprintf(stderrDbg, "DBG case=%-26s q=%.2f | %s\n", tc.name, score, strings.ReplaceAll(narrative, "\n", " "))
			}
			return out
		},
	}
}

package player

import (
	"testing"

	"github.com/dnd-llm/dnd-llm/internal/domain/actor"
)

// The conscience channel is what makes a deed reshape its DOER (identity = the integral of
// deeds), not just how others regard them. These pin the moral valence: cruelty breeds guilt,
// kindness pride, a neutral act nothing — keyed on the CLASS of deed, never a particular one.
func TestConscienceReaction(t *testing.T) {
	cases := []struct {
		name        string
		v           *verdict
		wantFeeling actor.EmotionType
		wantOk      bool
	}{
		{"an assault leaves guilt", &verdict{kind: verdictAssault}, actor.EmotionGuilt, true},
		{"hostile destruction leaves guilt", &verdict{kind: verdictTransform, hostile: true}, actor.EmotionGuilt, true},
		{"kindness leaves pride", &verdict{kind: verdictKindness}, actor.EmotionPride, true},
		{"a NON-hostile transform leaves no mark", &verdict{kind: verdictTransform, hostile: false}, "", false},
		{"a plain deed leaves no mark", &verdict{kind: verdictPlain}, "", false},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			feeling, fact, ok := conscienceReaction(c.v)
			if ok != c.wantOk || feeling != c.wantFeeling {
				t.Errorf("conscienceReaction = (%q, ok=%v), want (%q, ok=%v)", feeling, ok, c.wantFeeling, c.wantOk)
			}
			if ok && fact == "" {
				t.Error("a deed with moral weight must carry an inner-recoil fact for the narrator")
			}
			if !ok && fact != "" {
				t.Error("a morally neutral deed must carry no fact")
			}
		})
	}
}

// The integral hardens the doer: each prior deed of the same valence dulls the next one's
// sting, and enough of them tip the doer past feeling into numbness. These pin the curve.
func TestConscienceIntensity_Hardens(t *testing.T) {
	first := conscienceIntensity(0)
	if first != conscienceFloor {
		t.Errorf("a first deed must sting fully: %.2f, want %.2f", first, conscienceFloor)
	}
	// Strictly diminishing with accumulated same-valence deeds.
	prev := first
	for n := 1; n <= 20; n++ {
		got := conscienceIntensity(n)
		if got >= prev {
			t.Errorf("deed #%d must sting less than #%d: %.3f vs %.3f", n, n-1, got, prev)
		}
		prev = got
	}
	// A negative count is floored to "first deed", never amplified.
	if conscienceIntensity(-5) != first {
		t.Error("a negative prior count must read as the first deed")
	}
	// Enough cruelty tips past numbness (the descent the narration reports).
	if hardened := conscienceIntensity(20); hardened >= numbnessFloor {
		t.Errorf("a long history of cruelty must dull past numbness: %.3f must be < %.2f", hardened, numbnessFloor)
	}
}

// The integral becomes a NAME at a threshold: the deed that tips the standing across it names
// the turning point, exactly once. These pin the crossing logic (before vs after).
func TestIdentityCrossingBeat(t *testing.T) {
	// Tipping INTO dread (a cruel deed drops the standing to the dark threshold) names it.
	if identityCrossingBeat(darkThreshold+1, darkThreshold) == "" {
		t.Error("tipping across the dark threshold must name the turning point")
	}
	// A deed wholly PAST the threshold does not re-announce (the crossing fired earlier).
	if identityCrossingBeat(darkThreshold-1, darkThreshold-2) != "" {
		t.Error("a deed already past the dark threshold must stay silent")
	}
	// Tipping INTO trust names it too.
	if identityCrossingBeat(lightThreshold-1, lightThreshold) == "" {
		t.Error("tipping across the light threshold must name the turning point")
	}
	// A deed within the neutral band crosses nothing.
	if identityCrossingBeat(0, -1) != "" {
		t.Error("a deed within the neutral band must be silent")
	}
	// Becoming feared and becoming trusted read distinctly.
	if identityCrossingBeat(darkThreshold+1, darkThreshold) == identityCrossingBeat(lightThreshold-1, lightThreshold) {
		t.Error("the two turning points must read differently")
	}
}

