package turn

import (
	"fmt"
	"strings"

	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/event"
	goaldom "github.com/dnd-llm/dnd-llm/internal/domain/goal"
)

// describeForMemory renders a game event into a short, first-person-aware memory
// description from the perspective of ownerID. A memory's content is what makes
// it useful for recall and dialogue grounding, so we capture the substance of
// what was said or done — not a bare verb like "observed". Весь текст — на
// русском (язык игрока и есть рабочий язык модели); глаголы в настоящем
// времени, чтобы не зависеть от пола персонажа.
func describeForMemory(evt *event.GameEvent, ownerID domain.ActorID, nameOf func(domain.ActorID) string) string {
	switch data := evt.Data.(type) {
	case event.DialogueEventData:
		line := strings.TrimSpace(data.Text)
		if data.SpeakerID == ownerID {
			return fmt.Sprintf("Я говорю: %q", line)
		}
		return fmt.Sprintf("%s говорит: %q", nameOf(data.SpeakerID), line)

	case event.NPCActionEventData:
		// Reason стоит в событии для отладки, но это reasoning-метаголос LLM
		// («поскольку моя цель — …») — в content памяти он не попадает НИКОГДА:
		// оттуда он тёк в диалоговые промпты и слухи. Память пишет ядро, и
		// пишет только факт — что сделано.
		if data.ActorID == ownerID {
			return fmt.Sprintf("Я %s", actionPhrase(data.ActionType, personFirst))
		}
		return fmt.Sprintf("%s %s", nameOf(data.ActorID), actionPhrase(data.ActionType, personThird))

	case event.GoalProgressEventData:
		// Детерминированный шаблон вместо LLM-наррации прогресса: конкретный
		// сдвиг с процентом, чтобы recall двигал NPC дальше, а не топтался.
		return fmt.Sprintf("Есть заметный сдвиг к тому, чтобы %s — позади уже около %d%% пути.",
			aimPhraseForType(goaldom.GoalType(data.GoalType)), int(data.Progress*100))

	case event.GoalAchievedEventData:
		// «удалось» — безличная форма: не требует согласования по роду.
		return fmt.Sprintf("Дело сделано: мне наконец удалось %s.",
			aimPhraseForType(goaldom.GoalType(data.GoalType)))

	case event.RumorHeardEventData:
		rumor := strings.TrimSpace(data.Rumor)
		return fmt.Sprintf("Услышано от %s: %q", nameOf(data.SourceID), rumor)

	case event.PlayerActionEventData:
		// Description по контракту — инфинитивная фраза (нормализует парсер
		// интентов), поэтому «пытаюсь/пытается + инфинитив» грамматически
		// корректно для любого лица и пола. Код не спрягает — только LLM.
		deed := strings.TrimSpace(data.Description)
		if data.ActorID == ownerID {
			return fmt.Sprintf("Я пытаюсь %s", deed)
		}
		return fmt.Sprintf("%s пытается %s", nameOf(data.ActorID), deed)

	case event.RandomEventEventData:
		// Готовая проза происшествия — verbatim, как и реплики.
		if d := strings.TrimSpace(data.Description); d != "" {
			return d
		}

	case event.ObservationEventData:
		if d := strings.TrimSpace(data.Description); d != "" {
			return d
		}
	}

	// Fallback: a humanised actor + event-type phrase, so even unmodelled events
	// leave a legible trace.
	who := "Я"
	if evt.ActorID != ownerID {
		who = nameOf(evt.ActorID)
	}
	return strings.TrimSpace(fmt.Sprintf("%s: %s", who, humanizeEventType(evt.Type)))
}

// grammatical person for actionPhrase: русские глаголы спрягаются по лицам, и
// механически вывести одну форму из другой нельзя — поэтому лексикон хранит обе
// (плюс инфинитив для меню и нуджей).
type actionPerson int

const (
	personFirst actionPerson = iota // «я наблюдаю за обстановкой»
	personThird                     // «Кветка наблюдает за обстановкой»
	personInf                       // «наблюдать за обстановкой»
)

// actionForms holds the three grammatical renderings of one action.
type actionForms struct {
	first string
	third string
	inf   string
}

// actionLexicon maps action menu IDs to their Russian renderings. Present tense
// keeps every form gender-neutral. The fallback for unknown IDs is the raw
// snake_case turned into words — visible, so a missing entry gets noticed.
var actionLexicon = map[string]actionForms{
	"wait":                  {"выжидаю", "выжидает", "выжидать"},
	"observe":               {"наблюдаю за обстановкой", "наблюдает за обстановкой", "наблюдать за обстановкой"},
