// actionPhrase renders an action ID as a Russian verb phrase in the requested
// grammatical person.
func actionPhrase(actionType string, person actionPerson) string {
	forms, ok := actionLexicon[actionType]
	if !ok {
		if actionType == "" {
			actionType = "что-то делаю"
		}
		return strings.ReplaceAll(actionType, "_", " ")
	}
	switch person {
	case personFirst:
		return forms.first
	case personThird:
		return forms.third
	default:
		return forms.inf
	}
}

// humanizeEventType renders an event type as a short readable phrase.
func humanizeEventType(t event.EventType) string {
	if ru, ok := eventTypesRu[t]; ok {
		return ru
	}
	return strings.ReplaceAll(string(t), "_", " ")
}

