package turn

import (
	"context"

	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/actor"
	"github.com/dnd-llm/dnd-llm/internal/domain/event"
	"github.com/dnd-llm/dnd-llm/internal/domain/memory"
	"go.uber.org/zap"
)

// emotionEventThreshold is the dominant-emotion intensity above which a
// perception emits an EmotionChanged event (gate against per-tick spam).
const emotionEventThreshold = 0.4

// processPerception lets NPCs react to what happened on the previous tick:
// co-located or directed events update their emotions (via the BehaviorSystem +
// EmotionHelper) and, when a MemoryService is wired, form memories. Runs first
// in the tick so updated emotions feed this tick's decisions.
//
// Returns EmotionChanged events and the set of actors whose state changed.
func (p *TickProcessor) processPerception(
	ctx context.Context,
	worldID domain.WorldID,
	gameTime domain.GameTime,
	byID map[domain.ActorID]*actor.Actor,
) ([]*event.GameEvent, map[domain.ActorID]bool) {
	dirty := make(map[domain.ActorID]bool)
	if p.eventStore == nil || gameTime.Tick == 0 {
		return nil, dirty
	}

	prev := gameTime.Tick - 1
	crit := event.StreamCriteria{}.ForWorld(worldID)
	crit.FromTick = &prev
	crit.ToTick = &prev
	recent, err := p.eventStore.GetEventStream(ctx, crit)
	if err != nil {
		// Perception degrades for one tick, but the failure must not be silent:
		// a persistent store error would otherwise switch off memory and emotion
		// formation with no trace in the logs.
		p.logger.Warn("perception: failed to load previous tick's events",
			zap.Uint64("tick", uint64(prev)), zap.Error(err))
		return nil, dirty
	}
	if len(recent) == 0 {
		return nil, dirty
	}

	nameOf := func(id domain.ActorID) string {
		if a, ok := byID[id]; ok {
			return a.GetName()
		}
		return "кто-то"
	}

	var events []*event.GameEvent
	for _, npc := range byID {
		if npc.State == nil || npc.State.Emotional == nil {
			continue
		}
		loc := npc.State.GetCurrentLocation()

		// Memories the NPC forms in this single instant of perception belong to one
		// experienced moment; we link them so recalling one can surface the rest.
		var formed []*memory.Memory
		// Cue words from the moment (who/what is present), used to resurface faded
		// memories that mention them.
		cueSet := map[string]struct{}{}

		for _, evt := range recent {
			if evt.ActorID == npc.ID {
				// We don't react emotionally to ourselves, but we do remember what
				// we said and did, so an NPC can refer back to its own conduct.
				if p.memoryService != nil && salientOwnEvent(evt) {
					desc := describeForMemory(evt, npc.ID, nameOf)
					if mem, err := p.memoryService.CreateFromEvent(ctx, evt, npc.ID, desc, memory.EmotionalToneFromActor(npc)); err == nil {
						formed = append(formed, mem)
					}
				}
				continue
			}
			// Perceivable if directed at the NPC or happening where they are.
			directed := evt.TargetID != nil && *evt.TargetID == npc.ID
			if !directed && evt.LocationID != loc {
				continue
			}

			// The person we're seeing/hearing is a cue that can resurface old
			// memories that mention them.
			if name := nameOf(evt.ActorID); name != "" && name != "кто-то" {
				cueSet[name] = struct{}{}
			}

			if impactKind := p.emotionalImpact(npc, evt); impactKind != "" {
				before, _ := npc.State.Emotional.CurrentTone.GetDominantEmotion()
				resp := p.behaviorSystem.GenerateEmotionalResponse(npc, impactKind, nil)
				if len(resp.Emotions) > 0 {
					npc.State.Emotional.CurrentTone.Emotions = resp.Emotions
					dirty[npc.ID] = true
				}
				after, intensity := npc.State.Emotional.CurrentTone.GetDominantEmotion()
				if intensity >= emotionEventThreshold && after != before {
					events = append(events, p.emotionEvent(npc, before, after, intensity, worldID, gameTime.Tick))
				}
			}

			// Form a memory of salient events, coloured by how the NPC feels right
			// now (perception just updated their emotion) — that subjective charge
			// is what makes the memory vivid and slow to fade.
			if p.memoryService != nil && salientToRemember(evt.Type) {
				desc := describeForMemory(evt, npc.ID, nameOf)
				if mem, err := p.memoryService.CreateFromEvent(ctx, evt, npc.ID, desc, memory.EmotionalToneFromActor(npc)); err == nil {
					formed = append(formed, mem)
				}
			}
		}

		// A feared person in the room keeps the dread alive. Lasting
		// relationship-fear (earned by, say, being attacked) re-floors the NPC's
		// MOMENTARY fear whenever its object is present — so a violent
		// reputation is a standing consequence the player meets every time, not
		// a one-tick flash. Runs after event reactions so it isn't overwritten.
		if p.applyPresenceFear(npc, byID, loc) {
			dirty[npc.ID] = true
		}

		p.linkMoment(ctx, formed)

		// A present cue (someone the NPC sees/hears) can dredge up a faded,
		// compressed memory that mentions them.
		if p.memoryService != nil && len(cueSet) > 0 {
			keywords := make([]string, 0, len(cueSet))
			for w := range cueSet {
				keywords = append(keywords, w)
			}
			restCtx := memory.RestorationContext{
				CurrentLocation: loc,
				CurrentEmotion:  memory.EmotionalToneFromActor(npc),
				RecentKeywords:  keywords,
				CurrentTick:     gameTime.Tick,
			}
			_, _ = p.memoryService.RestoreOnCues(ctx, npc.ID, restCtx)
		}
	}
	return events, dirty
}

// applyPresenceFear floors the NPC's momentary fear to the strongest lasting
// fear it holds toward anyone co-located, through the shared presence scale
// (actor.PresenceFearFloor — one source for NPC tick and player self-regulation).
// Idempotent (a floor, not a sum), so a feared presence sustains dread tick after
// tick without runaway accumulation; when the feared actor leaves, the floor lifts
// and fear decays normally. Returns whether it raised the fear (caller marks dirty).
func (p *TickProcessor) applyPresenceFear(npc *actor.Actor, byID map[domain.ActorID]*actor.Actor, loc domain.LocationID) bool {
	if npc.State == nil || npc.State.Social == nil || npc.State.Emotional == nil {
		return false
	}
	var floor float32
	for id, other := range byID {
		if id == npc.ID || other.State == nil || other.State.GetCurrentLocation() != loc {
			continue
		}
		rel := npc.State.Social.GetRelationship(id)
		if rel == nil {
			continue
		}
		if f := actor.PresenceFearFloor(rel.Fear); f > floor {
			floor = f
		}
	}
	if floor <= 0 {
		return false
	}
	tone := npc.State.Emotional.CurrentTone
	if tone == nil {
		tone = &actor.EmotionalTone{}
		npc.State.Emotional.CurrentTone = tone
	}
	if tone.Emotions == nil {
		tone.Emotions = map[actor.EmotionType]float32{}
	}
	if tone.Emotions[actor.EmotionFear] >= floor {
		return false
	}
	tone.Emotions[actor.EmotionFear] = floor
	return true
}

// linkMoment associates the memories an NPC formed in one perception pass. They
// were experienced together, so a temporal link lets associative recall pull the
// whole moment back from any one of its parts. Chaining (not a full clique) keeps
// the graph sparse while still connected.
func (p *TickProcessor) linkMoment(ctx context.Context, formed []*memory.Memory) {
	if p.memoryService == nil {
		return
	}
	for i := 1; i < len(formed); i++ {
		_ = p.memoryService.Associate(ctx, formed[i-1], formed[i], memory.MemoryLinkTemporal)
	}
}

// emotionEvent builds an EmotionChanged event using the generic state-change data.
func (p *TickProcessor) emotionEvent(
	npc *actor.Actor,
	from, to actor.EmotionType,
	intensity float32,
	worldID domain.WorldID,
	tick domain.Tick,
) *event.GameEvent {
	data := event.StateChangeEventData{
		ActorID:   npc.ID,
		StateType: event.StateChangeEmotion,
		OldValue:  event.StringValue(string(from)),
		NewValue:  event.StringValue(string(to)),
		Reason:    "reaction to nearby event",
	}
	return event.NewGameEvent(
		event.EventTypeEmotionChanged,
		npc.ID,
		npc.State.GetCurrentLocation(),
		worldID,
		tick,
		data,
	)
}

// emotionalImpact returns the BehaviorSystem impact kind an event has on the
// perceiver. Combat carries its own charge regardless of who is involved; a
// social event (someone speaking nearby) is charged by how the perceiver feels
// about the speaker — a rival's voice grates, warm company gladdens. Returns ""
// when affectively neutral (a stranger's chatter, routine noise), leaving the
// NPC's mood untouched. This is what lets a peaceful social city, which has no
// combat, still stir real feelings.
func (p *TickProcessor) emotionalImpact(npc *actor.Actor, evt *event.GameEvent) string {
	if kind := perceivedImpact(evt.Type); kind != "" {
		return kind
	}
	// PlayerAction deliberately has NO branch here: the verdict engine is the
	// single owner of a deed's consequences and applies emotions, memories
	// and relationship shifts SYNCHRONOUSLY in the player's turn (the old
	// perception path fired a tick late — the victim could walk away first —
	// and would now double-count).
	if evt.Type == event.EventTypePlayerAction {
		return ""
	}
	if !isSocialEvent(evt.Type) || npc.State == nil || npc.State.Social == nil {
		return ""
	}
	rel := npc.State.Social.GetRelationship(evt.ActorID)
	if rel == nil {
		return ""
	}
	switch {
	case rel.IsHostile():
		return "insult"
	case rel.IsFriendly():
		return "help"
	default:
		return ""
	}
}

// isSocialEvent reports whether an event is a social overture (someone speaking
// or opening a conversation) that the relationship between the parties colours.
func isSocialEvent(t event.EventType) bool {
	switch t {
	case event.EventTypeDialogueLine, event.EventTypeConversationStarted:
		return true
	default:
		return false
	}
}

// perceivedImpact maps an event type to a BehaviorSystem impact kind
// (the strings assessEventImpact understands), or "" if emotionally neutral.
func perceivedImpact(t event.EventType) string {
	switch t {
	case event.EventTypeAttackPerformed, event.EventTypeDamageTaken, event.EventTypeActorDied:
		return "attack"
	case event.EventTypeCombatStarted:
		return "attack"
	case event.EventTypeCombatEnded:
		return "victory"
	default:
		return ""
	}
}

// salientToRemember reports whether an event type is worth forming a memory of,
// filtering out routine state/movement noise. RelationshipChanged is
// deliberately absent: the shift already lives in the actor's relationship
// state and in the event log, while as a memory it rendered into the
// contentless «Я: перемена в отношениях» that crowded real memories out of
// dialogue prompts.
func salientToRemember(t event.EventType) bool {
	switch t {
	case event.EventTypeAttackPerformed, event.EventTypeDamageTaken, event.EventTypeActorDied,
		event.EventTypeCombatStarted, event.EventTypeCombatEnded,
		event.EventTypeDialogueLine,
		// An ambient happening (the weaver's scene events) is by construction
		// out of the ordinary — that is its narrative point.
		// PlayerAction is deliberately absent: charged deeds form memories
		// SYNCHRONOUSLY through the verdict engine (with disposition-aware
		// perspectives); a second perception pass would only write duplicates
		// a tick late.
		event.EventTypeRandomEventTriggered:
		return true
	default:
		return false
	}
}

// trivialOwnActions are passive routine actions an NPC needn't commit to memory;
// remembering "I waited" every tick would only flood and dilute recall.
var trivialOwnActions = map[string]bool{
	"wait":        true,
	"observe":     true,
	"rest":        true,
	"listen_in":   true,
	"hum_a_tune":  true,
	"savour_meal": true,
	"idle":        true,
}

// salientOwnEvent reports whether an NPC's own event is worth remembering. Its
// own words always count; its own deeds count unless they are passive routine or
// a degraded fallback action. RelationshipChanged is deliberately absent here
// for the same reason as in salientToRemember: the shift already lives in the
// actor's relationship state, while as a memory it renders into the contentless
// «Я: перемена в отношениях» — which then even spread as a rumor.
func salientOwnEvent(evt *event.GameEvent) bool {
	switch evt.Type {
	case event.EventTypeDialogueLine,
		event.EventTypeAttackPerformed, event.EventTypeDamageTaken, event.EventTypeActorDied,
		event.EventTypeCombatStarted, event.EventTypeCombatEnded,
		// Goal progress is the deterministic replacement for the LLM-narrated
		// pursuit reason: the durable goal events render into concrete progress
		// memories («позади уже около 68% пути»), so recall moves the NPC
		// forward instead of looping a vague intent.
		event.EventTypeGoalProgressed, event.EventTypeGoalAchieved:
		return true
	case event.EventTypeNPCAction:
		data, ok := evt.Data.(event.NPCActionEventData)
		if !ok {
			return false
		}
		return !data.Fallback && !trivialOwnActions[data.ActionType]
	default:
		return false
	}
}

// Package event contains the event domain model for the D&D Living World system.
// Events are the fundamental building blocks of the event sourcing architecture.
package event

import (
	"encoding/json"
	"fmt"
	"time"

	"github.com/dnd-llm/dnd-llm/internal/domain"
)

// GameEvent represents a single event in the game world.
// Events are immutable and form the basis of the event sourcing pattern.
// All changes to the game state are recorded as events.
type GameEvent struct {
	// ID is the unique identifier for this event.
	ID domain.EventID `json:"id"`

	// Type is the type of event (combat, dialogue, movement, etc.).
	Type EventType `json:"type"`

	// ActorID is the primary actor who initiated this event.
	ActorID domain.ActorID `json:"actor_id"`

	// TargetID is the target of the event, if applicable.
	// For example, the target of an attack or the listener in a conversation.
	TargetID *domain.ActorID `json:"target_id,omitempty"`

	// LocationID is the location where this event occurred.
	LocationID domain.LocationID `json:"location_id"`

	// WorldID is the world this event belongs to.
	WorldID domain.WorldID `json:"world_id"`

	// Tick is the game time when this event occurred.
	Tick domain.Tick `json:"tick"`

	// Data contains type-specific event data.
	// This is polymorphic and depends on the event type.
	Data EventData `json:"data"`

	// Visibility determines who can perceive this event.
	Visibility domain.Visibility `json:"visibility"`

	// CausedBy is the ID of the event that caused this event (causal relationship).
	// This enables tracking chains of cause and effect.
	CausedBy *domain.EventID `json:"caused_by,omitempty"`

	// Metadata carries optional coordination annotations attached to an event by
	// the multi-player layer (compensation, merge, rumor/partial visibility). It
	// is nil for ordinary events and persisted as JSONB for audit.
	Metadata *EventMetadata `json:"metadata,omitempty"`

	// CreatedAt is the real-world timestamp when this event was created.
	CreatedAt time.Time `json:"created_at"`
}

// EventMetadata is the typed replacement for the former map[string]interface{}
// metadata bag. Every field corresponds to an annotation the coordination layer
// actually writes; grouping them keeps the persisted JSONB self-describing
// instead of a stringly-typed grab bag.
type EventMetadata struct {
	// Compensation marks an event emitted to undo a conflict loser's action.
	Compensation  bool   `json:"compensation,omitempty"`
	OriginalEvent string `json:"original_event,omitempty"`
	WinnerEvent   string `json:"winner_event,omitempty"`
	Narrative     string `json:"narrative,omitempty"`

	// Merge bookkeeping for events folded together during conflict resolution.
	MergedFrom   int      `json:"merged_from,omitempty"`
	SourceEvents []string `json:"source_events,omitempty"`

	// Rumor / partial-observation visibility annotations.
	IsRumor     bool    `json:"is_rumor,omitempty"`
	Reliability float64 `json:"reliability,omitempty"`
	IsPartial   bool    `json:"is_partial,omitempty"`
	Visibility  string  `json:"visibility,omitempty"`
}

// NewGameEvent creates a new game event with the given parameters.
func NewGameEvent(
	eventType EventType,
	actorID domain.ActorID,
	locationID domain.LocationID,
	worldID domain.WorldID,
	tick domain.Tick,
	data EventData,
) *GameEvent {
	return &GameEvent{
		ID:         domain.NewEventID(),
		Type:       eventType,
		ActorID:    actorID,
		LocationID: locationID,
		WorldID:    worldID,
		Tick:       tick,
		Data:       data,
		Visibility: domain.VisibilityPublic, // Default to public
		CreatedAt:  time.Now(),
	}
}

// WithTargetID sets the target actor ID for this event.
func (e *GameEvent) WithTargetID(targetID domain.ActorID) *GameEvent {
	e.TargetID = &targetID
	return e
}

// WithVisibility sets the visibility level for this event.
func (e *GameEvent) WithVisibility(visibility domain.Visibility) *GameEvent {
	e.Visibility = visibility
	return e
}

// WithCausedBy sets the causal relationship to another event.
func (e *GameEvent) WithCausedBy(eventID domain.EventID) *GameEvent {
	e.CausedBy = &eventID
	return e
}

// WithMetadata attaches typed coordination metadata to the event.
func (e *GameEvent) WithMetadata(meta *EventMetadata) *GameEvent {
	e.Metadata = meta
	return e
}

// Validate validates the event for correctness.
func (e *GameEvent) Validate() error {
	if e.ID.IsZero() {
		return fmt.Errorf("event ID is required")
	}

	if !e.Type.IsValid() {
		return fmt.Errorf("invalid event type: %s", e.Type)
	}

	if e.ActorID.IsZero() {
		return fmt.Errorf("actor ID is required")
	}

	if e.LocationID.IsZero() {
		return fmt.Errorf("location ID is required")
	}

	if e.WorldID.IsZero() {
		return fmt.Errorf("world ID is required")
	}

	if e.Tick.IsZero() {
		return fmt.Errorf("tick is required")
	}

	if e.Data == nil {
		return fmt.Errorf("event data is required")
	}

	// Validate that the event data is compatible with the event type. One data
	// struct intentionally serves a whole category of event types (e.g.
	// ConversationEventData → conversation_started/ended, MemoryEventData →
	// memory_created/forgotten/recalled/compressed — see unmarshalEventData), so
	// Data.EventType() is a coarse discriminator. Compare categories rather than
	// the exact type, which still catches cross-category mismatches.
	if e.Data.EventType().Category() != e.Type.Category() {
		return fmt.Errorf("event data category mismatch: event %s (%s) vs data %s (%s)",
			e.Type, e.Type.Category(), e.Data.EventType(), e.Data.EventType().Category())
	}

	// Validate the event data itself
	if err := e.Data.Validate(); err != nil {
		return fmt.Errorf("invalid event data: %w", err)
	}

	if !e.Visibility.IsValid() {
		return fmt.Errorf("invalid visibility: %s", e.Visibility)
	}

	return nil
}

// GetParticipants returns all actor IDs that participated in this event.
// This includes the primary actor and the target (if any).
func (e *GameEvent) GetParticipants() []domain.ActorID {
	participants := []domain.ActorID{e.ActorID}
	if e.TargetID != nil && !e.TargetID.IsZero() {
		participants = append(participants, *e.TargetID)
	}
	return participants
}

// IsVisibleTo determines if this event is visible to the given observer.
func (e *GameEvent) IsVisibleTo(observerID domain.ActorID, inSameLocation bool) bool {
	participants := e.GetParticipants()

	filter := domain.VisibilityFilter{
		Observer:       observerID,
		Participants:   participants,
		InSameLocation: inSameLocation,
		// These would be set based on actor's abilities
		HasPerception: false,
		HasTrueSight:  false,
	}

	return filter.CanSee(e.Visibility)
}

// Category returns the category of this event.
func (e *GameEvent) Category() EventCategory {
	return e.Type.Category()
}

// MarshalJSON implements custom JSON marshaling for GameEvent.
// This is necessary because EventData is an interface.
func (e *GameEvent) MarshalJSON() ([]byte, error) {
	type Alias GameEvent
	return json.Marshal(&struct {
		*Alias
		DataType string `json:"data_type"`
	}{
		Alias:    (*Alias)(e),
		DataType: string(e.Type),
	})
}

// UnmarshalJSON implements custom JSON unmarshaling for GameEvent.
// This is necessary because EventData is an interface.
func (e *GameEvent) UnmarshalJSON(data []byte) error {
	type Alias GameEvent
	aux := &struct {
		*Alias
		DataRaw  json.RawMessage `json:"data"`
		DataType string          `json:"data_type"`
	}{
		Alias: (*Alias)(e),
	}

	if err := json.Unmarshal(data, aux); err != nil {
		return err
	}

	// Parse the event type to determine which data type to unmarshal into
	eventType := EventType(aux.DataType)

	eventData, err := UnmarshalEventData(eventType, aux.DataRaw)
	if err != nil {
		return fmt.Errorf("failed to unmarshal event data: %w", err)
	}

	e.Data = eventData
	return nil
}

// UnmarshalEventData reconstructs the concrete EventData for a given event type
// from its JSON payload. It is the single source of truth for event-data typing
// on read — persistence layers MUST route through it rather than decoding into a
// generic map, otherwise consumers that type-switch on the concrete data (e.g.
// memory formation) silently fall through to a degraded path.
func UnmarshalEventData(eventType EventType, data []byte) (EventData, error) {
	var eventData EventData

	switch eventType {
	case EventTypeActorMoved, EventTypeActorEnteredLocation, EventTypeActorLeftLocation:
		if eventType == EventTypeActorEnteredLocation {
			var d LocationEntryEventData
			if err := json.Unmarshal(data, &d); err != nil {
				return nil, err
			}
			eventData = d
		} else {
			var d MovementEventData
			if err := json.Unmarshal(data, &d); err != nil {
				return nil, err
			}
			eventData = d
		}

	case EventTypeCombatStarted, EventTypeCombatEnded:
		var d CombatEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeAttackPerformed:
		var d AttackEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeDamageTaken:
		var d DamageEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeDialogueLine:
		var d DialogueEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeConversationStarted, EventTypeConversationEnded:
		var d ConversationEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeRelationshipChanged:
		var d RelationshipEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeFactionReputationChanged:
		var d FactionReputationEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeItemPickedUp, EventTypeItemDropped, EventTypeItemUsed,
		EventTypeItemEquipped, EventTypeItemUnequipped, EventTypeItemBroken, EventTypeItemRepaired:
		var d ItemEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeItemTraded:
		var d ItemTradeEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeSpellCast, EventTypeSpellEffect:
		var d SpellEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeManaSpent, EventTypeManaRestored:
		var d ManaEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeQuestStarted, EventTypeQuestUpdated, EventTypeQuestCompleted, EventTypeQuestFailed:
		var d QuestEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeNPCAction:
		var d NPCActionEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypePlayerAction:
		var d PlayerActionEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeGoalProgressed:
		var d GoalProgressEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeGoalAchieved:
		var d GoalAchievedEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeWorldReseeded:
		var d WorldReseededEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeEntityCreated, EventTypeEntityMaterialized:
		var d EntityLifecycleEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeEntityChanged:
		var d EntityChangeEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeEntityTransferred:
		var d EntityTransferEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeWeaverIntervened:
		var d WeaverIntervenedEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeFrontStarted:
		var d FrontStartedEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeFrontAdvanced:
		var d FrontAdvancedEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeFrontResolved:
		var d FrontResolvedEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeRandomEventTriggered:
		var d RandomEventEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeMentionsResolved:
		var d MentionsResolvedEventData
		if err := json.Unmarshal(data, &d); err != nil {
			return nil, err
		}
		eventData = d

	case EventTypeGoalCreated:
		var d GoalCreatedEventData
		if err := json.Unmarshal(data, &d); err != nil {
