// Clone creates a deep copy of the event.
// This is useful for creating derived events or for testing.
func (e *GameEvent) Clone() *GameEvent {
	clone := &GameEvent{
		ID:         e.ID,
		Type:       e.Type,
		ActorID:    e.ActorID,
		LocationID: e.LocationID,
		WorldID:    e.WorldID,
		Tick:       e.Tick,
		Data:       e.Data,
		Visibility: e.Visibility,
		CreatedAt:  e.CreatedAt,
	}

	if e.TargetID != nil {
		targetID := *e.TargetID
		clone.TargetID = &targetID
	}

	if e.CausedBy != nil {
		causedBy := *e.CausedBy
		clone.CausedBy = &causedBy
	}

	if e.Metadata != nil {
		meta := *e.Metadata
		if e.Metadata.SourceEvents != nil {
			meta.SourceEvents = append([]string(nil), e.Metadata.SourceEvents...)
		}
		clone.Metadata = &meta
	}

	return clone
}

// Event is a type alias for GameEvent for convenience and backward compatibility.
type Event = GameEvent

