package morph

import (
	"context"
	"fmt"
	"strings"

	infrallm "github.com/dnd-llm/dnd-llm/internal/infrastructure/llm"
)

// This file is the per-language LLM frame. The model is NOT asked to decline —
// generation of case forms is a metalinguistic task a small model fails at
// (~55% on held-out names). It is asked for the dictionary entry instead:
// genitive + gender + animacy + locative preposition. The genitive is picked
// from a grammar-constrained candidate set (see candidates.go), so a rename is
// physically impossible at decoding time, and the deterministic engine
// (engine.go) expands the full paradigm from that entry. A new language
// registers its own paradigm function — storage, service and call sites are
// untouched.

// paradigmFn turns a nominative name into a stored Record for one language.
type paradigmFn func(ctx context.Context, c infrallm.SchemaCompleter, name string) (*Record, error)

// registry maps a language code to its paradigm builder.
var registry = map[string]paradigmFn{
	"ru": ruParadigm,
}

// GenerateParadigm runs a language's paradigm frame for a name (dictionary
// entry from the LLM → deterministic expansion). The service worker and the
// llmbench probe both go through here, so the probe exercises the exact
// production call.
func GenerateParadigm(ctx context.Context, c infrallm.SchemaCompleter, lang, name string) (*Record, error) {
	build := registry[lang]
	if build == nil {
		return nil, fmt.Errorf("morph: no paradigm builder for %q", lang)
	}
	return build(ctx, c, name)
}

// DictEntry is the Russian dictionary-entry schema: the genitive (constrained
// to the candidate set via a dynamic enum), the gender, the animacy and the
// locative preposition. Everything else is derived in Go.
type DictEntry struct {
	Gen     string `json:"gen" maxlen:"100"`
	Gender  string `json:"gender" enum:"мужской,женский,средний,множественный"`
	Animate string `json:"animate" enum:"одушевлённое,неодушевлённое"`
	LocPrep string `json:"loc_prep" enum:"в,на"`
}

const ruMorphSystem = `Ты — словарь русского языка. Для названия в именительном падеже укажи:
- gen: родительный падеж (отвечает «нет кого/чего?»). Меняй только окончания слов. Выдуманные и редкие названия склоняй как обычные русские слова с тем же окончанием; несклоняемыми считай только явные заимствования и иностранные фамилии.
- gender: грамматический род названия.
- animate: одушевлённость — человек или зверь «одушевлённое», место, вещь или явление «неодушевлённое».
- loc_prep: предлог места для этого названия — «в» (в доме) или «на» (на площади).

## ПРИМЕРЫ
«Тетрадь» → {"gen":"Тетради","gender":"женский","animate":"неодушевлённое","loc_prep":"в"}
«Кузнец Степан» → {"gen":"Кузнеца Степана","gender":"мужской","animate":"одушевлённое","loc_prep":"в"}
«Дубовый Причал» → {"gen":"Дубового Причала","gender":"мужской","animate":"неодушевлённое","loc_prep":"на"}`

// ruParadigm asks for the dictionary entry and expands it deterministically.
func ruParadigm(ctx context.Context, c infrallm.SchemaCompleter, name string) (*Record, error) {
	req := infrallm.Request{
		SystemPrompt: ruMorphSystem,
		UserPrompt: fmt.Sprintf("«%s» → верни JSON: "+
			`{"gen":"...","gender":"...","animate":"...","loc_prep":"..."}`, name),
		Temperature: 0.1,
		MaxTokens:   160,
		Language:    "ru",
	}

	candidates := genitiveCandidates(name)
	if candidates != nil {
		req.Options = &infrallm.RequestOptions{
			DynamicEnums: map[string][]string{"gen": candidates},
		}
	}

	entry, _, err := infrallm.Decode[DictEntry](ctx, c, req)
	if err != nil {
		return nil, fmt.Errorf("morph %q: %w", name, err)
	}

	gen := entry.Gen
	if candidates == nil {
		// Free-form fallback (cross product over the cap): the stem validator
		// is the net against renames. A rejected genitive degrades the record
		// to empty slots — every call site falls back to its nominative-safe
		// phrasing — and is still cached so the name isn't re-warmed in a loop.
		gen = validateForm(name, gen)
		if gen == "" {
			return &Record{Name: name, Gender: genderCode(entry.Gender)}, nil
		}
	}

	rec := expandParadigm(name, gen, genderCode(entry.Gender), entry.Animate == "одушевлённое", entry.LocPrep)
	return rec, nil
}

// genderCode maps the Russian gender label to a short code.
func genderCode(g string) string {
	switch strings.TrimSpace(g) {
	case "мужской":
		return "m"
	case "женский":
		return "f"
	case "средний":
		return "n"
	case "множественный":
		return "pl"
	default:
		return ""
	}
}

// dedupeForms collects the distinct case phrases for the search index,
// dropping empties and anything equal to the nominative.
func dedupeForms(name string, forms ...string) []string {
	seen := map[string]bool{normalize(name): true}
	var out []string
	for _, f := range forms {
		f = strings.TrimSpace(f)
		if f == "" {
			continue
		}
		key := normalize(f)
		if seen[key] {
			continue
		}
		seen[key] = true
		out = append(out, f)
	}
	return out
}

package morph

import (
	"strings"
	"unicode"
	"unicode/utf8"
)

// candidates.go builds the closed answer set for the dictionary-entry call:
// every plausible genitive of the name, generated by inverting the declension
// classes. The set is injected into the request grammar as a dynamic enum, so
// the model cannot rename, truncate or invent a word — it can only CHOOSE the
// right genitive, which is the part that genuinely needs a feel for the
// language (gender of «Тихводь», the fluent vowel in «Рынок», the indeclinable
// «Соль» in a surname).

// maxGenitiveCandidates caps the cross-product size; past the cap the call
// falls back to a free-form genitive checked by the stem validator.
const maxGenitiveCandidates = 240

// genitiveCandidates returns every plausible genitive phrase of a name, or nil
// when the cross product would blow past the cap.
func genitiveCandidates(name string) []string {
	words := strings.Fields(name)
	if len(words) == 0 {
		return nil
	}

	perWord := make([][]string, len(words))
	total := 1
	for i, w := range words {
		perWord[i] = wordGenitiveCandidates(w)
		total *= len(perWord[i])
		if total > maxGenitiveCandidates {
			return nil
		}
	}

	phrases := []string{""}
	for _, cands := range perWord {
		next := make([]string, 0, len(phrases)*len(cands))
		for _, p := range phrases {
			for _, c := range cands {
				if p == "" {
					next = append(next, c)
				} else {
					next = append(next, p+" "+c)
				}
			}
		}
		phrases = next
	}
	return phrases
}

// wordGenitiveCandidates inverts the declension classes for one word: each
// plausible reading of its nominative ending contributes its genitive. The
// word itself is always a candidate — that is the indeclinable reading, and
// the correct one for the frozen tail of names like «Хлеб из ночной муки».
func wordGenitiveCandidates(w string) []string {
	out := []string{w}
	if utf8.RuneCountInString(w) < 3 {
		return out
	}
	low := strings.ToLower(w)
	add := func(form string) {
		if form == "" {
			return
		}
		form = matchCase(w, form)
		for _, have := range out {
			if have == form {
				return
			}
		}
		out = append(out, form)
	}
	stem := func(n int) string { return trimLastRunes(low, n) }

	switch {
	// Adjective readings (with the noun reading of the same ending alongside —
	// «Дарой» is a noun in -ой, «гений» a noun in -ий).
	case strings.HasSuffix(low, "ый"):
		add(stem(2) + "ого")
	case strings.HasSuffix(low, "ой"):
		add(stem(2) + "ого") // Сухой→Сухого
		add(stem(1) + "я")   // Дарой→Дароя
	case strings.HasSuffix(low, "ий"):
		add(stem(2) + "ого") // velar stems: великий→великого
		add(stem(2) + "его")
		add(stem(1) + "я") // noun reading: гений→гения
	case strings.HasSuffix(low, "ая"), strings.HasSuffix(low, "яя"):
		add(stem(2) + "ой")
		add(stem(2) + "ей")
	case strings.HasSuffix(low, "ое"), strings.HasSuffix(low, "ее"):
		add(stem(2) + "ого")
		add(stem(2) + "его")
	case strings.HasSuffix(low, "ые"), strings.HasSuffix(low, "ие"):
		add(stem(2) + "ых") // Ночные→Ночных
		add(stem(2) + "их")
		add(stem(1) + "я") // neuter noun reading: Здание→Здания

	// Noun readings by nominative ending.
	case strings.HasSuffix(low, "ия"):
		add(stem(1) + "и")
	case strings.HasSuffix(low, "а"):
		add(stem(1) + "ы")
		add(stem(1) + "и")
	case strings.HasSuffix(low, "я"):
		add(stem(1) + "и")
	case strings.HasSuffix(low, "о"):
		add(stem(1) + "а")
	case strings.HasSuffix(low, "е"), strings.HasSuffix(low, "ё"):
		add(stem(1) + "я")
	case strings.HasSuffix(low, "й"):
		add(stem(1) + "я")
	case strings.HasSuffix(low, "ь"):
		add(stem(1) + "я")         // masculine soft: Уголь→?
		add(stem(1) + "и")         // feminine 3rd: Тихводь→Тихводи
		add(fluent(stem(1)) + "я") // fluent vowel: Уголь→Угля, День→Дня
	case strings.HasSuffix(low, "ы"), strings.HasSuffix(low, "и"):
		// Plural readings.
		add(stem(1) + "ов")
		add(stem(1) + "ев")
		add(stem(1) + "ей")
		add(stem(1)) // zero ending: Ворота→Ворот
	default:
		// Consonant ending: masculine hard.
		add(low + "а")
		add(fluent(low) + "а") // Рынок→Рынка, Переулок→Переулка
	}
	return out
}

// fluent drops a fluent vowel (беглая гласная): an о/е/ё sitting between the
// final consonant and the rest of the stem («рынок»→«рынк», «угол»→«угл»).
// Returns "" when the word has no such shape.
func fluent(s string) string {
	r := []rune(s)
	if len(r) < 3 {
		return ""
	}
	last, beforeLast := r[len(r)-1], r[len(r)-2]
	if strings.ContainsRune(ruVowels+"ьй", unicode.ToLower(last)) {
		return ""
	}
	if v := unicode.ToLower(beforeLast); v != 'о' && v != 'е' && v != 'ё' {
		return ""
	}
	return string(r[:len(r)-2]) + string(last)
}

package morph

import (
	"fmt"
	"strings"
	"unicode/utf8"
)

// engine.go is the deterministic core of Russian declension. The insight is the
// dictionary convention: nominative + genitive + animacy pin down a noun's
// paradigm (the genitive exposes the stem, the softness, fluent vowels and
// indeclinability), and adjectives are fully regular from their own endings.
// So the LLM is only asked for the dictionary entry — one genitive picked from
// a grammar-constrained candidate set — and these tables expand everything
// else. The model never writes case forms; it cannot rename, truncate or
// invent. Wrong output here can only come from a wrong table, not a wrong roll
// of the dice.

// wordForms holds the six case forms of one word of a name.
type wordForms struct {
	nom, gen, dat, acc, ins, prep string
}

// frozenWord is the paradigm of an indeclinable word: every case = nominative.
// Correct Russian for genuinely indeclinable words («Ли», «метро») and for the
// already-inflected tail of names like «Хлеб из ночной муки».
func frozenWord(w string) wordForms {
	return wordForms{nom: w, gen: w, dat: w, acc: w, ins: w, prep: w}
}

// expandParadigm turns a dictionary entry into the full Record. genPhrase must
// have the same number of words as name; a word equal to its nominative is
// frozen, anything else is classified by its (nominative, genitive) ending
// pair. An unclassifiable word means an engine gap: the record degrades to
// empty slots (every call site falls back to the nominative) but is still
// cached, so the name isn't re-warmed in a loop.
func expandParadigm(name, genPhrase, gender string, animate bool, locPrep string) *Record {
	nomWords := strings.Fields(name)
	genWords := strings.Fields(genPhrase)
	rec := &Record{Name: name, Gender: gender}
	if len(nomWords) == 0 || len(nomWords) != len(genWords) {
		return rec
	}

	forms := make([]wordForms, len(nomWords))
	for i := range nomWords {
		wf, ok := expandWord(nomWords[i], genWords[i], animate)
		if !ok {
			return rec
		}
		forms[i] = wf
	}

	join := func(pick func(wordForms) string) string {
		parts := make([]string, len(forms))
		for i, wf := range forms {
			parts[i] = pick(wf)
		}
		return strings.Join(parts, " ")
	}
	gen := join(func(w wordForms) string { return w.gen })
	dat := join(func(w wordForms) string { return w.dat })
	acc := join(func(w wordForms) string { return w.acc })
	ins := join(func(w wordForms) string { return w.ins })
	prep := join(func(w wordForms) string { return w.prep })

	if locPrep != "в" && locPrep != "на" {
		locPrep = "в"
	}
	fromPrep := "из"
	if locPrep == "на" {
		fromPrep = "с"
	}

	rec.Slots = map[Slot]string{
		SlotIn:     locPrep + " " + prep,
		SlotInto:   locPrep + " " + acc,
		SlotTo:     "к " + dat,
		SlotFrom:   fromPrep + " " + gen,
		SlotOf:     gen,
		SlotObject: acc,
	}
	rec.Inflections = dedupeForms(name, gen, dat, acc, ins, prep)
	return rec
}

// expandWord derives one word's six forms from its nominative and genitive.
// Classification is driven by the ending pair; the genitive supplies the stem
// (so fluent vowels — «Рынок/Рынка», «Уголь/Угля» — come out right by
// construction). Returns ok=false when the pair fits no known class.
func expandWord(nom, gen string, animate bool) (wordForms, bool) {
	if strings.EqualFold(nom, gen) {
		return frozenWord(nom), true
	}
	if wf, ok := expandAdjective(nom, gen, animate); ok {
		return wf, true
	}
	return expandNoun(nom, gen, animate)
}

// --- adjectives -------------------------------------------------------------

// adjEndings maps a nominative adjective ending to its declension row.
// soft=true for -ий/-яя/-ее/-ие stems (except velar+ий, which is hard).
type adjRow struct {
	gen, dat, ins, prep, acc string // acc for inanimate; animate masc/pl use gen
	accIsNom                 bool   // feminine has its own acc; others derive
}

// expandAdjective recognises a (nominative, genitive) adjective pair and
// expands the regular adjective table for the word's own gender (read from its
// nominative ending). Returns ok=false when the endings don't look adjectival
// or the stems disagree.
func expandAdjective(nom, gen string, animate bool) (wordForms, bool) {
	type adjClass struct {
		nomEnd, genEnd                string
		dat, ins, prep, acc           string
		accFromGenWhenAnimate, plural bool
	}
	// The acc column is the inanimate accusative ending ("" = same as nom).
	classes := []adjClass{
		// masculine
		{nomEnd: "ый", genEnd: "ого", dat: "ому", ins: "ым", prep: "ом", acc: "", accFromGenWhenAnimate: true},
		{nomEnd: "ой", genEnd: "ого", dat: "ому", ins: "ым", prep: "ом", acc: "", accFromGenWhenAnimate: true},
		{nomEnd: "ий", genEnd: "ого", dat: "ому", ins: "им", prep: "ом", acc: "", accFromGenWhenAnimate: true}, // velar stems: великий→великого
		{nomEnd: "ий", genEnd: "его", dat: "ему", ins: "им", prep: "ем", acc: "", accFromGenWhenAnimate: true},
		// feminine (acc has its own form)
		{nomEnd: "ая", genEnd: "ой", dat: "ой", ins: "ой", prep: "ой", acc: "ую"},
		{nomEnd: "ая", genEnd: "ей", dat: "ей", ins: "ей", prep: "ей", acc: "ую"}, // hushing stems: хорошая→хорошей
		{nomEnd: "яя", genEnd: "ей", dat: "ей", ins: "ей", prep: "ей", acc: "юю"},
		// neuter
		{nomEnd: "ое", genEnd: "ого", dat: "ому", ins: "ым", prep: "ом", acc: ""},
		{nomEnd: "ее", genEnd: "его", dat: "ему", ins: "им", prep: "ем", acc: ""},
		// plural
		{nomEnd: "ые", genEnd: "ых", dat: "ым", ins: "ыми", prep: "ых", acc: "", accFromGenWhenAnimate: true, plural: true},
		{nomEnd: "ие", genEnd: "их", dat: "им", ins: "ими", prep: "их", acc: "", accFromGenWhenAnimate: true, plural: true},
	}
	for _, c := range classes {
		nomStem, ok1 := cutSuffix(nom, c.nomEnd)
		genStem, ok2 := cutSuffix(gen, c.genEnd)
		if !ok1 || !ok2 || !strings.EqualFold(nomStem, genStem) || utf8.RuneCountInString(nomStem) < 2 {
			continue
		}
		wf := wordForms{
			nom:  nom,
			gen:  gen,
			dat:  nomStem + c.dat,
			ins:  nomStem + c.ins,
			prep: nomStem + c.prep,
		}
		switch {
		case animate && c.accFromGenWhenAnimate:
			wf.acc = gen
		case c.acc != "":
			wf.acc = nomStem + c.acc
		default:
			wf.acc = nom
		}
		return wf, true
	}
	return wordForms{}, false
}

// --- nouns ------------------------------------------------------------------

// expandNoun classifies a noun by its (nominative, genitive) ending pair and
// expands the standard declension tables. The stem always comes from the
// genitive, which is what makes fluent vowels free.
func expandNoun(nom, gen string, animate bool) (wordForms, bool) {
	wf := wordForms{nom: nom, gen: gen}
	accAnimate := func(inanimate string) string {
		if animate {
			return gen
		}
		return inanimate
	}

	switch {
	// 1st declension: -а/-я (and -ия), feminine and masculine alike.
	case endsWith(nom, "ия") && endsWith(gen, "ии"):
		stem := trimLastRunes(gen, 1) // «Мари-и»
		wf.dat, wf.acc, wf.ins, wf.prep = stem+"и", stem+"ю", stem+"ей", stem+"и"
	case endsWith(nom, "а") && (endsWith(gen, "ы") || endsWith(gen, "и")):
		stem := trimLastRunes(gen, 1)
		wf.dat, wf.acc, wf.prep = stem+"е", stem+"у", stem+"е"
		if endsWithAny(stem, "ж", "ш", "ч", "щ", "ц") {
			wf.ins = stem + "ей"
		} else {
			wf.ins = stem + "ой"
		}
	case endsWith(nom, "я") && endsWith(gen, "и"):
		stem := trimLastRunes(gen, 1)
		wf.dat, wf.acc, wf.ins, wf.prep = stem+"е", stem+"ю", stem+"ей", stem+"е"

	// 3rd declension feminine: -ь, gen -и («Тихводь/Тихводи»).
	case endsWith(nom, "ь") && endsWith(gen, "и"):
		stem := trimLastRunes(gen, 1)
		wf.dat, wf.acc, wf.ins, wf.prep = stem+"и", nom, stem+"ью", stem+"и"

	// 2nd declension masculine soft: -ь/-й, gen -я («Уголь/Угля», «Дарой/Дароя»).
	case (endsWith(nom, "ь") || endsWith(nom, "й")) && endsWith(gen, "я"):
		stem := trimLastRunes(gen, 1)
		wf.dat, wf.ins = stem+"ю", stem+"ем"
		wf.acc = accAnimate(nom)
		if endsWith(nom, "ий") {
			wf.prep = stem + "и"
		} else {
			wf.prep = stem + "е"
		}

	// 2nd declension masculine hard: consonant, gen -а («Рынок/Рынка»).
	case endsWithConsonant(nom) && endsWith(gen, "а"):
		stem := trimLastRunes(gen, 1)
		wf.dat, wf.prep = stem+"у", stem+"е"
		wf.acc = accAnimate(nom)
		if endsWithAny(stem, "ж", "ш", "ч", "щ") {
			wf.ins = stem + "ем"
		} else {
			wf.ins = stem + "ом"
		}

	// neuter: -о/-е/-ё («Заречье/Заречья»).
	case endsWith(nom, "о") && endsWith(gen, "а"):
		stem := trimLastRunes(gen, 1)
		wf.dat, wf.acc, wf.ins, wf.prep = stem+"у", nom, stem+"ом", stem+"е"
	case (endsWith(nom, "е") || endsWith(nom, "ё")) && endsWith(gen, "я"):
		stem := trimLastRunes(gen, 1)
		wf.dat, wf.acc, wf.ins = stem+"ю", nom, stem+"ем"
		switch {
		case endsWith(nom, "ие"):
			wf.prep = stem + "и"
		case endsWith(nom, "ье"):
			wf.prep = nom // о Заречье
		default:
			wf.prep = stem + "е"
		}

	// pluralia tantum: -ы/-и with a plural genitive («Причалы/Причалов»).
	case (endsWith(nom, "ы") || endsWith(nom, "и")) && pluralGenitive(nom, gen):
		stem := trimLastRunes(nom, 1)
		soft := endsWith(nom, "и") && !endsWithAny(stem, "к", "г", "х", "ж", "ч", "ш", "щ")
		if soft {
			wf.dat, wf.ins, wf.prep = stem+"ям", stem+"ями", stem+"ях"
		} else {
			wf.dat, wf.ins, wf.prep = stem+"ам", stem+"ами", stem+"ах"
		}
		wf.acc = accAnimate(nom)

	default:
		return wordForms{}, false
	}
	return wf, true
}

// pluralGenitive reports whether gen looks like a plural genitive of nom:
// «Причалов», «Сваев», «Песней» or the bare-stem zero ending («Ворот»).
func pluralGenitive(nom, gen string) bool {
	stem := trimLastRunes(nom, 1)
	for _, end := range []string{"ов", "ев", "ёв", "ей", ""} {
		if strings.EqualFold(gen, stem+end) {
			return true
		}
	}
	return false
}

// --- rune helpers -----------------------------------------------------------

func endsWith(s, suffix string) bool {
	return strings.HasSuffix(strings.ToLower(s), suffix)
}

func endsWithAny(s string, suffixes ...string) bool {
	for _, suf := range suffixes {
		if endsWith(s, suf) {
			return true
		}
	}
	return false
}

const ruVowels = "аеёиоуыэюя"

func endsWithConsonant(s string) bool {
	r, size := utf8.DecodeLastRuneInString(strings.ToLower(s))
	if size == 0 || r == utf8.RuneError {
		return false
	}
	if r < 'а' || r > 'я' { // not a Russian letter (ё is above this range but is a vowel anyway)
		return false
	}
	return !strings.ContainsRune(ruVowels+"ьй", r)
}

func trimLastRunes(s string, n int) string {
	r := []rune(s)
	if len(r) < n {
		return ""
	}
	return string(r[:len(r)-n])
}

func cutSuffix(s, suffix string) (string, bool) {
	low := strings.ToLower(s)
	if !strings.HasSuffix(low, suffix) {
		return "", false
	}
	return trimLastRunes(s, utf8.RuneCountInString(suffix)), true
}

// debugString renders forms for logs and test failures.
func (w wordForms) debugString() string {
	return fmt.Sprintf("gen=%s dat=%s acc=%s ins=%s prep=%s", w.gen, w.dat, w.acc, w.ins, w.prep)
}

// playturn is a CLI probe for the player-driven loop: it joins the world over
// HTTP, opens the game WebSocket, sends one chat command as the player and
// prints the turn's progress and result. Acceptance tooling for the living
// city — what wscat was, but speaking the game's protocol.
//
//	go run ./cmd/playturn -cmd "спрашиваю у пекарки, что за хлеб из ночной муки"
package main

import (
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"net/http"
	"os"
	"strings"
	"time"

	"github.com/gorilla/websocket"
)

func main() {
	baseURL := flag.String("url", "http://localhost:8090", "backend base URL")
	command := flag.String("cmd", "", "player chat command (required)")
	timeout := flag.Duration("timeout", 150*time.Second, "how long to wait for the turn result")
	flag.Parse()

	if strings.TrimSpace(*command) == "" {
		fmt.Fprintln(os.Stderr, "usage: playturn -cmd \"осмотреться\"")
		os.Exit(2)
	}

	if err := join(*baseURL); err != nil {
		fail("join: %v", err)
	}

	wsURL := strings.Replace(*baseURL, "http", "ws", 1) + "/api/v1/ws"
	conn, _, err := websocket.DefaultDialer.Dial(wsURL, nil)
	if err != nil {
		fail("dial %s: %v", wsURL, err)
	}
	defer conn.Close()

	msg := map[string]any{
		"type":      "action",
		"timestamp": time.Now().Format(time.RFC3339),
		"data":      map[string]any{"command": *command},
	}
	if err := conn.WriteJSON(msg); err != nil {
		fail("send action: %v", err)
	}
	fmt.Printf("➤ %s\n", *command)

	deadline := time.Now().Add(*timeout)
	for {
		if err := conn.SetReadDeadline(deadline); err != nil {
			fail("set deadline: %v", err)
		}
		_, raw, err := conn.ReadMessage()
		if err != nil {
			fail("read: %v", err)
		}

		var envelope struct {
			Type    string          `json:"type"`
			Data    json.RawMessage `json:"data"`
			Payload json.RawMessage `json:"payload"`
		}
		if err := json.Unmarshal(raw, &envelope); err != nil {
			continue
		}

		switch envelope.Type {
		case "play_status":
			var d struct {
				Stage string `json:"stage"`
			}
			_ = json.Unmarshal(envelope.Data, &d)
			fmt.Printf("  … %s\n", d.Stage)

		case "action_result":
			printResult(envelope.Payload)
			return

		case "error":
			fmt.Printf("✗ server error: %s\n", string(envelope.Data))
			os.Exit(1)
		}
	}
}

func join(baseURL string) error {
	resp, err := http.Post(baseURL+"/api/v1/play/join", "application/json", bytes.NewBufferString(`{}`))
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	// 409 means the player is already in the world (join is idempotent across a
	// reseed, which wipes the city but keeps the player) — proceed to the WS.
	if resp.StatusCode == http.StatusConflict {
		return nil
	}
	if resp.StatusCode >= 300 {
		return fmt.Errorf("join returned %s", resp.Status)
	}
	return nil
}

func printResult(data json.RawMessage) {
	var r struct {
		Status     string `json:"status"`
		Narrative  string `json:"narrative"`
		Question   string `json:"question"`
		NPCReplies []struct {
			Name    string `json:"name"`
			Text    string `json:"text"`
			Gesture string `json:"gesture"`
			Emotion string `json:"emotion"`
			Tone    string `json:"tone"`
		} `json:"npc_replies"`
		TurnEvents []struct {
			ActorName string `json:"actor_name"`
			Text      string `json:"text"`
		} `json:"turn_events"`
		Tick int `json:"tick"`
	}
	if err := json.Unmarshal(data, &r); err != nil {
		fmt.Printf("✗ unparseable result: %v\n%s\n", err, data)
		os.Exit(1)
	}

	fmt.Printf("\n[%s, tick %d]\n", r.Status, r.Tick)
	if r.Narrative != "" {
		fmt.Printf("— %s\n", r.Narrative)
	}
	if r.Question != "" {
		fmt.Printf("? %s\n", r.Question)
	}
	for _, l := range r.NPCReplies {
		// Бейдж — жест (согласован с текстом по построению); эмоция — внутренний
		// сигнал отношений, в выводе игрока её нет.
		if l.Gesture != "" {
			fmt.Printf("%s (%s): «%s»\n", l.Name, l.Gesture, l.Text)
		} else {
			fmt.Printf("%s: «%s»\n", l.Name, l.Text)
		}
	}
	for _, e := range r.TurnEvents {
		// Some events are self-contained second-person facts (a hazard burning the
		// player) with no actor name — print them without an empty "  • : " prefix.
		if strings.TrimSpace(e.ActorName) == "" {
			fmt.Printf("  • %s\n", e.Text)
		} else {
			fmt.Printf("  • %s: %s\n", e.ActorName, e.Text)
		}
	}
}

func fail(format string, a ...any) {
	fmt.Fprintf(os.Stderr, "✗ "+format+"\n", a...)
	os.Exit(1)
}

