// crystallizeAt asks the common-sense gate to birth the mentioned mundane
// thing right here. Nil-safe and best-effort: nil means «здесь такого нет».
func (s *TurnService) crystallizeAt(ctx context.Context, tc *turnContext, mention string) *entity.Entity {
	if s.crystallizer == nil {
		return nil
	}
	here := tc.player.GetCurrentLocation()

	// What is already in the scene anchors the gate's common sense (a hearth
	// on view makes a torch obvious). Best-effort.
	var present []string
	if s.knowledge != nil {
		holders := []domain.ActorID{tc.player.ID}
		for _, a := range tc.coLocated() {
			holders = append(holders, a.ID)
		}
		if things, err := s.knowledge.ListPresent(ctx, knowledge.Scope{
			WorldID:  tc.worldID,
			ActorID:  tc.player.ID,
			Location: here,
		}, holders); err == nil {
			for _, e := range things {
				present = append(present, e.Name)
			}
		}
	}

	return s.crystallizer.TryCrystallize(ctx, knowledge.CrystallizeInput{
		WorldID:       tc.worldID,
		Location:      here,
		LocationName:  tc.locationName(here),
		LocationDesc:  tc.locationDescription(here),
		TimeOfDay:     appllm.TimeOfDayRu(int(tc.gameTime.Hour())),
		PresentThings: present,
		Mention:       mention,
		SourceActor:   tc.player.ID,
		Tick:          tc.tick,
	})
}

