package player

import (
	"context"
	"fmt"
	"math"
	"strings"

	"github.com/dnd-llm/dnd-llm/internal/application/extraction"
	"github.com/dnd-llm/dnd-llm/internal/application/knowledge"
	appllm "github.com/dnd-llm/dnd-llm/internal/application/llm"
	"github.com/dnd-llm/dnd-llm/internal/application/social"
	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/actor"
	"github.com/dnd-llm/dnd-llm/internal/domain/check"
	"github.com/dnd-llm/dnd-llm/internal/domain/entity"
	"github.com/dnd-llm/dnd-llm/internal/domain/event"
	"github.com/dnd-llm/dnd-llm/internal/domain/skill"
	"go.uber.org/zap"
)

// Ownership transfers are mechanics, not prose. Taking, giving, buying,
// selling and stealing all converge on the same primitives: ground the thing
// in what is physically HERE, decide how it changes hands — deterministic
// relink for unowned things, the owner's in-character consent (a dialogue
// line carrying a decision) for owned ones, a stealth contest for covert
// takes — then execute: relink owner, move coins, append the transfer event.

// ============================================================================
// take
// ============================================================================

func (s *TurnService) doTake(ctx context.Context, tc *turnContext, action extraction.ParsedPlayerAction) (*actionOutcome, error) {
	mention := strings.TrimSpace(action.Topic)
	if mention == "" {
		return &actionOutcome{question: "Что именно взять?"}, nil
	}

	thing, question, err := s.groundPresentThing(ctx, tc, mention)
	if err != nil {
		// A technical grounding failure must degrade, not cancel the whole
		// turn (the old behaviour killed multi-action turns over one bad
		// lookup): treat it as "not found" and let the gate judge.
		s.logger.Warn("take grounding failed; degrading to not-found", zap.String("mention", mention), zap.Error(err))
		thing, question = nil, "Здесь не видно такого."
	}
	if thing == nil {
		// Not among the present things: the common-sense gate may birth a
		// mundane item out of thin air («хватаю факел» in a tavern), one LLM
		// call total. A refusal falls back to the honest question.
		if stub := s.crystallizeAt(ctx, tc, mention); stub != nil {
			if err := s.executeTransfer(ctx, tc, stub, nil, tc.player.ID, 0, event.TransferPickup); err != nil {
				return nil, err
			}
			return s.transferNarrative(ctx, tc, action, fmt.Sprintf("Ты берёшь: %s.", stub.Name)), nil
		}
		if question == "" {
			question = "Здесь не видно такого."
		}
		return &actionOutcome{question: question}, nil
	}
	if question != "" {
		return &actionOutcome{question: question}, nil
	}

	// Physical form bounds what bare hands can carry off (entity.Kind.Carriable):
	// lore is immaterial, a feature too large and fixed, a substance slips through
	// fingers (a handful at most — a quantity needs a vessel). Only a discrete item
	// is carried off whole. Dash-apposition keeps the phrasing morphology-safe.
	switch thing.Kind {
	case entity.KindLore:
		return &actionOutcome{narrative: fmt.Sprintf("%s — это предание, не вещь: в руки его не взять.", thing.Name)}, nil
	case entity.KindFeature:
		return &actionOutcome{narrative: fmt.Sprintf("%s — часть этого мира, с собой не унести.", thing.Name)}, nil
	case entity.KindSubstance:
		return &actionOutcome{narrative: fmt.Sprintf("%s — пригоршню зачерпнуть можно, но чтобы унести, нужна посуда.", thing.Name)}, nil
	}

	owner := s.ownerOf(ctx, thing)
	if owner != nil && *owner == tc.player.ID {
		return &actionOutcome{narrative: fmt.Sprintf("%s и так при тебе.", thing.Name)}, nil
	}

	// Owner standing right here: covert wording means a stealth contest; an
	// open take of a WARE settles at the deterministic engine price (money is
	// mechanics — no NPC will in the loop); only what money cannot buy
	// (value = 0) goes through the in-character consent path.
	if owner != nil {
		if holder := tc.actorByID(*owner); holder != nil && holder.GetCurrentLocation() == tc.player.GetCurrentLocation() {
			if action.Covert {
				return s.stealFrom(ctx, tc, thing, holder)
			}
			if thing.Value > 0 {
				return s.buyAtPrice(ctx, tc, thing, holder)
			}
			return s.proposeTransfer(ctx, tc, thing, holder, appllm.OfferPlayerBuys, action)
		}
	}

	// Unowned, or the owner is elsewhere while the thing lies here: it can be
	// picked up. The world remembers the pickup either way; an absent owner's
	// grievance is a future mechanic, not a blocker.
	if err := s.executeTransfer(ctx, tc, thing, owner, tc.player.ID, 0, event.TransferPickup); err != nil {
		return nil, err
	}
	return s.transferNarrative(ctx, tc, action, fmt.Sprintf("Ты забираешь: %s.", thing.Name)), nil
}

// ============================================================================
// give
// ============================================================================

func (s *TurnService) doGive(ctx context.Context, tc *turnContext, action extraction.ParsedPlayerAction) (*actionOutcome, error) {
	mention := strings.TrimSpace(action.Topic)
	if mention == "" {
		return &actionOutcome{question: "Что именно отдать?"}, nil
	}

	thing, question, err := s.groundPresentThing(ctx, tc, mention)
	if err != nil {
		// Give never crystallizes (one cannot gift a thing that does not
		// exist), but a technical failure still must not cancel the turn.
		s.logger.Warn("give grounding failed; degrading", zap.String("mention", mention), zap.Error(err))
		return &actionOutcome{question: "Здесь не видно такого."}, nil
	}
	if question != "" {
		return &actionOutcome{question: question}, nil
	}

	owner := s.ownerOf(ctx, thing)
	if owner == nil || *owner != tc.player.ID {
		return &actionOutcome{narrative: fmt.Sprintf("%s — не твоя вещь, не тебе её отдавать.", thing.Name)}, nil
	}

	addressees, question, err := s.resolveAddressees(ctx, tc, action.Who)
	if err != nil {
		return nil, err
	}
	if question != "" {
		return &actionOutcome{question: question}, nil
	}
	var target *actor.Actor
	switch len(addressees) {
	case 0:
		co := tc.coLocated()
		if len(co) == 1 {
			target = co[0]
		} else {
			return &actionOutcome{question: "Кому именно отдать?"}, nil
		}
	case 1:
		target = addressees[0]
	default:
		return &actionOutcome{question: "Одну вещь — одному человеку. Кому именно?"}, nil
	}

	// Money is mechanics: selling a ware settles at the engine price; a gift
	// is accepted by disposition. The consent path remains only for selling
	// what money cannot buy (value = 0 — let the NPC's will judge that).
	if strings.TrimSpace(action.Payment) != "" && thing.Value > 0 {
		return s.sellAtPrice(ctx, tc, thing, target)
	}
	if strings.TrimSpace(action.Payment) == "" {
		return s.giveGift(ctx, tc, thing, target)
	}
	return s.proposeTransfer(ctx, tc, thing, target, appllm.OfferPlayerSells, action)
}

// ============================================================================
// attack
// ============================================================================

func (s *TurnService) doAttack(ctx context.Context, tc *turnContext, action extraction.ParsedPlayerAction) (*actionOutcome, error) {
	addressees, question, err := s.resolveAddressees(ctx, tc, action.Who)
	if err != nil {
		return nil, err
	}
	if question != "" {
		return &actionOutcome{question: question}, nil
	}
	if len(addressees) == 0 {
		return &actionOutcome{question: "На кого именно?"}, nil
	}
	target := addressees[0]

	// The deed is the bare act (verb + optional instrument). The TARGET is NOT
	// folded in: it's carried by the verdict (v.targetNPC) and named by the
	// facts — repeating it here made the victim's own memory read «На меня
	// нападают: Вася … ударить: Купец Изольт» (first person framing, third
	// person self-reference) and the witness's double-name the target. No name
	// in the deed also means no morphology concern.
	deed := "ударить"
	if how := strings.TrimSpace(action.Topic); how != "" {
		deed += " " + how
	}

	// The blow's BODILY toll is an uncertain contest: a check (biased by the player's
	// feeling — rage harder but wilder, fear pulled but wary) sets how it lands and what
	// it costs. Resolve and commit the harm BEFORE the social verdict, so the strike fact
	// colours the narration and the target's wound is real, not just their fright.
	strike := s.resolveStrike(tc, target)
	s.applyStrike(ctx, tc, target, strike)

	// Атака — готовый вердикт: цель заземлена точным граундингом, заряд
	// враждебен по определению. Ядро коммитит событие, эмоции, отношение и
	// память жертвы со свидетелями СЕЙЧАС; рендерер описывает свершившееся.
	v := &verdict{
		kind:      verdictAssault,
		targetNPC: target,
		facts:     append([]string{strikeFact(strike.tier)}, assaultFacts(target.Identity.Name, len(tc.coLocated())-1)...),
		// A blow before the watch draws the law's challenge — the struck target,
		// even a guard, is the one wronged and leads nothing.
		lawConfront: lawConfrontationFact(guardsAmong(witnessesExcept(tc.coLocated(), target.ID))),
	}
	if err := s.applyVerdict(ctx, tc, deed, v); err != nil {
		return nil, fmt.Errorf("apply attack verdict: %w", err)
	}

	narrative, err := s.narrator.NarratePlayerAction(ctx, s.verdictNarrationInput(ctx, tc, deed, v, action.Topic))
	if err != nil {
		s.logger.Warn("attack narration failed", zap.Error(err))
		narrative = fmt.Sprintf("Ты пытаешься %s. %s", deed, strings.Join(v.facts, " "))
	}
	return &actionOutcome{narrative: withConfront(narrative, v)}, nil
}

// hostileShift / friendlyShift are the relationship deltas of a hostile blow
// and an accepted gift — the same scale conversation sentiment uses.
const (
	hostileShift  = 8
	friendlyShift = 4
)

// ============================================================================
// the consent path: a dialogue line carrying a decision
// ============================================================================

// proposeTransfer puts the proposal to the thing's owner (or receiver) as a
// conversation move: the offer opens/continues the talk, the NPC answers in
// character with a structured decision, and deterministic code executes it.
func (s *TurnService) proposeTransfer(
	ctx context.Context,
	tc *turnContext,
	thing *entity.Entity,
	counterpart *actor.Actor,
	direction appllm.OfferDirection,
	action extraction.ParsedPlayerAction,
) (*actionOutcome, error) {
	// The proposal is a conversation move — it lands in the same fold-backed
	// talk as any line, so the haggle's history is simply the conversation's.
	conv := s.activeConversation(ctx, tc)
	if conv == nil || !conv.Has(counterpart.ID) {
		if conv != nil {
			s.endConversation(ctx, tc, conv)
		}
		var err error
		if conv, err = s.startConversation(ctx, tc, []*actor.Actor{counterpart}, thing.Name); err != nil {
			return nil, fmt.Errorf("open transfer conversation: %w", err)
		}
	}

	// The player's own words enter the log when they spoke; the structured
	// proposal itself reaches the NPC through the offer frame.
	if line := strings.TrimSpace(action.Utterance); line != "" {
		playerLine := event.NewGameEvent(
			event.EventTypeDialogueLine,
			tc.player.ID, tc.player.GetCurrentLocation(), tc.worldID, tc.tick,
			event.DialogueEventData{
				ConversationID: conv.ID,
				SpeakerID:      tc.player.ID,
				ListenerIDs:    []domain.ActorID{counterpart.ID},
				Text:           line,
				Language:       "ru",
			},
		)
		if err := s.events.Append(ctx, playerLine); err != nil {
			return nil, fmt.Errorf("append player line: %w", err)
		}
	}

	dc := appllm.DialogueContext{
		Speaker:        counterpart,
		Listener:       tc.player,
		Topic:          thing.Name,
		Mood:           npcMood(counterpart),
		ConversationID: conv.ID,
		WorldID:        tc.worldID,
		CurrentTick:    tc.tick,
	}
	offer := appllm.Offer{
		Direction:   direction,
		ItemName:    thing.Name,
		ItemGist:    thing.Gist,
		PlayerPrice: strings.TrimSpace(action.Payment),
	}

	// Facts before prose: the will is decided first (a tiny frame), the core
	// EXECUTES it, and only then the reply is rendered with the executed
	// verdict in the prompt — «готов взять!» can no longer ride a refusal.
	decision, err := s.dialogue.DecideOffer(ctx, dc, offer)
	if err != nil {
		s.logger.Warn("offer decision failed", zap.String("npc", counterpart.Identity.Name), zap.Error(err))
		return &actionOutcome{narrative: fmt.Sprintf("%s обдумывает твоё предложение.", counterpart.Identity.Name)}, nil
	}

	var settledNote string
	if decision.Decision == appllm.OfferAccepted {
		note, err := s.executeConsented(ctx, tc, thing, counterpart, direction, decision.Price)
		if err != nil {
			return nil, err
		}
		if note != "" {
			// The purse vetoed the deal: the decision honestly degrades.
			decision = &appllm.OfferDecision{Decision: appllm.OfferRefused}
			settledNote = note
		}
	}

	// Facts before prose, at the surface too: every consent outcome carries a
	// deterministic, closed-vocabulary line stating what changed hands. Before,
	// a refusal's only signal was the model's lyric and the player could not
	// tell whether the thing moved. The purse-veto note, when present, already
	// is that fact, so it wins.
	if settledNote == "" {
		settledNote = offerOutcomeFact(counterpart.Identity.Name, thing.Name, direction, *decision)
	}
	reply := s.offerReply(ctx, tc, conv.ID, counterpart, dc, offer, *decision)
	return &actionOutcome{reply: reply, narrative: settledNote}, nil
}

// offerOutcomeFact states a consent transfer's outcome in one deterministic
// line, built from the executed verdict — never the model. The spoken reply
// then only COLOURS this fact. Mirrors the gift path's «{Name} принимает: …».
func offerOutcomeFact(npcName, thingName string, direction appllm.OfferDirection, decision appllm.OfferDecision) string {
	playerTakes := direction == appllm.OfferPlayerBuys
	switch decision.Decision {
	case appllm.OfferAccepted:
		if playerTakes {
			return fmt.Sprintf("%s отдаёт: %s.", npcName, thingName)
		}
		return fmt.Sprintf("%s принимает: %s.", npcName, thingName)
	case appllm.OfferCounter:
		return fmt.Sprintf("%s просит за это: %d мон.", npcName, decision.Price)
	default: // OfferRefused and any unknown verdict: the safe, honest reading.
		if playerTakes {
			return fmt.Sprintf("%s не отдаёт: %s.", npcName, thingName)
		}
		return fmt.Sprintf("%s не берёт: %s.", npcName, thingName)
	}
}

// offerReply renders and journals the NPC's spoken answer from the executed
// decision. Degrades to a closed line — the deal already stands either way.
func (s *TurnService) offerReply(
	ctx context.Context,
	tc *turnContext,
	convID string,
	counterpart *actor.Actor,
	dc appllm.DialogueContext,
	offer appllm.Offer,
	decision appllm.OfferDecision,
) *NPCLine {
	resp, err := s.dialogue.SpeakOfferOutcome(ctx, dc, offer, decision)
	if err != nil {
		s.logger.Warn("offer outcome reply failed", zap.String("npc", counterpart.Identity.Name), zap.Error(err))
		text := map[string]string{
			appllm.OfferAccepted: "По рукам.",
			appllm.OfferCounter:  fmt.Sprintf("Моя цена — %d мон.", decision.Price),
			appllm.OfferRefused:  "Нет. Эта вещь не для того.",
		}[decision.Decision]
		resp = &appllm.OfferResponse{Content: text, Decision: decision.Decision, Price: decision.Price}
	}

	// The NPC's answer is a spoken line in the log — the next haggling round
	// builds on it through the conversation history.
	npcLine := event.NewGameEvent(
		event.EventTypeDialogueLine,
		counterpart.ID, tc.player.GetCurrentLocation(), tc.worldID, tc.tick,
		event.DialogueEventData{
			ConversationID: convID,
			SpeakerID:      counterpart.ID,
			ListenerIDs:    []domain.ActorID{tc.player.ID},
			Text:           resp.Content,
			Emotion:        resp.Emotion,
			Language:       "ru",
		},
	)
	if err := s.events.Append(ctx, npcLine); err != nil {
		s.logger.Warn("append offer reply failed", zap.Error(err))
	}

	return &NPCLine{
		ActorID: counterpart.ID,
		Name:    counterpart.Identity.Name,
		Text:    resp.Content,
		Gesture: resp.BodyLanguage,
		Emotion: resp.Emotion,
	}
}

// executeConsented settles an accepted offer: coins move, ownership relinks,
// the transfer is journaled. Returns a non-empty note when the player's purse
// vetoed the deal (the honest degradation path).
func (s *TurnService) executeConsented(
	ctx context.Context,
	tc *turnContext,
	thing *entity.Entity,
	counterpart *actor.Actor,
	direction appllm.OfferDirection,
	price int,
) (string, error) {
	kind := event.TransferTrade
	if price == 0 {
		kind = event.TransferGift
	}

	switch direction {
	case appllm.OfferPlayerBuys:
		if price > tc.player.State.Wealth {
			return fmt.Sprintf("В твоём кошеле лишь %d мон. — на такую цену не хватает.", tc.player.State.Wealth), nil
		}
		tc.player.State.Wealth -= price
		counterpart.State.Wealth += price
		ownerID := counterpart.ID
		if err := s.executeTransfer(ctx, tc, thing, &ownerID, tc.player.ID, price, kind); err != nil {
			return "", err
		}
	case appllm.OfferPlayerGives, appllm.OfferPlayerSells:
		// The merchant is always solvent: NPC purses may go negative by design.
		counterpart.State.Wealth -= price
		tc.player.State.Wealth += price
		playerID := tc.player.ID
		if err := s.executeTransfer(ctx, tc, thing, &playerID, counterpart.ID, price, kind); err != nil {
			return "", err
		}
		// An accepted gift warms the receiver toward the giver.
		if kind == event.TransferGift {
			s.shiftRelationship(ctx, tc, counterpart, friendlyShift)
		}
	}

	if err := s.actors.Update(ctx, tc.player); err != nil {
		s.logger.Warn("persist player purse failed", zap.Error(err))
	}
	if err := s.actors.Update(ctx, counterpart); err != nil {
		s.logger.Warn("persist counterpart purse failed", zap.Error(err))
	}
	return "", nil
}

// crystallizeAt looks the mention up in the location's prop fund and births it
// on a match. The fund is established lazily: an unfurnished place is furnished
// once from its own description (so «хватаю факел» works in any tavern, authored
// or not, including ones the weaver builds at runtime) — that is the only LLM
// call, and only on first reach into a bare place. The lookup itself is fully
// deterministic. Nil-safe: nil means «такого здесь нет».
func (s *TurnService) crystallizeAt(ctx context.Context, tc *turnContext, mention string) *entity.Entity {
	if s.crystallizer == nil {
		return nil
	}
	here := tc.player.GetCurrentLocation()
	loc := tc.locations[here]
	if loc == nil {
		return nil
	}
	var props []knowledge.Prop
	if s.furnisher != nil {
		props = s.furnisher.EnsureFund(ctx, tc.worldPremise, tc.worldEra, loc)
	} else {
		props = knowledge.PropsFromState(loc.State)
	}
	if len(props) == 0 {
		return nil
	}
	return s.crystallizer.TryCrystallize(ctx, knowledge.CrystallizeInput{
		WorldID:     tc.worldID,
		Location:    here,
		Mention:     mention,
		Props:       props,
		SourceActor: tc.player.ID,
		Tick:        tc.tick,
	})
}

// ============================================================================
// the stealth contest
// ============================================================================

const (
	// stealthBaseDice is an unhindered thief's nimbleness at a quiet take — the
	// pool before DEX adds and the owner's vigilance takes away.
	stealthBaseDice = 3
	// paranoiaVigilanceDice is how many dice a FULLY paranoid owner (1.0) takes off
	// the thief's pool; lesser wariness scales down proportionally.
	paranoiaVigilanceDice = 2
	// crowdEyesPerDie: every this-many extra onlookers beyond the owner cost the
	// thief one die — a packed room is harder to palm a thing in.
	crowdEyesPerDie = 2
)

// stealFrom is a covert take from a present owner: a deterministic contest of
// the moment (the owner's wariness, the crowd) with a tick-seeded roll —
// reseed-stable for the replay. Success transfers quietly; getting caught is
// a hostile act with everything that follows.
func (s *TurnService) stealFrom(ctx context.Context, tc *turnContext, thing *entity.Entity, owner *actor.Actor) (*actionOutcome, error) {
	if stealthSucceeds(tc, owner) {
		ownerID := owner.ID
		if err := s.executeTransfer(ctx, tc, thing, &ownerID, tc.player.ID, 0, event.TransferTheft); err != nil {
			return nil, err
		}
		return &actionOutcome{narrative: fmt.Sprintf("Никто не заметил. %s — теперь у тебя.", thing.Name)}, nil
	}

	// Caught red-handed: the thing stays, the world reacts. The full hostile
	// consequence bundle lands NOW — the owner's fear/fury, the witnesses'
	// alarm, the memories — through the same verdict path an attack takes
	// (facts unused: this branch keeps its own closed prose). A theft caught
	// before the watch is a crime the law sees — it confronts, just as for a
	// blow; the owner, even a guard, is the wronged party and leads nothing.
	v := &verdict{kind: verdictAssault, targetNPC: owner,
		lawConfront: lawConfrontationFact(guardsAmong(witnessesExcept(tc.coLocated(), owner.ID)))}
	if err := s.applyVerdict(ctx, tc, "попытаться украсть чужую вещь", v); err != nil {
		return nil, fmt.Errorf("apply theft verdict: %w", err)
	}

	return &actionOutcome{narrative: withConfront(fmt.Sprintf(
		"Ты тянешься к чужому добру — и %s ловит тебя за руку. Взгляд тяжелеет; вещь остаётся при хозяине.",
		owner.Identity.Name,
	), v)}, nil
}

// stealthSucceeds is the theft contest, resolved through the one check primitive
// (domain/check): the thief's nimbleness (DEX) pools against the owner's vigilance,
// seeded from the tick and the parties so the replay rolls the same. The thief's
// FEELING biases the same dials every contested deed reads (actor.EmotionBias) — a
// furious or terror-shaken hand fumbles a lift it would make composed. A graded outcome
// the caller reads as did-it-go-unnoticed; the richer Mixed ("taken, but noticed") is a
// future enrichment of stealFrom, not a separate dice model.
func stealthSucceeds(tc *turnContext, owner *actor.Actor) bool {
	capability := stealthBaseDice + tc.player.AbilityModifier(skill.AbilityDexterity)
	capability, pos, _ := actor.DominantBias(tc.player).Apply(capability, check.Risky)
	seed := check.Seed(tc.tick, "steal", string(tc.player.ID), string(owner.ID))
	pool := check.PoolFromContest(capability, ownerVigilance(tc, owner))
	return check.Resolve(seed, pool, pos).Tier.Accomplished()
}

// ownerVigilance is how hard an owner is to fool, in dice the thief LOSES from their
// pool: their wariness (paranoia), the extra eyes of a crowd, and a watchful dislike
// of the thief. The successor to the old hand-tuned chance penalties, now expressed
// in the shared currency of the check pool.
func ownerVigilance(tc *turnContext, owner *actor.Actor) int {
	dice := 0
	if owner.Identity != nil && owner.Identity.Personality != nil {
		dice += int(math.Round(float64(owner.Identity.Personality.Paranoia) * paranoiaVigilanceDice))
	}
	if extraEyes := len(tc.coLocated()) - 1; extraEyes > 0 {
		dice += extraEyes / crowdEyesPerDie
	}
	if affectionToward(owner, tc.player.ID) < 0 {
		dice++ // a wary owner keeps a closer watch on a disliked guest
	}
	return dice
}

// ============================================================================
// shared primitives
// ============================================================================

// groundPresentThing grounds the mention in the scene's PHYSICAL contents.
// Tier zero is the lexical focus over present names; the resolver LLM decides
// only when lexicon fails. Knowing about a thing elsewhere is not enough —
// hands need it here.
func (s *TurnService) groundPresentThing(ctx context.Context, tc *turnContext, mention string) (*entity.Entity, string, error) {
	if s.knowledge == nil {
		return nil, "Здесь нет такого.", nil
	}
	here := tc.player.GetCurrentLocation()
	holders := []domain.ActorID{tc.player.ID}
	for _, a := range tc.coLocated() {
		holders = append(holders, a.ID)
	}
	present, err := s.knowledge.ListPresent(ctx, knowledge.Scope{
		WorldID:  tc.worldID,
		ActorID:  tc.player.ID,
		Location: here,
	}, holders)
	if err != nil {
		return nil, "", fmt.Errorf("list present things: %w", err)
	}
	if len(present) == 0 {
		return nil, "Здесь нет ничего, что можно было бы взять в руки.", nil
	}

	byID := make(map[domain.EntityID]*entity.Entity, len(present))
	candidates := make([]extraction.Candidate, 0, len(present))
	for _, e := range present {
		byID[e.ID] = e
		candidates = append(candidates, extraction.Candidate{
			ID:    string(e.ID),
			Name:  e.Name,
			Note:  truncateRunes(e.Gist, 80),
			Forms: s.candidateForms(e.Name, e.Aliases),
		})
	}
	// One grammar-bound resolution: the structural accelerator lands a named thing
	// («кружку» → кружка) without the model; a fuzzy description falls to it. The
	// present scope is the frame — hands reach only what is here.
	group, err := s.resolver.ResolveGroup(ctx, tc.worldID, mention, extraction.MentionWhat, candidates)
	if err != nil {
		return nil, "", err
	}
	if len(group) == 0 {
		return nil, "Здесь не видно такого — оглядись или спроси у людей.", nil
	}
	if e, ok := byID[domain.EntityID(group[0].ID)]; ok {
		return e, "", nil
	}
	return nil, "Здесь не видно такого.", nil
}

// ownerOf returns the entity's owning actor, nil when unowned.
func (s *TurnService) ownerOf(ctx context.Context, e *entity.Entity) *domain.ActorID {
	links, err := s.knowledge.Links(ctx, e.ID)
	if err != nil {
		return nil
	}
	for _, l := range links {
		if l.LinkType == entity.LinkOwner && l.SubjectType == entity.SubjectActor {
			id := domain.ActorID(l.SubjectID)
			return &id
		}
	}
	return nil
}

// executeTransfer is the deterministic handover: ownership relinks, the
// located_at pin lifts (the thing now travels with its holder), the world
// remembers the event.
func (s *TurnService) executeTransfer(
	ctx context.Context,
	tc *turnContext,
	thing *entity.Entity,
	from *domain.ActorID,
	to domain.ActorID,
	price int,
	kind event.TransferKind,
) error {
	if err := s.knowledge.TransferOwnership(ctx, thing.ID, to); err != nil {
		return fmt.Errorf("transfer ownership: %w", err)
	}

	evt := event.NewGameEvent(
		event.EventTypeEntityTransferred,
		to, tc.player.GetCurrentLocation(), tc.worldID, tc.tick,
		event.EntityTransferEventData{
			EntityID:    thing.ID.String(),
			EntityName:  thing.Name,
			FromActorID: from,
			ToActorID:   to,
			Price:       price,
			Kind:        kind,
		},
	)
	if err := s.events.Append(ctx, evt); err != nil {
		return fmt.Errorf("append transfer event: %w", err)
	}
	return nil
}

// transferNarrative dresses a settled pickup in narrator prose, degrading to
// the closed fallback line. The transfer is ALREADY executed — the fact says
// so, and the renderer cannot describe a failure to grab.
func (s *TurnService) transferNarrative(ctx context.Context, tc *turnContext, action extraction.ParsedPlayerAction, fallback string) *actionOutcome {
	deed := strings.TrimSpace(action.Topic)
	if deed == "" {
		deed = "взять вещь"
	} else {
		deed = "взять: " + deed
	}
	narrative, err := s.narrator.NarratePlayerAction(ctx,
		s.narrateFactsInput(ctx, tc, deed, []string{fallback}, action.Topic, false))
	if err != nil || strings.TrimSpace(narrative) == "" {
		return &actionOutcome{narrative: fallback}
	}
	return &actionOutcome{narrative: narrative}
}

// shiftRelationship moves an NPC's standing toward the player through the shared
// relationship primitive. Many callers use it (a gift, a kindness, an assault, a
// destruction), so the reason follows the SIGN of the shift — a souring is hostility, a
// warming is kindness. The old fixed «дар» (a gift) was right when this had a single
// gift caller, but once it was reused for hostile shifts it mislabelled every assault as
// a present — poisoning any memory or narration keyed on the relationship's reason.
func (s *TurnService) shiftRelationship(ctx context.Context, tc *turnContext, npc *actor.Actor, delta int) {
	reason := "доброта"
	if delta < 0 {
		reason = "враждебность"
	}
	events := social.ShiftRelationship(npc, tc.player, delta, reason, tc.worldID, tc.tick)
	for _, evt := range events {
		if err := s.events.Append(ctx, evt); err != nil {
			s.logger.Warn("append relationship shift failed", zap.Error(err))
		}
	}
	if err := s.actors.Update(ctx, npc); err != nil {
		s.logger.Warn("persist relationship shift failed", zap.Error(err))
	}
}

package knowledge

import (
	"context"
	"errors"
	"strings"

	"github.com/dnd-llm/dnd-llm/internal/domain"
	"github.com/dnd-llm/dnd-llm/internal/domain/entity"
	"github.com/dnd-llm/dnd-llm/internal/domain/event"
	domllm "github.com/dnd-llm/dnd-llm/internal/domain/llm"
	"github.com/dnd-llm/dnd-llm/internal/infrastructure/persistence"
	"github.com/dnd-llm/dnd-llm/internal/infrastructure/search"
	"github.com/google/uuid"
	"go.uber.org/zap"
)

// The crystallizer births mundane items "out of thin air": the player reached
// for a thing the scene does not list, and the location's AUTHORED prop fund
// says the place has it («хватаю факел» in a tavern). Fully deterministic —
// the fund is fixture data, the lookup is a stem match, the birth is a stub
// insert. Zero LLM calls: what a place has is authored world content, not a
// runtime judgement. Crystallized items are runtime state: the reseed wipe
// erases them with the incarnation.

// Crystallizer births fund props as entities at the player's reach.
type Crystallizer struct {
	entities entity.Repository
	events   event.EventStore
	searcher *search.EntitySearcher
	graph    persistence.GraphStore // optional, best-effort mirror
	morph    NameWarmer             // optional
	logger   *zap.Logger
}

// NewCrystallizer builds a Crystallizer. searcher, graph and morph may be nil.
func NewCrystallizer(
	entities entity.Repository,
	events event.EventStore,
	searcher *search.EntitySearcher,
	graph persistence.GraphStore,
	morph NameWarmer,
	logger *zap.Logger,
) *Crystallizer {
	if logger == nil {
		logger = zap.NewNop()
	}
	return &Crystallizer{
		entities: entities, events: events,
		searcher: searcher, graph: graph, morph: morph, logger: logger,
	}
}

// CrystallizeInput is one reach-for-a-thing in a concrete scene.
type CrystallizeInput struct {
	WorldID     domain.WorldID
	Location    domain.LocationID
	Mention     string // слова игрока
	Props       []Prop // авторский фонд локации (PropsFromState)
	SourceActor domain.ActorID
	Tick        domain.Tick
}

// TryCrystallize looks the mention up in the location's prop fund and, on a
// match, births a stub entity here. Returns nil when the fund has no such
// thing or a twin already exists in the world (the unique-name floor; reusing
// the twin would teleport someone's thing). Failures degrade to nil with a
// log — a refused crystallization is never worth failing the player's turn.
func (c *Crystallizer) TryCrystallize(ctx context.Context, in CrystallizeInput) *entity.Entity {
	mention := strings.TrimSpace(in.Mention)
	if mention == "" || c.entities == nil || len(in.Props) == 0 {
		return nil
	}

	prop := MatchProp(in.Props, mention)
	if prop == nil {
		return nil
	}
	return c.CrystallizeProp(ctx, in, prop)
}

// CrystallizeProp births a stub for ONE specific prop of the fund, skipping the
// mention lookup — the path a non-player reach takes (the spreading fire reaching
// the place's authored furniture). Returns nil on the same floors as
// TryCrystallize (a twin name already exists, an invalid fund entry). The mention
// lookup in TryCrystallize is just a way to choose the prop; both paths share
// this one birth so a crystallized thing is identical however the world reached it.
func (c *Crystallizer) CrystallizeProp(ctx context.Context, in CrystallizeInput, prop *Prop) *entity.Entity {
	if c.entities == nil || prop == nil {
		return nil
	}

	stub := &entity.Entity{
		ID:        domain.NewEntityID(),
		WorldID:   in.WorldID,
		Kind:      entity.KindItem,
		Name:      prop.Name,
		Aliases:   prop.Aliases,
		Gist:      strings.TrimSpace(prop.Gist),
		Lifecycle: entity.LifecycleStub,
		Origin:    entity.OriginCrystallized,
		Category:  entity.Category(prop.Category),
		Value:     prop.Value,
	}
	// The prop's material flammability lands on the entity, so the tick's fire
	// spread reads a per-thing judgment (wooden stool burns, clay bowl doesn't)
	// rather than guessing from the category.
	stub.SetFlammable(prop.Flammable)
	if stub.Gist == "" {
		stub.Gist = "обычная вещь этого места"
	}
	if err := stub.Validate(); err != nil {
		// An invalid fund entry is an authoring error — loud, not silent.
		c.logger.Warn("prop fund entry is invalid", zap.String("name", prop.Name), zap.Error(err))
		return nil
	}
	if err := c.entities.Save(ctx, stub); err != nil {
		if errors.Is(err, entity.ErrDuplicateName) {
			c.logger.Info("crystallization refused: twin name exists", zap.String("name", prop.Name))
			return nil
		}
		c.logger.Warn("crystallized stub save failed", zap.String("name", prop.Name), zap.Error(err))
		return nil
	}

	if err := c.entities.AddLink(ctx, entity.Link{
		EntityID:    stub.ID,
		LinkType:    entity.LinkLocatedAt,
		SubjectType: entity.SubjectLocation,
		SubjectID:   in.Location.String(),
	}); err != nil {
		c.logger.Warn("crystallized stub link failed", zap.String("name", prop.Name), zap.Error(err))
	}

	c.journal(ctx, stub, in.SourceActor, in.Tick)
	c.index(ctx, in.WorldID, stub)
	c.mirror(ctx, stub)
	if c.morph != nil {
		c.morph.WarmAsync(stub.Name)
	}

	c.logger.Info("prop crystallized from the location fund",
		zap.String("name", stub.Name),
		zap.String("category", string(stub.Category)),
		zap.Int("value", stub.Value))
	return stub
}

// journal appends the lifecycle event, world-as-actor (the same pattern the
// materializer uses); best-effort — the entities table is the state of record.
func (c *Crystallizer) journal(ctx context.Context, e *entity.Entity, source domain.ActorID, tick domain.Tick) {
	if c.events == nil {
		return
	}
	if tick.IsZero() {
		tick = 1
	}
	src := &source
	if source.IsZero() {
		src = nil
	}
	evt := event.NewGameEvent(
		event.EventTypeEntityCreated,
		domain.ActorID(e.WorldID), domain.LocationID(e.WorldID), e.WorldID, tick,
		event.EntityLifecycleEventData{
			EntityID:      e.ID.String(),
			Name:          e.Name,
			Kind:          string(e.Kind),
			Gist:          e.Gist,
			Origin:        string(e.Origin),
			SourceActorID: src,
		},
	)
	if err := c.events.Append(ctx, evt); err != nil {
		c.logger.Warn("crystallized journal append failed", zap.String("entity", e.Name), zap.Error(err))
	}
}

// index registers the newborn in the search corpus so the very next mention
// grounds to it instead of crystallizing again.
func (c *Crystallizer) index(ctx context.Context, worldID domain.WorldID, e *entity.Entity) {
	if c.searcher == nil {
		return
	}
	searchables := []domllm.SearchableEntity{searchableFromEntity(e)}
	c.searcher.AddToLocalCache(worldID.String(), searchables)
	wid, err := uuid.Parse(worldID.String())
	if err != nil {
		return
	}
	if err := c.searcher.IndexEntities(ctx, searchables, &wid, nil); err != nil {
		c.logger.Warn("crystallized vector indexing failed", zap.Error(err))
	}
}

// mirror writes the graph reflection, best-effort.
func (c *Crystallizer) mirror(ctx context.Context, e *entity.Entity) {
	if c.graph == nil {
		return
	}
	node := persistence.GraphNode{
		ID:     persistence.NodeID(e.ID),
		Type:   persistence.NodeTypeEntity,
		Labels: []string{string(e.Kind)},
		Properties: map[string]interface{}{
			"name": e.Name,
			"gist": e.Gist,
			"kind": string(e.Kind),
		},
	}
	if err := c.graph.AddNode(ctx, node); err != nil {
		if uerr := c.graph.UpdateNode(ctx, node.ID, node.Properties); uerr != nil {
			c.logger.Warn("crystallized graph mirror failed", zap.String("entity", e.Name), zap.Error(uerr))
		}
	}
}

